-- بيانات مقرر فيزياء 1 (المقرر 101، قيد الإعداد) — الجزء 2 من 2. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-phys1-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L3-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بمنحنى (الموقع – الزمن)؟', null, null, '["رسم بياني يُمثَّل فيه الموقع على المحور الأفقي والزمن على المحور الرأسي","رسم بياني يُمثَّل فيه الزمن على المحور الأفقي والموقع على المحور الرأسي","صورة توضح شكل الطريق الذي سلكه الجسم أثناء حركته","رسم بياني يُمثَّل فيه الزمن على المحور الأفقي والسرعة على المحور الرأسي"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 38 — منحنى (الموقع – الزمن)'),
('mcq', 2, 'نقطة على منحنى (الموقع – الزمن) لعدّاء إحداثياتها (3.0 s, 15.0 m). ماذا تعني هذه النقطة؟', null, null, '["قطع العدّاء 15.0 m في كل 3.0 s من حركته","كان العدّاء على بُعد 3.0 m من نقطة الأصل عند اللحظة 15.0 s","كان العدّاء على بُعد 15.0 m من نقطة الأصل عند اللحظة 3.0 s","كانت سرعة العدّاء 15.0 m/s عند اللحظة 3.0 s"]'::jsonb, 'فهم', 'تفسير نقطة على منحنى', 'سهل', 'الكتاب ص 38 — منحنى (الموقع – الزمن)'),
('mcq', 3, 'أيّ المعلومات الآتية يمكن الحصول عليها مباشرة من منحنى (الموقع – الزمن) لجسم يتحرك في خط مستقيم؟', null, null, '["شكل الطريق الذي سلكه الجسم، أكان صاعدًا أم هابطًا","موقع الجسم عند أي لحظة خلال فترة القياس","مقدار كتلة الجسم الذي يتحرك على الطريق","القوة المؤثرة في الجسم والتي سببت حركته"]'::jsonb, 'فهم', 'دلالة المنحنى', 'سهل', 'الكتاب ص 38 — منحنى (الموقع – الزمن)'),
('mcq', 4, 'يمثل المنحنى الآتي حركة دراجة على طريق مستقيم. ماذا تمثل النقطة التي يقطع عندها الخط البياني المحور الرأسي؟', null, '[{"src":"qimg/phys1/c2l3-o01-start.svg","alt":"منحنى (الموقع – الزمن): المحور الأفقي الزمن (s) من 0 إلى 6 بتدريج 1، والمحور الرأسي الموقع (m) من 0 إلى 60 بتدريج 10. خط مستقيم صاعد يبدأ من النقطة (0, 20) وينتهي عند النقطة (6, 50)."}]'::jsonb, '["المسافة الكلية التي قطعتها الدراجة خلال 6 s","الزمن الذي استغرقته الدراجة لتبدأ الحركة","إزاحة الدراجة خلال الثانية الأولى","موقع الدراجة عند اللحظة $t = 0$ أي بداية التوقيت"]'::jsonb, 'فهم', 'تفسير نقطة على منحنى', 'متوسط', 'الكتاب ص 38 — منحنى (الموقع – الزمن)'),
('mcq', 5, 'على منحنى (الموقع – الزمن) لسيارة، ظهرت عند اللحظة 2.0 s قيمة سالبة للموقع هي $-30\ \text{m}$. ماذا تعني هذه القيمة؟', null, null, '["أن السيارة كانت على بُعد 30 m من نقطة الأصل في الاتجاه السالب","أن السيارة كانت تتحرك إلى الخلف في الزمن","أن القراءة خاطئة؛ لأن الموقع لا يمكن أن يكون سالبًا","أن السيارة قطعت مسافة 30 m خلال 2.0 s"]'::jsonb, 'فهم', 'تفسير قيمة سالبة', 'متوسط', 'الكتاب ص 38 — منحنى (الموقع – الزمن)'),
('mcq', 6, 'بدأ أحمد السير من نقطة الأصل، وبعد 0.25 h بدأ صديقه نبيل السير من النقطة نفسها، ومُثّلت حركتاهما على منحنى (الموقع – الزمن) واحد. ماذا يعني أن خط نبيل يبدأ عند النقطة (0.25 h, 0 km)؟', null, null, '["أن نبيلًا كان على بُعد 0.25 km من نقطة الأصل عند بداية التوقيت","أن نبيلًا بقي في نقطة الأصل حتى اللحظة 0.25 h ثم بدأ الحركة","أن نبيلًا قطع 0.25 km قبل أن يبدأ أحمد السير","أن نبيلًا بدأ السير قبل أحمد بمقدار 0.25 h"]'::jsonb, 'فهم', 'تفسير نقطة بداية الخط', 'متوسط', 'الكتاب ص 41 — مسائل تدريبية (السؤال 18)'),
('mcq', 7, 'أيّ العبارات الآتية صحيحة بشأن تمثيل حركة أكثر من جسم بمنحنى (الموقع – الزمن)؟', null, null, '["لا يمكن أن يمثل المنحنى الواحد إلا حركة جسم واحد","يمكن تمثيل حركة جسمين على المنحنى نفسه فقط إذا بدآ من الموقع نفسه","يمكن تمثيل حركة أكثر من جسم في منحنى واحد بخط بياني لكل جسم","عند تمثيل جسمين على منحنى واحد يجب أن يكون لكل منهما محور زمن مختلف"]'::jsonb, 'فهم', 'خصائص المنحنى', 'متوسط', 'الكتاب ص 40، 42 — دراسة حركة عدة أجسام'),
('essay', 1, 'وضّح المقصود بمنحنى (الموقع – الزمن)، وبيّن كيف تمثل عليه بيانات جدول يتضمن مواقع عدّاء عند أزمنة مختلفة.', null, null, null, 'فهم', 'شرح مفهوم', 'سهل', 'الكتاب ص 38 — منحنى (الموقع – الزمن)'),
('essay', 2, 'يبين الجدول الآتي مواقع عدّاء يتحرك على مضمار مستقيم. فسّر ما تعنيه النقطة (4.0 s, 20.0 m) على منحنى (الموقع – الزمن) لهذا العدّاء، ثم فسّر ما تمثله نقاط الخط البياني الواقعة بين نقاط الجدول، مثل النقطة عند 4.5 s.', '{"headers":["الزمن (s)","الموقع (m)"],"rows":[["0.0","0.0"],["1.0","5.0"],["2.0","10.0"],["3.0","15.0"],["4.0","20.0"],["5.0","25.0"],["6.0","30.0"]]}'::jsonb, null, null, 'فهم', 'تفسير منحنى', 'متوسط', 'الكتاب ص 38 — منحنى (الموقع – الزمن)'),
('essay', 3, 'قال طالب: «منحنى (الموقع – الزمن) يخبرنا أين كان الجسم فقط، ولا يخبرنا متى كان هناك». قوّم هذه العبارة، ووضّح ما يقدمه المنحنى من معلومات عن حركة الجسم.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 38 — منحنى (الموقع – الزمن)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L3-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'منحنى (الموقع – الزمن) رسم بياني تُحدَّد فيه إحداثيات الزمن على المحور الأفقي (x) وإحداثيات الموقع على المحور الرأسي (y)، ثم يُرسم خط يمر بالنقاط.', '["هذا تبديل للمحورين؛ فالزمن يوضع على المحور الأفقي والموقع على الرأسي.","","المنحنى ليس تصويرًا لمسار الحركة؛ بل يبين كيف يتغير الموقع مع الزمن.","المحور الرأسي في هذا المنحنى يمثل الموقع لا السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.240Z"}'::jsonb),
('mcq', 2, 2, 'الإحداثي الأفقي للنقطة هو الزمن (3.0 s) والإحداثي الرأسي هو الموقع (15.0 m)؛ أي أن العدّاء كان في الموقع 15.0 m عند اللحظة 3.0 s.', '["النقطة الواحدة تعطي موقعًا عند لحظة واحدة، ولا تخبرنا بما يقطعه العدّاء في كل فترة.","هذا تبديل لمعنى الإحداثيين؛ فالقيمة الأفقية زمن والرأسية موقع.","","المحور الرأسي يمثل الموقع بوحدة m، وليس السرعة بوحدة m/s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.241Z"}'::jsonb),
('mcq', 3, 1, 'يبين منحنى (الموقع – الزمن) موقع الجسم عند كل لحظة، ويمكن منه تحديد إزاحة الجسم خلال فترات زمنية محددة.', '["المنحنى لا يصور مسار الحركة؛ فالخط المائل لا يعني أن الطريق مائل.","","المنحنى يربط الموقع بالزمن فقط، ولا يحمل أي معلومة عن كتلة الجسم.","المنحنى يصف الحركة فقط ولا يبيّن القوى المسببة لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.241Z"}'::jsonb),
('mcq', 4, 3, 'عند تقاطع الخط مع المحور الرأسي تكون $t = 0$؛ فالإحداثي الرأسي لهذه النقطة (20 m) هو موقع الدراجة لحظة بدء التوقيت، أي موقعها الابتدائي.', '["المسافة خلال 6 s تحتاج إلى موقعين (عند 0 s وعند 6 s)، لا إلى نقطة واحدة.","المحور الرأسي يمثل الموقع لا الزمن؛ والزمن عند هذه النقطة صفر.","الإزاحة تحتاج إلى فرق موقعين عند لحظتين، والنقطة تعطي موقعًا واحدًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.241Z"}'::jsonb),
('mcq', 5, 0, 'الموقع كمية يمكن أن تكون موجبة أو سالبة؛ والإشارة السالبة تعني أن الجسم في الجهة السالبة من نقطة الأصل، والمقدار 30 m هو بُعده عنها.', '["","الزمن على المحور الأفقي يتزايد دائمًا، والإشارة السالبة تخص الموقع لا الزمن.","الموقع يمكن أن يكون سالبًا عندما يكون الجسم في الاتجاه السالب من نقطة الأصل.","القيمة على المحور الرأسي موقع لحظي، وليست مسافة مقطوعة خلال فترة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.241Z"}'::jsonb),
('mcq', 6, 1, 'النقطة (0.25 h, 0 km) تعني أن موقع نبيل عند اللحظة 0.25 h هو نقطة الأصل؛ أي أنه بدأ الحركة من نقطة الأصل بعد مرور 0.25 h من بداية التوقيت.', '["القيمة 0.25 إحداثي زمني بوحدة h، وليست موقعًا بوحدة km.","","موقع نبيل عند هذه النقطة صفر؛ فهو لم يقطع أي مسافة بعد.","خط نبيل يبدأ عند 0.25 h على محور الزمن، أي بعد بدء أحمد (عند 0 h) لا قبله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.241Z"}'::jsonb),
('mcq', 7, 2, 'يمكن تمثيل حركة أكثر من جسم في منحنى (الموقع – الزمن) واحد، فيُرسم لكل جسم خطه البياني على المحورين نفسيهما، وهذا يسهل المقارنة بين حركتيهما.', '["المنحنى الواحد يمكن أن يحمل خطوطًا بيانية لعدة أجسام.","لا يشترط أن تبدأ الأجسام من الموقع نفسه؛ فلكل خط نقطة بداية خاصة به.","","تُمثَّل الأجسام كلها على محوري الزمن والموقع أنفسهما ليمكن مقارنتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.241Z"}'::jsonb),
('essay', 1, null::int, null, null, 'منحنى (الموقع – الزمن) رسم بياني يبين موقع الجسم عند كل لحظة زمنية. لتمثيل بيانات الجدول: نضع الزمن $t$ على المحور الأفقي والموقع $\boldsymbol{d}$ على المحور الرأسي، ونختار تدريجًا مناسبًا لكل محور، ثم نحدد نقطة لكل زوج (الزمن، الموقع) من الجدول، وأخيرًا نرسم أفضل خط مستقيم يمر بأغلب النقاط (خط المواءمة الأفضل).', '["تعريف المنحنى: رسم بياني يبين موقع الجسم بدلالة الزمن","الزمن على المحور الأفقي والموقع على المحور الرأسي","تعيين نقطة لكل زوج من الجدول","رسم خط المواءمة الأفضل"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"تحديد المحورين","marks":1},{"element":"تعيين النقاط","marks":0.5},{"element":"خط المواءمة الأفضل","marks":0.5}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["تبديل المحورين بوضع الموقع على المحور الأفقي.","وصف المنحنى بأنه صورة لمسار الحركة.","توصيل النقاط بخطوط متكسرة بدل خط المواءمة الأفضل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.241Z"}'::jsonb),
('essay', 2, null::int, null, null, 'النقطة (4.0 s, 20.0 m) تعني أن العدّاء كان على بُعد 20.0 m من نقطة البداية عند اللحظة 4.0 s. أما نقاط الخط الواقعة بين نقاط الجدول فتمثل مواقع العدّاء عند لحظات لم تُقَس مباشرة؛ فالخط يبين موقعه عند أي لحظة، فمثلًا عند 4.5 s يكون موقعه 22.5 m تقريبًا. لذلك يقدم المنحنى معلومات عن الحركة حتى لو لم تتوافر بيانات مباشرة لتلك اللحظات.', '["الإحداثي الأفقي زمن والرأسي موقع","معنى النقطة: موقع 20.0 m عند 4.0 s","النقاط بين القياسات تمثل مواقع عند لحظات لم تُقَس","قراءة 22.5 m عند 4.5 s"]'::jsonb, '["عند $t = 4.5\\ \\text{s}$ يقع الخط في منتصف المسافة بين 20.0 m و25.0 m: $\\boldsymbol{d} \\approx 22.5\\ \\text{m}$"]'::jsonb, '[{"element":"معنى النقطة","marks":1},{"element":"تفسير النقاط البينية","marks":1},{"element":"قراءة الموقع عند 4.5 s","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["قراءة النقطة على أنها 4.0 m عند 20.0 s.","الاعتقاد أن المنحنى لا يعطي معلومات إلا عند نقاط الجدول."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.242Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فكل نقطة على المنحنى لها إحداثيان: زمن (أفقي) وموقع (رأسي)، فهي تخبرنا أين كان الجسم ومتى كان هناك معًا. ويمكن من المنحنى تحديد موقع الجسم عند أي لحظة، وتحديد اللحظة التي يكون فيها في موقع معين، وتحديد إزاحته خلال فترة زمنية، ومقارنة حركة عدة أجسام إذا مُثّلت على المنحنى نفسه.', '["الحكم: العبارة غير صحيحة","كل نقطة تربط موقعًا بلحظة زمنية","المعلومات المستفادة: الموقع عند لحظة، واللحظة عند موقع، والإزاحة خلال فترة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"التعليل بإحداثيي النقطة","marks":1},{"element":"ذكر ما يقدمه المنحنى","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الموافقة على العبارة.","ذكر أن المنحنى يبين شكل المسار."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.242Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L3-O01') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L3-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين الجدول مواقع كرة تتدحرج على أرض مستوية. أيّ المنحنيات الأربعة في الشكل الآتي هو منحنى (الموقع – الزمن) الصحيح لبيانات الجدول؟', '{"headers":["الزمن (s)","الموقع (m)"],"rows":[["0.0","10.0"],["1.0","15.0"],["2.0","20.0"],["3.0","25.0"],["4.0","30.0"]]}'::jsonb, '[{"src":"qimg/phys1/c2l3-o02-panels.svg","alt":"أربعة منحنيات مرقمة. المنحنى (1): الزمن (s) أفقيًا من 0 إلى 4 والموقع (m) رأسيًا من 0 إلى 40؛ خط مستقيم من (0, 30) إلى (4, 10). المنحنى (2): المحوران نفساهما؛ خط مستقيم من (0, 10) إلى (4, 30). المنحنى (3): الموقع (m) أفقيًا من 0 إلى 40 والزمن (s) رأسيًا من 0 إلى 4؛ خط مستقيم من (10, 0) إلى (30, 4). المنحنى (4): الزمن (s) أفقيًا من 0 إلى 4 والموقع (m) رأسيًا من 0 إلى 40؛ خط مستقيم من (0, 0) إلى (4, 20)."}]'::jsonb, '["المنحنى (4)","المنحنى (2)","المنحنى (1)","المنحنى (3)"]'::jsonb, 'تطبيق', 'اختيار التمثيل البياني لجدول', 'متوسط', 'الكتاب ص 38 — رسم منحنى (الموقع – الزمن) وخط المواءمة الأفضل'),
('mcq', 2, 'ما الترتيب الصحيح لخطوات رسم منحنى (الموقع – الزمن) من جدول بيانات؟', null, null, '["تحديد المحورين (الزمن أفقيًا والموقع رأسيًا)، ثم تعيين النقاط، ثم رسم خط المواءمة الأفضل","رسم خط المواءمة الأفضل أولًا، ثم تحديد المحورين (الزمن أفقيًا والموقع رأسيًا)، ثم تعيين النقاط عليه","تعيين النقاط، ثم توصيل كل نقطة بالتي تليها، ثم تحديد المحورين","تحديد المحورين (الموقع أفقيًا والزمن رأسيًا)، ثم تعيين النقاط، ثم توصيلها"]'::jsonb, 'فهم', 'ترتيب خطوات إجراء', 'سهل', 'الكتاب ص 38 — رسم منحنى (الموقع – الزمن) وخط المواءمة الأفضل'),
('mcq', 3, 'ما المقصود بخط المواءمة الأفضل عند رسم منحنى (الموقع – الزمن)؟', null, null, '["خط متكسر يصل كل نقطة بالنقطة التي تليها مباشرة","خط مستقيم يصل النقطة الأولى بالنقطة الأخيرة فقط","خط مستقيم يبدأ دائمًا من نقطة الأصل مهما كانت النقاط","أفضل خط مستقيم يمر بأغلب النقاط أو بالقرب منها"]'::jsonb, 'فهم', 'تعريف مفهوم', 'سهل', 'الكتاب ص 38 — رسم منحنى (الموقع – الزمن) وخط المواءمة الأفضل'),
('mcq', 4, 'عيّن طالب مواقع جسم بدلالة الزمن (النقاط السوداء في الشكل الآتي)، ثم رسم أربعة خطوط مرقمة. أيّ الخطوط يمثل خط المواءمة الأفضل لهذه النقاط؟', null, '[{"src":"qimg/phys1/c2l3-o02-bestfit.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 6 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 40 بتدريج 5. ست نقاط سوداء عند (1, 2.5) و(2, 12.5) و(3, 14) و(4, 22) و(5, 26.5) و(6, 27.5). الخط 1 (أزرق متصل) مستقيم من (0, 0) إلى (6, 30). الخط 2 (برتقالي منقط) خط متكسر يصل النقاط الست بالترتيب. الخط 3 (أخضر متصل) مستقيم من (0, 10) إلى (6, 20). الخط 4 (بنفسجي متقطع) مستقيم من (0, 0) إلى (4.5, 36)."}]'::jsonb, '["الخط 3","الخط 4","الخط 1","الخط 2"]'::jsonb, 'تطبيق', 'قراءة رسم بياني', 'متوسط', 'الكتاب ص 38 — رسم منحنى (الموقع – الزمن) وخط المواءمة الأفضل'),
('mcq', 5, 'يمثل الشكل الآتي النموذج الجسيمي النقطي لطفل يزحف على أرضية غرفة، والفترة الزمنية بين كل نقطتين متتاليتين 1 s، وأول نقطة عند اللحظة 0 s. أيّ النقاط الآتية تقع على منحنى (الموقع – الزمن) لحركة الطفل؟', null, '[{"src":"qimg/phys1/c2l3-o02-crawl.svg","alt":"نموذج جسيمي نقطي: تسع نقاط فوق محور الموقع (cm) المدرّج من 0 إلى 160 بتدريج 20، والنقاط عند 0 و20 و40 و60 و80 و100 و120 و140 و160 cm."}]'::jsonb, '["(80 s, 4 cm)","(4 s, 100 cm)","(4 s, 80 cm)","(5 s, 80 cm)"]'::jsonb, 'تطبيق', 'التحويل من نموذج جسيمي إلى منحنى', 'متوسط', 'الكتاب ص 42 — مراجعة 2-3 (السؤال 19)'),
('mcq', 6, 'يبين الجدول مواقع دراجة عند أزمنة مختلفة، ويبين الشكل الآتي النقاط التي عيّنها طالب لهذه البيانات. أيّ النقاط عيّنها الطالب خطأً؟', '{"headers":["الزمن (s)","الموقع (m)"],"rows":[["0","0"],["1","6"],["2","12"],["3","18"],["4","24"],["5","30"]]}'::jsonb, '[{"src":"qimg/phys1/c2l3-o02-misplot.svg","alt":"نقاط معيّنة على منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 5 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 36 بتدريج 3. النقاط عند (0, 0) و(1, 6) و(2, 12) و(3, 21) و(4, 24) و(5, 30)."}]'::jsonb, '["النقطة المقابلة للزمن 3 s","النقطة المقابلة للزمن 4 s","النقطة المقابلة للزمن 1 s","النقطة المقابلة للزمن 5 s"]'::jsonb, 'تحليل', 'اكتشاف خطأ في التمثيل', 'متوسط', 'الكتاب ص 38 — رسم منحنى (الموقع – الزمن) وخط المواءمة الأفضل'),
('mcq', 7, 'تبدأ سيارة الحركة من موقع يبعد 150 m عن نقطة الأصل في الاتجاه الموجب، وتتحرك نحو نقطة الأصل فتقطع مسافات متساوية في فترات زمنية متساوية، وتصل إليها عند 6.0 s. كيف يبدو منحنى (الموقع – الزمن) لحركتها؟', null, null, '["خط مستقيم يبدأ من النقطة (0 s, 0 m) ويصعد حتى النقطة (6.0 s, 150 m)","خط أفقي يبدأ من النقطة (0 s, 150 m) وينتهي عند النقطة (6.0 s, 150 m)","خط مستقيم يبدأ من النقطة (0 s, 0 m) وينخفض حتى النقطة $(6.0\\ \\text{s},\\ -150\\ \\text{m})$","خط مستقيم يبدأ من النقطة (0 s, 150 m) وينخفض ليقطع محور الزمن عند 6.0 s"]'::jsonb, 'تطبيق', 'وصف المنحنى من وصف لفظي', 'صعب', 'الكتاب ص 38 — رسم منحنى (الموقع – الزمن) وخط المواءمة الأفضل'),
('essay', 1, 'سجّل طلاب الزمن الذي تمر فيه سيارة أمام كل منهم، وكانت المسافة بين كل طالبين 20 m، فحصلوا على البيانات الواردة في الجدول. صف خطوات رسم منحنى (الموقع – الزمن) لهذه البيانات، وصف خط المواءمة الأفضل الناتج، ثم قدّر منه موقع السيارة عند اللحظة 3.5 s.', '{"headers":["الزمن (s)","الموقع (m)"],"rows":[["0.0","0"],["1.0","20"],["2.1","40"],["2.9","60"],["4.0","80"],["5.1","100"]]}'::jsonb, null, null, 'تطبيق', 'رسم منحنى من بيانات', 'متوسط', 'الكتاب ص 38 — رسم منحنى (الموقع – الزمن) وخط المواءمة الأفضل'),
('essay', 2, 'يمثل الشكل الآتي النموذج الجسيمي النقطي لحركة عدّاء، والفترة الزمنية بين كل نقطتين متتاليتين 2.0 s، وأول نقطة عند اللحظة 0.0 s. كوّن جدول (الموقع – الزمن) لهذه الحركة، ثم صف منحنى (الموقع – الزمن) الذي تحصل عليه، وحدد منه موقع العدّاء عند 5.0 s.', null, '[{"src":"qimg/phys1/c2l3-o02-e2.svg","alt":"نموذج جسيمي نقطي: ست نقاط فوق محور الموقع (m) المدرّج من 0 إلى 15 بتدريج 3، والنقاط عند 0 و3 و6 و9 و12 و15 m."}]'::jsonb, null, 'تطبيق', 'التحويل بين تمثيلات', 'متوسط', 'الكتاب ص 42 — مراجعة 2-3 (السؤالان 19 و24)'),
('essay', 3, 'غادرت السيارتان A وB المدرسة عندما كانت قراءة ساعة الإيقاف صفرًا، وتحركت A بسرعة منتظمة 75 km/h وB بسرعة منتظمة 100 km/h في الاتجاه نفسه. صف كيف ترسم منحنى (الموقع – الزمن) للسيارتين حتى 2.0 h، وحدد بُعد كل منهما عن المدرسة عند 2.0 h، ثم حدد من الرسم متى تمر كل منهما بمحطة وقود تبعد 150 km عن المدرسة.', null, null, null, 'تطبيق', 'رسم منحنيين', 'صعب', 'الكتاب ص 55 — تقويم الفصل (السؤال 52)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
