insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'بيانات الجدول تبدأ من الموقع 10.0 m عند 0.0 s ويزداد الموقع حتى 30.0 m عند 4.0 s، مع وضع الزمن على المحور الأفقي والموقع على الرأسي؛ وهذا ما يبينه المنحنى (2) الذي يمر بالنقطتين (0, 10) و(4, 30).', '["المنحنى (4) يبدأ من نقطة الأصل وينتهي عند 20 m؛ أي أنه أهمل الموقع الابتدائي 10.0 m.","","المنحنى (1) يبدأ من 30 m وينخفض إلى 10 m، فهو يعكس ترتيب البيانات زمنيًا.","المنحنى (3) وُضع فيه الموقع على المحور الأفقي والزمن على الرأسي، وهذا تبديل للمحورين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.242Z"}'::jsonb),
('mcq', 2, 0, 'نحدد أولًا المحورين وتدريجهما (الزمن على الأفقي والموقع على الرأسي)، ثم نعيّن مواقع الجسم بدلالة الزمن نقاطًا، ثم نرسم أفضل خط يمر بأغلب النقاط.', '["","لا يمكن رسم خط المواءمة الأفضل قبل تعيين النقاط التي يُرسم الخط بناءً عليها.","لا تُعيَّن النقاط قبل تحديد المحورين، ولا توصل النقاط بخطوط متكسرة بل يُرسم خط المواءمة الأفضل.","هذا الترتيب يبدّل المحورين، ويوصل النقاط بدل رسم خط المواءمة الأفضل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.242Z"}'::jsonb),
('mcq', 3, 3, 'بعد تعيين مواقع الجسم بدلالة الزمن نرسم أفضل خط مستقيم يمر بأغلب النقاط، ويسمى خط المواءمة الأفضل، ولا يشترط أن يمر بكل النقاط.', '["التوصيل بين النقاط المتتالية يعطي خطًا متكسرًا، وليس خط المواءمة الأفضل.","الاعتماد على نقطتين فقط يهمل بقية القياسات، وقد يبتعد الخط عن أغلب النقاط.","لا يشترط أن يمر الخط بنقطة الأصل؛ فالجسم قد يبدأ من موقع غير الصفر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.242Z"}'::jsonb),
('mcq', 4, 2, 'الخط 1 خط مستقيم يمر بين النقاط وبالقرب من أغلبها، بحيث تتوزع النقاط حوله على جانبيه؛ وهذه صفة خط المواءمة الأفضل.', '["الخط 3 يبتعد كثيرًا عن أغلب النقاط؛ فهو أقل ميلًا من اتجاه تزايد النقاط.","الخط 4 يمر بالقرب من نقطة واحدة فقط ويبتعد عن بقية النقاط.","","الخط 2 متكسر يصل النقاط المتتالية، وخط المواءمة الأفضل خط مستقيم واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.243Z"}'::jsonb),
('mcq', 5, 2, 'كل نقطة تبعد 20 cm عن سابقتها وتفصلها عنها 1 s؛ فالنقطة الخامسة (عند 4 s) تقع عند الموقع 80 cm، ومنها النقطة (4 s, 80 cm).', '["هذا تبديل للإحداثيين؛ فالزمن 4 s والموقع 80 cm.","الموقع 100 cm يقابل اللحظة 5 s لا 4 s.","","عُدّت النقطة الأولى عند 1 s بدل 0 s، فزاد الزمن ثانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:34:59.243Z"}'::jsonb),
('mcq', 6, 0, 'وفق الجدول موقع الدراجة عند 3 s هو 18 m، لكن الطالب عيّنها عند 21 m؛ أما بقية النقاط فتطابق الجدول.', '["","النقطة عند 4 s معيّنة عند 24 m وهو ما يطابق الجدول.","النقطة عند 1 s معيّنة عند 6 m وهو ما يطابق الجدول.","النقطة عند 5 s معيّنة عند 30 m وهو ما يطابق الجدول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.243Z"}'::jsonb),
('mcq', 7, 3, 'موقع السيارة الابتدائي 150 m، ويتناقص بانتظام حتى يصبح صفرًا عند 6.0 s؛ فالخط مستقيم يبدأ من (0 s, 150 m) وينتهي عند (6.0 s, 0 m) على محور الزمن.', '["هذا الخط يمثل جسمًا يبدأ من نقطة الأصل ويبتعد عنها، وهو عكس الحركة الموصوفة.","الخط الأفقي يمثل جسمًا ساكنًا يبقى في الموقع نفسه، والسيارة تتحرك.","هذا الخط يبدأ من نقطة الأصل، والسيارة بدأت من 150 m وتوقفت حركتها الموصوفة عند نقطة الأصل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.243Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) نرسم المحور الأفقي للزمن بتدريج مناسب (مثلًا من 0 إلى 6 s) والمحور الرأسي للموقع (من 0 إلى 120 m). 2) نعيّن النقاط الست من الجدول. 3) نلاحظ أن النقاط لا تقع تمامًا على خط واحد بسبب أخطاء القياس، فنرسم أفضل خط مستقيم يمر بأغلب النقاط أو قريبًا منها، فيبدأ من نقطة الأصل تقريبًا ويمر قرب النقطة (5.0 s, 100 m). 4) من الخط عند 3.5 s نجد الموقع تقريبًا 70 m.', '["تحديد المحورين: الزمن أفقيًا والموقع رأسيًا بتدريج مناسب","تعيين النقاط","رسم خط مستقيم يمر بأغلب النقاط لا خط متكسر","تقدير الموقع عند 3.5 s ≈ 70 m"]'::jsonb, '["الخط يمر قرب (0, 0) و(5.0 s, 100 m)، فيزداد الموقع 20 m تقريبًا لكل 1 s","عند 3.5 s: الموقع ≈ 70 m"]'::jsonb, '[{"element":"المحوران والتدريج","marks":1},{"element":"تعيين النقاط","marks":1},{"element":"خط المواءمة الأفضل","marks":1},{"element":"قراءة الموقع","marks":1}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["توصيل النقاط بخط متكسر.","وضع الزمن على المحور الرأسي.","اختيار تدريج غير منتظم للمحورين."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.243Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الجدول: الزمن 0.0 و2.0 و4.0 و6.0 و8.0 و10.0 s، يقابلها الموقع 0 و3 و6 و9 و12 و15 m. عند تعيين هذه النقاط (الزمن أفقيًا والموقع رأسيًا) تقع على خط مستقيم يبدأ من نقطة الأصل وينتهي عند (10.0 s, 15 m). ومن الخط عند 5.0 s يكون الموقع 7.5 m.', '["جدول صحيح من ستة أزواج","تعيين النقاط بمحورين صحيحين","المنحنى خط مستقيم من (0, 0) إلى (10.0 s, 15 m)","الموقع عند 5.0 s = 7.5 m"]'::jsonb, '["كل نقطة تزيد 3 m على سابقتها وتليها بـ 2.0 s","5.0 s تقع في منتصف الفترة بين 4.0 s و6.0 s، فالموقع في منتصف المسافة بين 6 m و9 m: 7.5 m"]'::jsonb, '[{"element":"الجدول","marks":1},{"element":"وصف المنحنى","marks":1},{"element":"الموقع عند 5.0 s","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["اعتبار الفترة الزمنية 1 s بدل 2.0 s.","بدء الزمن من 2.0 s عند النقطة الأولى."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:34:59.244Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نضع الزمن (h) على المحور الأفقي من 0 إلى 2.0 h، والموقع (km) على الرأسي من 0 إلى 200 km، ونعتبر المدرسة نقطة الأصل. خط A مستقيم يبدأ من (0, 0) ويزداد 75 km كل ساعة فيصل إلى (2.0 h, 150 km). وخط B مستقيم يبدأ من (0, 0) ويصل إلى (2.0 h, 200 km). عند 2.0 h تبعد A مسافة 150 km وB مسافة 200 km. وبرسم خط أفقي عند 150 km يقطع خط B عند 1.5 h وخط A عند 2.0 h؛ فتمر B بالمحطة عند 1.5 h وA عند 2.0 h.', '["اختيار المحورين ونقطة الأصل","خط A من (0, 0) إلى (2.0 h, 150 km)","خط B من (0, 0) إلى (2.0 h, 200 km)","B تمر بالمحطة عند 1.5 h وA عند 2.0 h"]'::jsonb, '["موقع A عند 2.0 h: 75 × 2.0 = 150 km","موقع B عند 2.0 h: 100 × 2.0 = 200 km","B تصل 150 km عند 150 ÷ 100 = 1.5 h","A تصل 150 km عند 150 ÷ 75 = 2.0 h"]'::jsonb, '[{"element":"المحوران","marks":1},{"element":"الخطان صحيحان","marks":1},{"element":"الموقعان عند 2.0 h","marks":1},{"element":"زمنا المرور بالمحطة","marks":1}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["رسم الخطين بالميل نفسه.","قسمة الزمن على المسافة.","قراءة زمن A وB بالعكس."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.244Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
