('mcq', 3, 'أيّ العبارات الآتية تعبّر عن موقع لحظي لعدّاء يتحرك على مضمار مستقيم؟', null, null, '["قطع العدّاء 22.5 m خلال 4.5 s من بدء حركته","كان العدّاء على بُعد 22.5 m من نقطة البداية عند 4.5 s","استغرق العدّاء 4.5 s ليقطع 22.5 m من المضمار","تحرك العدّاء مسافة 5.0 m في كل ثانية واحدة من زمن حركته"]'::jsonb, 'فهم', 'تمييز مفهوم', 'متوسط', 'الكتاب ص 38 — الموقع اللحظي'),
('mcq', 4, 'لماذا يُعرَّف الموقع اللحظي بأنه موقع الجسم عند لحظة زمنية تؤول إلى الصفر؟', null, null, '["لأن الجسم يكون ساكنًا دائمًا عند تلك اللحظة","لأن الموقع اللحظي يساوي صفرًا دائمًا عند تلك اللحظة","لأن الموقع اللحظي لا يُقاس إلا عند بداية التوقيت","لأن موقع الجسم المتحرك يتغير، فيُحدَّد عند لحظة واحدة"]'::jsonb, 'فهم', 'تعليل', 'صعب', 'الكتاب ص 38 — الموقع اللحظي'),
('mcq', 5, 'كيف يُمثَّل الموقع اللحظي لجسم على منحنى (الموقع – الزمن)؟', null, null, '["بطول الخط البياني كاملًا","بالإحداثي الرأسي لنقطة واحدة على الخط البياني","بالإحداثي الأفقي لنقطة واحدة على الخط البياني","بالفرق بين الإحداثيين الرأسيين لنقطتين على الخط"]'::jsonb, 'فهم', 'تمثيل مفهوم بيانيًا', 'متوسط', 'الكتاب ص 38 — الموقع اللحظي'),
('mcq', 6, 'سُجّل موقع عربة كل 1.0 s في جدول، ثم مُثّلت البيانات بمنحنى (الموقع – الزمن) ورُسم خط المواءمة الأفضل. كيف يمكن تحديد الموقع اللحظي للعربة عند 2.5 s مع أن الجدول لا يتضمن هذه اللحظة؟', null, null, '["بقراءة الإحداثي الرأسي للنقطة على الخط عند 2.5 s","لا يمكن تحديده لأنه غير موجود في الجدول","بحساب متوسط جميع المواقع المسجلة في الجدول","بضرب 2.5 في آخر موقع مسجل في الجدول"]'::jsonb, 'تطبيق', 'توظيف مفهوم', 'متوسط', 'الكتاب ص 38 — استخدام الرسم البياني لتحديد الموقع والزمن'),
('mcq', 7, 'كان الموقع اللحظي لسيارة عند اللحظة 5.0 s يساوي 0 m. ماذا يعني ذلك؟', null, null, '["أن السيارة لم تتحرك منذ بداية التوقيت","أن السيارة متوقفة حتمًا عند تلك اللحظة","أن المسافة التي قطعتها السيارة حتى تلك اللحظة صفر","أن السيارة كانت عند نقطة الأصل في تلك اللحظة"]'::jsonb, 'فهم', 'تفسير قيمة', 'متوسط', 'الكتاب ص 38 — الموقع اللحظي'),
('essay', 1, 'يمثل المنحنى الآتي حركة عربة على مسار مستقيم. وضّح المقصود بالموقع اللحظي، ثم حدد من المنحنى الموقع اللحظي للعربة عند 2.5 s وعند 4.5 s، مبيّنًا طريقة القراءة.', null, '[{"src":"qimg/phys1/c2l3-o03-e1.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 5 بتدريج 0.5، والموقع (m) رأسيًا من 0 إلى 40 بتدريج 4. خط مستقيم من النقطة (0, 0) إلى النقطة (5, 40)."}]'::jsonb, null, 'فهم', 'شرح وتطبيق', 'متوسط', 'الكتاب ص 38 — الموقع اللحظي'),
('essay', 2, 'بدأ عدّاء التوقيت وهو عند الموقع 5.0 m من نقطة الأصل، وعند اللحظة 4.5 s كان موقعه 27.5 m. ميّز بين الموقع اللحظي للعدّاء عند 4.5 s وإزاحته خلال الفترة من 0 إلى 4.5 s، واذكر متى تتساوى القيمتان.', null, null, null, 'تحليل', 'مقارنة مفهومين', 'متوسط', 'الكتاب ص 38، 53 — الموقع اللحظي'),
('essay', 3, 'قال طالب: «لا يمكن تحديد الموقع اللحظي لسيارة تتحرك بسرعة؛ لأنها لا تبقى في مكان واحد». قوّم هذه العبارة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 38 — الموقع اللحظي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
