insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الموقع اللحظي هو موقع الجسم عند لحظة زمنية تؤول إلى الصفر؛ أي موقعه عند لحظة محددة واحدة.', '["هذا تعريف الإزاحة، وهي تحتاج إلى لحظتين لا لحظة واحدة.","موقع الجسم لحظة البدء هو الموقع الابتدائي، وهو حالة خاصة واحدة من المواقع اللحظية.","","المسافة الكلية تُقاس خلال فترة زمنية، والموقع اللحظي يخص لحظة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.244Z"}'::jsonb),
('mcq', 2, 0, 'يُستخدم الرمز $\boldsymbol{d}$ لتمثيل الموقع اللحظي للجسم عند لحظة زمنية تؤول إلى الصفر.', '["","$\\Delta \\boldsymbol{d}$ رمز الإزاحة (التغير في الموقع) لا الموقع اللحظي.","$t_{i}$ رمز اللحظة الابتدائية (زمن)، لا رمز الموقع.","$\\Delta t$ رمز الفترة الزمنية لا الموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.245Z"}'::jsonb),
('mcq', 3, 1, 'الموقع اللحظي يحدد أين كان الجسم عند لحظة معينة، والعبارة «على بُعد 22.5 m من نقطة البداية عند اللحظة 4.5 s» تحدد موقعًا عند لحظة واحدة.', '["هذه العبارة تصف ما قطعه العدّاء خلال فترة زمنية، لا موقعه عند لحظة.","","هذه العبارة تصف الزمن اللازم لقطع مسافة، أي فترة زمنية لا لحظة.","هذه العبارة تصف معدل قطع المسافة خلال الحركة، وليس موقعًا عند لحظة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:59.245Z"}'::jsonb),
('mcq', 4, 3, 'موقع الجسم المتحرك يتغير باستمرار؛ فإذا أُخذ خلال فترة زمنية طويلة تغيّر، لذا يُحدَّد الموقع اللحظي عند لحظة واحدة تؤول فترتها إلى الصفر.', '["الجسم قد يكون متحركًا عند تلك اللحظة؛ والتعريف لا يشترط سكونه.","عبارة «تؤول إلى الصفر» تخص الفترة الزمنية، لا قيمة الموقع نفسه.","الموقع اللحظي يمكن تحديده عند أي لحظة من الحركة، لا عند بدايتها فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.245Z"}'::jsonb),
('mcq', 5, 1, 'كل نقطة على الخط البياني تقابل لحظة واحدة (إحداثيها الأفقي)، وإحداثيها الرأسي هو موقع الجسم عند تلك اللحظة، أي موقعه اللحظي.', '["طول الخط البياني لا يمثل كمية فيزيائية في هذا المنحنى.","","الإحداثي الأفقي يمثل الزمن (اللحظة) لا الموقع.","الفرق بين موقعين عند لحظتين هو الإزاحة لا الموقع اللحظي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.245Z"}'::jsonb),
('mcq', 6, 0, 'يبين الخط البياني موقع الجسم عند أي لحظة حتى لو لم تتوافر بيانات مباشرة لها؛ فنرسم خطًا رأسيًا عند 2.5 s حتى يلاقي الخط، ثم خطًا أفقيًا إلى محور الموقع.', '["","الخط البياني يعطي مواقع اللحظات الواقعة بين القياسات، فلا يلزم وجودها في الجدول.","متوسط المواقع لا يرتبط بلحظة محددة، فلا يعطي الموقع عند 2.5 s.","لا علاقة رياضية تجعل الموقع اللحظي ناتج ضرب الزمن في آخر موقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.245Z"}'::jsonb),
('mcq', 7, 3, 'الموقع اللحظي 0 m يعني فقط أن السيارة كانت عند نقطة الأصل عند اللحظة 5.0 s، وقد تكون متحركة وقد تكون قطعت مسافات قبل ذلك ثم عادت.', '["قد تكون السيارة تحركت ثم عادت إلى نقطة الأصل؛ فالموقع عند لحظة لا يكشف ما حدث قبلها.","الموقع اللحظي لا يخبرنا وحده هل الجسم ساكن أم متحرك عند تلك اللحظة.","الموقع صفر لا يعني أن المسافة المقطوعة صفر؛ فقد تكون ذهبت ثم عادت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.245Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الموقع اللحظي هو موقع الجسم عند لحظة زمنية تؤول إلى الصفر، ويرمز له بالرمز $\boldsymbol{d}$. لقراءته: نرسم خطًا رأسيًا من اللحظة المطلوبة على محور الزمن حتى يلاقي الخط البياني، ثم خطًا أفقيًا من نقطة التلاقي إلى محور الموقع. عند 2.5 s يكون الموقع 20 m، وعند 4.5 s يكون الموقع 36 m.', '["تعريف الموقع اللحظي","طريقة القراءة (خط رأسي ثم أفقي)","الموقع عند 2.5 s = 20 m","الموقع عند 4.5 s = 36 m"]'::jsonb, '["الخط يمر بـ (0, 0) و(5, 40)، فيزداد الموقع 8 m كل 1 s","عند 2.5 s: 2.5 × 8 = 20 m","عند 4.5 s: 4.5 × 8 = 36 m"]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"طريقة القراءة","marks":1},{"element":"القراءتان","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["قراءة الزمن من المحور الرأسي.","الخلط بين الموقع اللحظي والإزاحة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.245Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الموقع اللحظي عند 4.5 s هو 27.5 m، ويحدد أين كان العدّاء عند تلك اللحظة بالنسبة لنقطة الأصل. أما الإزاحة فهي التغير في الموقع خلال الفترة: $\Delta \boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 27.5 - 5.0 = 22.5\ \text{m}$ في الاتجاه الموجب. فالموقع اللحظي يخص لحظة واحدة، والإزاحة تخص لحظتين. وتتساوى القيمتان عندما يبدأ الجسم من نقطة الأصل ($\boldsymbol{d}_i = 0$).', '["الموقع اللحظي 27.5 m يخص لحظة واحدة","الإزاحة 22.5 m تخص فترة بين لحظتين","تتساويان عندما يكون الموقع الابتدائي صفرًا"]'::jsonb, '["$\\Delta \\boldsymbol{d} = \\boldsymbol{d}_f - \\boldsymbol{d}_i$","$\\Delta \\boldsymbol{d} = 27.5\\ \\text{m} - 5.0\\ \\text{m} = 22.5\\ \\text{m}$"]'::jsonb, '[{"element":"الموقع اللحظي ومعناه","marks":1},{"element":"حساب الإزاحة ومعناها","marks":1},{"element":"شرط التساوي","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["اعتبار الموقع 27.5 m هو الإزاحة.","جمع الموقعين بدل طرحهما."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.245Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فالموقع اللحظي يُعرَّف عند لحظة زمنية تؤول إلى الصفر، وفي هذه اللحظة يكون للسيارة موقع واحد محدد حتى وهي تتحرك. صحيح أن موقعها يتغير مع الزمن، لكن لكل لحظة موقعًا خاصًا بها، ويمكن قراءته من منحنى (الموقع – الزمن) عند أي لحظة.', '["الحكم: العبارة غير صحيحة","للجسم المتحرك موقع واحد عند كل لحظة","تغيّر الموقع مع الزمن لا يمنع تحديده عند لحظة، ويمكن قراءته من المنحنى"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بتعريف الموقع اللحظي","marks":1},{"element":"ذكر طريقة التحديد","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الموافقة على العبارة.","الخلط بين الموقع اللحظي والموقع الابتدائي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.245Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L3-O03') and x.type = v.type and x.number = v.number
