from (values
('mcq', 1, 'يمثل المنحنى الآتي حركة عدّاء على مضمار مستقيم. ما موقع العدّاء عند اللحظة 4.0 s؟', null, '[{"src":"qimg/phys1/c2l3-o04-a1.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 8 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 60 بتدريج 10. خط مستقيم من النقطة (0, 10) إلى النقطة (8, 50)."}]'::jsonb, '["20 m","10 m","30 m","40 m"]'::jsonb, 'تطبيق', 'قراءة الموقع عند لحظة', 'سهل', 'الكتاب ص 39 — استخدام الرسم البياني لتحديد الموقع والزمن'),
('mcq', 2, 'يمثل المنحنى الآتي حركة عدّاء على مضمار مستقيم. متى كان العدّاء على بُعد 40 m من نقطة الأصل؟', null, '[{"src":"qimg/phys1/c2l3-o04-a2.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 8 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 60 بتدريج 10. خط مستقيم من النقطة (0, 10) إلى النقطة (8, 50)."}]'::jsonb, '["6.0 s","8.0 s","4.0 s","5.0 s"]'::jsonb, 'تطبيق', 'قراءة اللحظة عند موقع', 'سهل', 'الكتاب ص 39 — استخدام الرسم البياني لتحديد الموقع والزمن'),
('mcq', 3, 'يمثل المنحنى الآتي حركة سيارة على طريق مستقيم يمتد شرقًا وغربًا، والاتجاه الموجب نحو الشرق. أين كانت السيارة عند اللحظة 8.0 s؟', null, '[{"src":"qimg/phys1/c2l3-o04-b1.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 8 بتدريج 1، والموقع (m) رأسيًا من −60 إلى 140 بتدريج 20، ومحور الزمن مرسوم عند الموقع 0. خط مستقيم من النقطة (0, 120) إلى النقطة (8, −40) يقطع محور الزمن عند 6."}]'::jsonb, '["على بُعد 40 m شرق نقطة الأصل","على بُعد 160 m غرب نقطة الأصل","عند نقطة الأصل نفسها","على بُعد 40 m غرب نقطة الأصل"]'::jsonb, 'تطبيق', 'قراءة موقع سالب', 'متوسط', 'الكتاب ص 39 — مسائل تدريبية (السؤال 11)'),
