('essay', 1, null::int, null, null, '(a) نرسم خطًا رأسيًا من 1.5 h حتى يلاقي الخط البياني، ثم خطًا أفقيًا إلى محور الموقع: 6.0 km. (b) نرسم خطًا أفقيًا من 2.0 km حتى يلاقي الخط، ثم خطًا رأسيًا إلى محور الزمن: 0.5 h. (c) عند 2.5 h يكون الموقع 10 km.', '["(a) 6.0 km","(b) 0.5 h","(c) 10 km","وصف القراءة: رأسي ثم أفقي للموقع، وأفقي ثم رأسي للزمن"]'::jsonb, '["الخط يمر بـ (0, 0) و(2.5 h, 10 km)، فيزداد الموقع 4 km كل 1 h","(a) 1.5 × 4 = 6.0 km","(b) 2.0 ÷ 4 = 0.5 h"]'::jsonb, '[{"element":"الموقع عند 1.5 h","marks":1},{"element":"اللحظة عند 2.0 km","marks":1},{"element":"الموقع عند 2.5 h","marks":0.5},{"element":"طريقة القراءة","marks":0.5}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["قراءة الزمن من محور الموقع.","الخلط بين وحدتي h وkm."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.247Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) عند 5 s الموقع 4 m (منتصف الجزء الصاعد الأول)، وعند 15 s الموقع 8 m (الجزء الأفقي)، وعند 40 s الموقع 0 m أي عادت إلى نقطة الأصل. (b) كانت عند 16 m عند اللحظة 30 s فقط. (c) كانت عند 4 m مرتين: عند 5 s أثناء ابتعادها، وعند 37.5 s أثناء عودتها.', '["الموقع عند 5 s = 4 m","الموقع عند 15 s = 8 m","الموقع عند 40 s = 0 m","عند 16 m: 30 s","عند 4 m: 5 s و37.5 s"]'::jsonb, '["الجزء من 30 s إلى 40 s: يتناقص الموقع 16 m خلال 10 s، أي 1.6 m كل ثانية","للوصول إلى 4 m يلزم نقص 12 m: 12 ÷ 1.6 = 7.5 s بعد 30 s، أي عند 37.5 s"]'::jsonb, '[{"element":"المواقع الثلاثة","marks":1.5},{"element":"اللحظة عند 16 m","marks":0.5},{"element":"اللحظتان عند 4 m","marks":2}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["ذكر لحظة واحدة فقط للموقع 4 m وإهمال العودة.","قراءة الموقع عند 15 s على أنه بين 8 m و16 m."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-18T12:34:59.247Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المنحنى خط مستقيم يبدأ من (0 s, 0 m)، ويزداد فيه الموقع 2.5 m كل 2.0 s، أي 1.25 m كل ثانية، وينتهي عند (80 s, 100.0 m). (a) الموقع 25.0 m عند 20 s. (b) على بُعد 25.0 m من المختبر يعني الموقع $100.0 - 25.0 = 75.0\ \text{m}$ من الصف، وذلك عند 60 s. (c) تصل إلى المختبر (100.0 m) عند 80 s.', '["رسم خط مستقيم من نقطة الأصل بمعدل 2.5 m كل 2.0 s","(a) 20 s","تحويل البُعد عن المختبر إلى موقع 75.0 m","(b) 60 s","(c) 80 s"]'::jsonb, '["الموقع يزداد 1.25 m كل 1 s","(a) 25.0 ÷ 1.25 = 20 s","(b) الموقع $= 100.0 - 25.0 = 75.0\\ \\text{m}$، والزمن = 75.0 ÷ 1.25 = 60 s","(c) 100.0 ÷ 1.25 = 80 s"]'::jsonb, '[{"element":"وصف المنحنى","marks":1},{"element":"(a)","marks":1},{"element":"(b) مع التحويل","marks":1.5},{"element":"(c)","marks":0.5}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["إعطاء 20 s للحالتين (a) و(b) بإهمال أن البعد عن المختبر يختلف عن البعد عن الصف.","اعتبار المعدل 2.5 m لكل ثانية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.247Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
