from (values
('mcq', 1, 'يمثل المنحنى الآتي حركة جسم خلال 6 s. أيّ العبارات الآتية تصف حركته؟', null, '[{"src":"qimg/phys1/c2l3-o05-rest.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 6 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 40 بتدريج 10. خط أفقي عند الموقع 30 من 0 إلى 6."}]'::jsonb, '["الجسم ساكن في الموقع 30 m طوال الفترة","الجسم يتحرك بانتظام على طريق أفقي مستوٍ","الجسم يبتعد عن نقطة الأصل 30 m كل ثانية","الجسم ساكن عند نقطة الأصل طوال الفترة"]'::jsonb, 'فهم', 'وصف حركة', 'سهل', 'الكتاب ص 56 — تقويم الفصل (السؤال 56)'),
('mcq', 2, 'يمثل المنحنى الآتي حركة دراجة على طريق مستقيم. أيّ العبارات الآتية تصف حركتها؟', null, '[{"src":"qimg/phys1/c2l3-o05-toward.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 6 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 140 بتدريج 20. خط مستقيم من النقطة (0, 120) إلى النقطة (6, 0)."}]'::jsonb, '["تبتعد عن نقطة الأصل حتى تصل إلى 120 m عند 6 s","تتحرك نحو نقطة الأصل وتصل إليها عند 6 s","تنزل منحدرًا ارتفاعه 120 m خلال 6 s","تبقى ساكنة عند الموقع 120 m مدة 6 s"]'::jsonb, 'تحليل', 'وصف حركة', 'متوسط', 'الكتاب ص 39 — مسائل تدريبية (وصف الحركة من منحنى الموقع – الزمن)'),
('mcq', 3, 'يمثل المنحنى الآتي حركة شخصين A وB يسيران على طريق مستقيم يمتد شرقًا وغربًا، والاتجاه الموجب نحو الشرق. أيّ العبارات الآتية تصف حركة الشخص A؟', null, '[{"src":"qimg/phys1/c2l3-o05-ab.svg","alt":"منحنى (الموقع – الزمن) لشخصين: الزمن (s) أفقيًا من 0 إلى 10 بتدريج 1، والموقع (m) رأسيًا من −60 إلى 80 بتدريج 20، ومحور الزمن عند الموقع 0. الخط A (أزرق) مستقيم من (0, −40) إلى (10, 40). الخط B (أحمر) مستقيم من (0, 60) إلى (10, −20)."}]'::jsonb, '["يبدأ على بُعد 40 m شرق نقطة الأصل، ويتحرك غربًا","يبدأ على بُعد 40 m غرب نقطة الأصل، ويتحرك غربًا مبتعدًا عنها","يبدأ من نقطة الأصل، ويتحرك شرقًا حتى 40 m","يبدأ على بُعد 40 m غرب نقطة الأصل، ويتحرك شرقًا"]'::jsonb, 'تحليل', 'وصف حركة مع الإشارات', 'متوسط', 'الكتاب ص 39 — مسائل تدريبية (السؤال 12)'),
('mcq', 4, 'يمثل المنحنى الآتي حركة طالب في ممر مستقيم. أيّ العبارات الآتية تصف حركته؟', null, '[{"src":"qimg/phys1/c2l3-o05-return.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 12 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 30 بتدريج 5. خط متكسر يصل النقاط (0, 0) ثم (4, 20) ثم (8, 20) ثم (12, 0)."}]'::jsonb, '["يصعد درجًا خلال 4 s، ثم يمشي على أرض مستوية 4 s، ثم ينزل درجًا خلال 4 s","يبتعد عن نقطة الأصل 20 m خلال 4 s، ثم يبقى ساكنًا 8 s، ثم يعود إليها","يبتعد عن نقطة الأصل 20 m خلال 4 s، ثم يبقى ساكنًا 4 s، ثم يعود إليها خلال 4 s","يبتعد عن نقطة الأصل 20 m خلال 4 s، ثم يبقى ساكنًا 4 s، ثم يبتعد 20 m أخرى"]'::jsonb, 'تحليل', 'وصف حركة متعددة المراحل', 'متوسط', 'الكتاب ص 55 — تقويم الفصل (السؤال 54a)'),
('mcq', 5, 'يمثل المنحنى الآتي حركة متزلج على مسار مستقيم. أيّ العبارات الآتية تصف حركته؟', null, '[{"src":"qimg/phys1/c2l3-o05-cross.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 8 بتدريج 1، والموقع (m) رأسيًا من −30 إلى 30 بتدريج 10، ومحور الزمن مرسوم عند الموقع 0. خط مستقيم هابط من النقطة (0, 20) إلى النقطة (4, −20) يقطع محور الزمن عند 2، ثم خط أفقي من النقطة (4, −20) إلى النقطة (8, −20)."}]'::jsonb, '["يتحرك في الاتجاه السالب حتى يصل إلى نقطة الأصل عند 4 s، ثم يسكن عندها","يتحرك في الاتجاه السالب فيمر بنقطة الأصل عند 2 s، ثم يسكن من 4 s إلى 8 s","يتحرك في الاتجاه السالب حتى 4 s، ثم يواصل حركته بانتظام في الاتجاه نفسه","يتحرك في الاتجاه الموجب فيمر بنقطة الأصل عند 2 s، ثم يسكن من 4 s إلى 8 s"]'::jsonb, 'تحليل', 'مقارنة أجزاء منحنى', 'صعب', 'الكتاب ص 39 — مسائل تدريبية (السؤالان 9 و11)'),
('mcq', 6, 'هل يمكن أن يكون منحنى (الموقع – الزمن) لجسم خطًا رأسيًا؟', null, null, '["نعم؛ ويعني أن الجسم ساكن في موقعه","نعم؛ ويعني أن الجسم يتحرك رأسيًا إلى أعلى","لا؛ لأن الخط الرأسي يعني أن الجسم ساكن عند نقطة الأصل","لا؛ لأنه يعني وجود الجسم في مواقع مختلفة في اللحظة نفسها"]'::jsonb, 'تحليل', 'تعليل', 'صعب', 'الكتاب ص 56 — تقويم الفصل (السؤال 56)'),
('mcq', 7, 'يتكون منحنى (الموقع – الزمن) لكرة تتدحرج على أرض مستوية من خط مستقيم يصل النقطة (0 s, 50 m) بالنقطة (5 s, 0 m)، يليه خط مستقيم يصل النقطة (5 s, 0 m) بالنقطة (10 s, 50 m). أيّ العبارات الآتية تصف حركة الكرة؟', null, null, '["تقترب من نقطة الأصل حتى تصلها عند 5 s، ثم تبتعد عنها في الاتجاه الموجب حتى 50 m","تنزل منحدرًا حتى 5 s، ثم تصعد منحدرًا آخر حتى 10 s","تقترب من نقطة الأصل حتى 5 s، ثم تتجاوزها إلى الجهة السالبة حتى $-50\\ \\text{m}$","تقترب من نقطة الأصل حتى تصلها عند 5 s، ثم تبقى ساكنة عندها"]'::jsonb, 'تحليل', 'وصف حركة متعددة المراحل', 'متوسط', 'الكتاب ص 39 — مسائل تدريبية (وصف الحركة من منحنى الموقع – الزمن)'),
('essay', 1, 'يمثل المنحنى الآتي حركة علي ذهابًا وإيابًا في ممر مستقيم، ونقطة الأصل عند أحد طرفي الممر. اكتب فقرة تصف حركة علي في الممر وصفًا يتطابق مع المنحنى، محددًا فترات السكون وفترات الابتعاد والعودة ومواقعه عندها.', null, '[{"src":"qimg/phys1/c2l3-o05-e1.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 70 بتدريج 5، والموقع (m) رأسيًا من 0 إلى 25 بتدريج 5. خط متكسر يصل النقاط (0, 0) ثم (10, 10) ثم (25, 10) ثم (35, 20) ثم (40, 20) ثم (55, 5) ثم (60, 5) ثم (65, 0)."}]'::jsonb, null, 'تحليل', 'وصف حركة بفقرة', 'صعب', 'الكتاب ص 55 — تقويم الفصل (السؤال 54a)'),
('essay', 2, 'يبين الجدول الآتي مواقع سيارة تتحرك على طريق مستقيم يمتد شرقًا وغربًا، والاتجاه الموجب نحو الشرق. صف منحنى (الموقع – الزمن) لهذه البيانات، ثم صف حركة السيارة بالكلمات: من أين بدأت؟ وفي أيّ اتجاه تحركت؟ ومتى مرت بنقطة الأصل؟ وأين أصبحت في النهاية؟', '{"headers":["الزمن (s)","الموقع (m)"],"rows":[["0","120"],["2","80"],["4","40"],["6","0"],["8","$-40$"]]}'::jsonb, null, null, 'تحليل', 'وصف حركة مع الإشارات', 'متوسط', 'الكتاب ص 39 — مسائل تدريبية (السؤال 9)'),
('essay', 3, 'يمثل المنحنى الآتي حركة أرنب يهرب من كلب على أرض مستوية. صف كيف يختلف هذا الرسم البياني في كل حالة مما يأتي: (a) بدأ الأرنب الحركة من موقع يبعد 1 m عن نقطة الأصل في الاتجاه الموجب. (b) ركض الأرنب في الاتجاه المعاكس. (c) توقف الأرنب بعد 1 s مدة 1 s ثم أكمل حركته كما كان.', null, '[{"src":"qimg/phys1/c2l3-o05-e3.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 3 بتدريج 0.5، والموقع (m) رأسيًا من 0 إلى 3 بتدريج 0.5. خط مستقيم من النقطة (0, 0) إلى النقطة (3, 3)."}]'::jsonb, null, 'إبداع', 'تعديل منحنى وفق وصف', 'متوسط', 'الكتاب ص 54 — تقويم الفصل (السؤال 45)')
