('mcq', 2, 1, 'الموقع يتناقص بانتظام من 120 m عند 0 s إلى 0 m عند 6 s؛ أي أن الدراجة تقترب من نقطة الأصل حتى تصل إليها عند 6 s.', '["قُرئ المنحنى معكوسًا زمنيًا؛ فالموقع 120 m عند البداية لا عند النهاية.","","المنحنى لا يصور شكل الطريق؛ فالخط الهابط يعني تناقص الموقع لا نزول منحدر.","الموقع يتغير مع الزمن، فالدراجة متحركة لا ساكنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-18T12:34:59.248Z"}'::jsonb),
('mcq', 3, 3, 'خط A يبدأ عند $-40\ \text{m}$ (غرب نقطة الأصل) ويزداد موقعه مع الزمن، أي يتحرك شرقًا، ويقطع محور الزمن عند 5 s فيمر بنقطة الأصل ثم يصبح شرقها.', '["الموقع الابتدائي سالب أي غرب نقطة الأصل، والموقع يزداد أي أن الحركة نحو الشرق.","الموقع يزداد مع الزمن، فالحركة نحو الشرق لا الغرب.","خط A يبدأ من $-40\\ \\text{m}$ لا من نقطة الأصل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-18T12:34:59.248Z"}'::jsonb),
('mcq', 4, 2, 'من 0 إلى 4 s يزداد الموقع من 0 إلى 20 m (ابتعاد)، ومن 4 s إلى 8 s يبقى الموقع 20 m (سكون)، ومن 8 s إلى 12 s يتناقص الموقع إلى 0 (عودة إلى نقطة الأصل).', '["المنحنى لا يصور شكل المسار؛ فالأجزاء الصاعدة والهابطة تعني تغير الموقع لا صعود درج أو نزوله.","فترة السكون من 4 s إلى 8 s، أي 4 s لا 8 s.","","الجزء الأخير يتناقص فيه الموقع، فالطالب يعود نحو نقطة الأصل لا يبتعد عنها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (69%)"}],"at":"2026-11-18T12:34:59.248Z"}'::jsonb),
('mcq', 5, 1, 'من 0 إلى 4 s يتناقص الموقع من 20 m إلى $-20\ \text{m}$؛ فالمتزلج يتحرك في الاتجاه السالب ويمر بنقطة الأصل عند 2 s حين يقطع الخط محور الزمن. ومن 4 s إلى 8 s يبقى الموقع $-20\ \text{m}$ (خط أفقي)، فهو ساكن.', '["المتزلج يمر بنقطة الأصل عند 2 s، وعند 4 s يكون موقعه $-20\\ \\text{m}$ لا صفرًا.","","الجزء الأفقي يعني أن الموقع ثابت عند $-20\\ \\text{m}$، أي أن المتزلج ساكن لا متحرك.","الموقع يتناقص من 20 m إلى $-20\\ \\text{m}$، فالحركة في الاتجاه السالب لا الموجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (69%)"}],"at":"2026-11-18T12:34:59.248Z"}'::jsonb),
('mcq', 6, 3, 'الخط الرأسي يقابل لحظة زمنية واحدة مع مواقع كثيرة مختلفة، ولا يمكن أن يكون الجسم في أكثر من موقع في اللحظة نفسها؛ لذا لا يكون المنحنى خطًا رأسيًا.', '["الجسم الساكن يمثله خط أفقي لا رأسي.","المنحنى لا يصور اتجاه المسار في الفراغ؛ والخط الرأسي يعني تعدد المواقع عند لحظة واحدة.","الحكم صحيح لكن التعليل خاطئ؛ فالجسم الساكن عند نقطة الأصل يمثله خط أفقي على محور الزمن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.248Z"}'::jsonb),
('mcq', 7, 0, 'من 0 إلى 5 s يتناقص الموقع من 50 m إلى 0 (اقتراب من نقطة الأصل حتى الوصول إليها)، ومن 5 s إلى 10 s يزداد الموقع من 0 إلى 50 m (ابتعاد في الاتجاه الموجب).', '["","الأرض مستوية، والمنحنى لا يصور المسار؛ فهبوط الخط وصعوده يعني تناقص الموقع وتزايده.","بعد 5 s يزداد الموقع ويبقى موجبًا، فالكرة لا تنتقل إلى الجهة السالبة.","بعد 5 s يتغير الموقع، فالكرة متحركة لا ساكنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.249Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من 0 إلى 10 s يبتعد علي عن نقطة الأصل من 0 إلى 10 m. من 10 s إلى 25 s يقف ساكنًا عند 10 m. من 25 s إلى 35 s يبتعد مرة أخرى من 10 m إلى 20 m. من 35 s إلى 40 s يقف ساكنًا عند 20 m (أبعد موقع). من 40 s إلى 55 s يعود نحو نقطة الأصل من 20 m إلى 5 m. من 55 s إلى 60 s يقف ساكنًا عند 5 m. من 60 s إلى 65 s يعود إلى نقطة الأصل فيصلها عند 65 s.', '["الابتعاد من 0 إلى 10 m (0–10 s)","السكون عند 10 m (10–25 s)","الابتعاد إلى 20 m (25–35 s) ثم السكون (35–40 s)","العودة إلى 5 m (40–55 s) ثم السكون (55–60 s)","العودة إلى نقطة الأصل عند 65 s"]'::jsonb, '[]'::jsonb, '[{"element":"المرحلة الأولى","marks":1},{"element":"فترات السكون الثلاث","marks":1.5},{"element":"مرحلة الابتعاد الثانية","marks":0.5},{"element":"مراحل العودة","marks":1}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["وصف الأجزاء الأفقية بأنها حركة على أرض مستوية.","وصف الأجزاء الهابطة بأنها نزول.","خطأ في قراءة لحظات بداية المراحل ونهايتها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.249Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المنحنى خط مستقيم هابط يبدأ من (0 s, 120 m) وينتهي عند (8 s, $-40\ \text{m}$)، ويقطع محور الزمن عند 6 s. فالسيارة بدأت على بُعد 120 m شرق نقطة الأصل، وتحركت غربًا بانتظام (يتناقص موقعها 20 m كل ثانية)، فمرت بنقطة الأصل عند 6 s، وأصبحت عند 8 s على بُعد 40 m غرب نقطة الأصل.', '["المنحنى خط مستقيم هابط","البداية 120 m شرق نقطة الأصل","الحركة نحو الغرب بانتظام","المرور بنقطة الأصل عند 6 s","النهاية 40 m غرب نقطة الأصل"]'::jsonb, '[]'::jsonb, '[{"element":"وصف المنحنى","marks":1},{"element":"موقع البداية واتجاه الحركة","marks":1},{"element":"لحظة المرور بنقطة الأصل","marks":1},{"element":"الموقع النهائي واتجاهه","marks":1}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["وصف الحركة بأنها نحو الشرق لأن القيم موجبة في البداية.","إهمال إشارة الموقع النهائي.","القول إن السيارة توقفت عند نقطة الأصل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.249Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) يبقى الخط مستقيمًا بالانحدار نفسه لكنه ينزاح إلى أعلى، فيبدأ من (0 s, 1 m) وينتهي عند (3 s, 4 m). (b) يصبح الخط هابطًا تحت محور الزمن؛ يبدأ من نقطة الأصل ويتناقص موقعه فيصل إلى $-3\ \text{m}$ عند 3 s. (c) يصعد الخط من (0, 0) إلى (1 s, 1 m)، ثم يصبح أفقيًا من 1 s إلى 2 s عند 1 m، ثم يصعد بالانحدار نفسه، فيصل إلى 2 m عند 3 s.', '["(a) إزاحة الخط إلى أعلى ليبدأ عند 1 m","(b) خط هابط إلى المواقع السالبة","(c) جزء أفقي يمثل السكون ثم صعود بالانحدار نفسه"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["رسم الحالة (b) خطًا صاعدًا بانحدار مختلف.","رسم التوقف خطًا رأسيًا.","تغيير انحدار الخط في الحالة (a)."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.249Z"}'::jsonb)
