('mcq', 6, 'يبين الشكل الآتي نموذجًا جسيميًا نقطيًا (الفترة الزمنية بين كل نقطتين متتاليتين ثانيتان) ومنحنى (الموقع – الزمن). هل يصف التمثيلان الحركة نفسها؟', null, '[{"src":"qimg/phys1/c2l3-o06-compare.svg","alt":"في الأعلى نموذج جسيمي نقطي: سبع نقاط فوق محور الموقع (m) المدرّج من 0 إلى 14 بتدريج 2، والنقاط عند 0 و2 و4 و6 و8 و10 و12 m، ومكتوب أن الفترة الزمنية بين كل نقطتين متتاليتين ثانيتان. في الأسفل منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 4 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 16 بتدريج 2، وخط مستقيم من (0, 0) إلى (3, 12)."}]'::jsonb, '["نعم؛ فكلاهما يبدأ من نقطة الأصل ويبتعد عنها","نعم؛ فكلاهما يصل إلى الموقع 12 m في النهاية","لا؛ فالنموذج يبين 2 m كل 2.0 s، والمنحنى يبين 4 m كل 1 s","لا؛ لأن النموذج يبين جسمًا ساكنًا والمنحنى يبين جسمًا متحركًا"]'::jsonb, 'تحليل', 'مقارنة تمثيلين', 'صعب', 'الكتاب ص 42 — مراجعة 2-3 (السؤال 24)'),
('mcq', 7, 'يبين الجدول مواقع قطة تتحرك في ممر مستقيم. أيّ الأوصاف اللفظية الآتية يكافئ الجدول؟', '{"headers":["الزمن (s)","الموقع (m)"],"rows":[["0","0"],["1","6"],["2","12"],["3","12"],["4","6"]]}'::jsonb, null, '["تبتعد 12 m خلال 2 s، ثم تسكن 2 s، ثم تعود 6 m نحو نقطة الأصل","تبتعد 12 m خلال 2 s، ثم تسكن 1 s، ثم تعود 6 m نحو نقطة الأصل خلال 1 s","تبتعد 12 m خلال 2 s، ثم تسكن 1 s، ثم تبتعد 6 m أخرى خلال 1 s","تبتعد عن نقطة الأصل 6 m كل ثانية طوال 4 s"]'::jsonb, 'تطبيق', 'التحويل بين تمثيلات', 'سهل', 'الكتاب ص 40 — التمثيلات المتكافئة'),
('essay', 1, 'يمثل الشكل الآتي النموذج الجسيمي النقطي لولد يعبر طريقًا مستقيمًا، والفترة الزمنية بين كل نقطتين متتاليتين 1.0 s، وأول نقطة عند 0.0 s. صف حركة الولد بثلاثة تمثيلات متكافئة: جدول بيانات، ووصف لمنحنى (الموقع – الزمن)، ووصف بالكلمات.', null, '[{"src":"qimg/phys1/c2l3-o06-e1.svg","alt":"نموذج جسيمي نقطي: سبع نقاط فوق محور الموقع (m) المدرّج من 0 إلى 9 بتدريج 1.5، والنقاط عند 0 و1.5 و3 و4.5 و6 و7.5 و9 m، مكتوب فوق النقطة عند 0 «البداية» وفوق النقطة عند 9 «النهاية»."}]'::jsonb, null, 'تطبيق', 'التحويل بين تمثيلات', 'سهل', 'الكتاب ص 55 — تقويم الفصل (السؤال 50)'),
('essay', 2, 'تقف سيارة عند إشارة مرور، ونقطة الأصل عند الإشارة والاتجاه الموجب نحو الشرق. عند بدء التوقيت كانت السيارة على بُعد 20 m غرب الإشارة، ثم تحركت شرقًا بانتظام فقطعت 10 m كل ثانية مدة 4 s، ثم توقفت 2 s. مثّل هذه الحركة بجدول بيانات كل 1 s، وصف النموذج الجسيمي النقطي ومنحنى (الموقع – الزمن) المكافئين له.', null, null, null, 'إبداع', 'إنتاج تمثيلات متكافئة', 'صعب', 'الكتاب ص 40 — التمثيلات المتكافئة'),
('essay', 3, 'يمثل المنحنى الآتي حركة طفل يمشي في ممر مستقيم. حوّله إلى جدول بيانات كل 1 s، ثم صف النموذج الجسيمي النقطي المكافئ له، واكتب وصفًا لفظيًا للحركة.', null, '[{"src":"qimg/phys1/c2l3-o06-e3.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 6 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 8 بتدريج 1. خط متكسر يصل النقاط (0, 0) ثم (2, 6) ثم (4, 6) ثم (6, 0)."}]'::jsonb, null, 'تحليل', 'التحويل بين تمثيلات', 'متوسط', 'الكتاب ص 40 — التمثيلات المتكافئة')
