('mcq', 1, 1, 'تبدأ العربة من الموقع 0 عند 0 s، وكل نقطة تالية أبعد 5 m وتليها بـ 1.0 s؛ فالمواقع 0 و5 و10 و15 و20 m عند الأزمنة 0 و1 و2 و3 و4 s.', '["عُدّت أول نقطة عند 1 s، وأُضيف موقع 25 m غير موجود في النموذج.","","هذا الجدول يعكس اتجاه الحركة؛ فالعربة تبدأ عند 0 m وتنتهي عند 20 m.","هذا تبديل للزمن والموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:34:59.250Z"}'::jsonb),
('mcq', 2, 0, 'الموقع يتناقص من 50 m إلى 10 m بمقدار 10 m كل ثانية؛ أي أن الدراجة تقترب من نقطة الأصل 10 m كل ثانية.', '["","الموقع يتناقص مع الزمن، فالدراجة تقترب من نقطة الأصل لا تبتعد.","عند 4 s كان موقع الدراجة 10 m، فلم تصل إلى نقطة الأصل بعد.","الموقع يتغير منذ البداية، فلا توجد فترة سكون عند 50 m."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-18T12:34:59.250Z"}'::jsonb),
('mcq', 3, 2, 'من 0 إلى 3 s يزداد الموقع 4 m كل ثانية (نقاط عند 0 و4 و8 و12 m)، ومن 3 s إلى 6 s يبقى الموقع 12 m، فتتراكب نقاط 4 s و5 s و6 s على النقطة عند 12 m.', '["أُهملت فترة السكون؛ فالموقع ثابت عند 12 m من 3 s إلى 6 s.","عُكس ترتيب المرحلتين؛ فالحركة أولًا ثم السكون.","","المسافات بين النقاط متساوية في مرحلة الحركة لأن الخط مستقيم، ثم تتراكب النقاط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-18T12:34:59.251Z"}'::jsonb),
('mcq', 4, 3, 'المنحنى (4) خط أفقي عند 20 m من 0 إلى 2 s (سكون)، ثم خط صاعد حتى 40 m عند 4 s (ابتعاد)، وهذا يطابق الوصف.', '["المنحنى (1) يبدأ من نقطة الأصل ويتحرك أولًا ثم يسكن، وهو عكس الوصف.","المنحنى (2) يبين سكونًا ثم عودة إلى نقطة الأصل لا ابتعادًا عنها.","المنحنى (3) لا يتضمن فترة السكون في أول 2 s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.251Z"}'::jsonb),
('mcq', 5, 0, 'تبدأ الكرة عند 40 m وتنتهي عند 0 m، وبين النقاط الخمس أربع فترات كل منها 2.0 s، أي 8 s؛ فالمنحنى خط هابط من (0 s, 40 m) إلى (8 s, 0 m).', '["","أُهمل اتجاه الحركة؛ فالبداية عند 40 m والنهاية عند 0 m.","عُدّت خمس فترات بدل أربع؛ فبين خمس نقاط أربع فترات فقط.","الخط الأفقي يمثل جسمًا ساكنًا، والكرة تغير موقعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:34:59.251Z"}'::jsonb),
('mcq', 6, 2, 'في النموذج تبعد كل نقطة 2 m عن سابقتها خلال 2.0 s، فيصل إلى 12 m عند 12 s؛ أما المنحنى فيزداد فيه الموقع 4 m كل 1 s ويصل إلى 12 m عند 3 s. فالتمثيلان لا يحملان المعلومات نفسها.', '["البداية والاتجاه نفسهما، لكن مواقع الجسم عند الأزمنة نفسها مختلفة.","يصلان إلى 12 m عند لحظتين مختلفتين (12 s في النموذج و3 s في المنحنى).","","النقاط في النموذج متباعدة، فالجسم متحرك لا ساكن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.251Z"}'::jsonb),
('mcq', 7, 1, 'الموقع يزداد من 0 إلى 12 m بين 0 و2 s، ويبقى 12 m بين 2 s و3 s، ثم يتناقص إلى 6 m عند 4 s؛ أي ابتعاد ثم سكون 1 s ثم عودة 6 m خلال 1 s.', '["فترة السكون من 2 s إلى 3 s فقط، أي 1 s لا 2 s.","","الموقع في آخر ثانية يتناقص من 12 m إلى 6 m، فهي عودة لا ابتعاد.","الموقع لا يزداد بانتظام طوال الفترة؛ فهناك سكون ثم عودة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-18T12:34:59.251Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الجدول: الزمن 0.0 و1.0 و2.0 و3.0 و4.0 و5.0 و6.0 s، والموقع 0 و1.5 و3.0 و4.5 و6.0 و7.5 و9.0 m. المنحنى: خط مستقيم صاعد يبدأ من نقطة الأصل وينتهي عند (6.0 s, 9.0 m). بالكلمات: بدأ الولد من نقطة الأصل وتحرك في خط مستقيم مبتعدًا عنها بانتظام، فيقطع 1.5 m كل ثانية، حتى وصل إلى 9.0 m بعد 6.0 s.', '["جدول صحيح من سبعة أزواج","المنحنى خط مستقيم من (0, 0) إلى (6.0 s, 9.0 m)","وصف لفظي: ابتعاد منتظم 1.5 m كل ثانية حتى 9.0 m"]'::jsonb, '["المسافة بين كل نقطتين 1.5 m خلال 1.0 s","سبع نقاط تعني ست فترات: 6 × 1.0 = 6.0 s","الموقع النهائي 6 × 1.5 = 9.0 m"]'::jsonb, '[{"element":"الجدول","marks":1},{"element":"المنحنى","marks":1},{"element":"الوصف اللفظي","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["عدّ سبع فترات بدل ست.","رسم المنحنى خطًا أفقيًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.251Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الجدول: الزمن 0 و1 و2 و3 و4 و5 و6 s، والموقع $-20$ و$-10$ و0 و10 و20 و20 و20 m. النموذج الجسيمي: خمس نقاط متباعدة بمسافات متساوية (10 m) من $-20\ \text{m}$ إلى 20 m في اتجاه الشرق، ثم نقطتان تتراكبان على النقطة عند 20 m. المنحنى: خط مستقيم صاعد من (0 s, $-20\ \text{m}$) يقطع محور الزمن عند 2 s ويصل إلى (4 s, 20 m)، ثم خط أفقي عند 20 m من 4 s إلى 6 s.', '["جدول صحيح بإشارات صحيحة","نموذج جسيمي: نقاط متساوية التباعد ثم نقاط متراكبة","منحنى: خط صاعد من $-20\\ \\text{m}$ ثم خط أفقي عند 20 m","مرور السيارة بالإشارة عند 2 s"]'::jsonb, '["الموقع الابتدائي $-20\\ \\text{m}$ (غرب)","يزداد الموقع 10 m كل ثانية حتى 4 s: $-20 + 4 \\times 10 = 20\\ \\text{m}$","من 4 s إلى 6 s يبقى الموقع 20 m"]'::jsonb, '[{"element":"الجدول","marks":1},{"element":"النموذج الجسيمي","marks":1},{"element":"المنحنى","marks":1},{"element":"الإشارات والاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["كتابة الموقع الابتدائي موجبًا.","رسم فترة التوقف خطًا هابطًا.","إهمال النقاط المتراكبة في النموذج الجسيمي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.252Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجدول: الزمن 0 و1 و2 و3 و4 و5 و6 s، والموقع 0 و3 و6 و6 و6 و3 و0 m. النموذج الجسيمي: ثلاث نقاط عند 0 و3 و6 m متباعدة بمسافات متساوية، ثم نقطتان تتراكبان عند 6 m، ثم نقطتان عند 3 m و0 m أثناء العودة. بالكلمات: يبتعد الطفل عن نقطة الأصل 6 m خلال 2 s بانتظام، ثم يقف 2 s، ثم يعود إلى نقطة الأصل خلال 2 s.', '["جدول صحيح","النموذج الجسيمي يبين الابتعاد ثم التراكب ثم العودة","وصف لفظي صحيح للمراحل الثلاث"]'::jsonb, '["من 0 إلى 2 s: يزداد الموقع 3 m كل ثانية","من 2 s إلى 4 s: الموقع ثابت 6 m","من 4 s إلى 6 s: يتناقص الموقع 3 m كل ثانية"]'::jsonb, '[{"element":"الجدول","marks":1},{"element":"النموذج الجسيمي","marks":1},{"element":"الوصف اللفظي","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["وصف الجزء الهابط بأنه نزول.","إهمال فترة الوقوف في النموذج الجسيمي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-18T12:34:59.252Z"}'::jsonb)
