from (values
('mcq', 1, 'ما المقصود بالتمثيلات المتكافئة لوصف حركة جسم؟', null, null, '["تمثيلات بيانية متطابقة في شكلها لحركات أجسام مختلفة","طرق لوصف الحركة يعطي كل منها معلومات مختلفة عن الأخرى","طرق مختلفة لوصف حركة الجسم نفسه تحمل المعلومات نفسها","رسوم بيانية تتساوى فيها قيم الموقع مع قيم الزمن عند كل نقطة"]'::jsonb, 'فهم', 'تعريف مفهوم', 'سهل', 'الكتاب ص 40 — التمثيلات المتكافئة'),
('mcq', 2, 'أيّ المجموعات الآتية تضم طرقًا متكافئة لوصف حركة جسم؟', null, null, '["الكلمات، والكتلة، والحجم، ودرجة الحرارة، ومنحنى (الموقع – الزمن)","الكلمات، والصور، ومخططات الحركة، وجداول البيانات، ومنحنيات (الموقع – الزمن)","جداول البيانات وحدها؛ لأنها أدق الطرق لوصف الحركة وتمثيلها","منحنيات (الموقع – الزمن) وحدها؛ لأنها الطريقة الوحيدة التي تبين الحركة"]'::jsonb, 'تذكر', 'تعداد', 'سهل', 'الكتاب ص 40 — التمثيلات المتكافئة'),
('mcq', 3, 'يصف جدول بيانات ونموذج جسيمي نقطي متكافئان حركة عربة، والفترة الزمنية بين كل نقطتين متتاليتين في النموذج 1 s، وأول نقطة عند 0 s. إذا بيّن الجدول أن موقع العربة عند اللحظة 2 s هو 6 m، فماذا يجب أن يبيّن النموذج الجسيمي النقطي؟', null, null, '["أن النقطة الثالثة تقع عند الموقع 6 m","أن النقطة الثانية تقع عند الموقع 6 m","أن النقطة الثالثة تقع عند الموقع 2 m","أي موقع للنقطة الثالثة؛ لأن النموذج تمثيل تقريبي"]'::jsonb, 'فهم', 'تعليل تسمية', 'سهل', 'الكتاب ص 40 — التمثيلات المتكافئة'),
('mcq', 4, 'إذا كانت التمثيلات المتكافئة تحمل المعلومات نفسها، فلماذا نحتاج إلى أكثر من تمثيل لوصف الحركة؟', null, null, '["لأن كل تمثيل يصف جزءًا من الحركة لا يصفه غيره من التمثيلات","لأن التمثيلات المتكافئة يجب أن تُستخدم جميعها معًا في كل مسألة","لأن الجدول يُستخدم للأجسام البطيئة والمنحنى للأجسام السريعة","لأن بعضها قد يكون أكثر فائدة من غيره وفقًا لما نريد معرفته عن الحركة"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 40 — التمثيلات المتكافئة'),
('mcq', 5, 'يبين الشكل الآتي ثلاثة تمثيلات. أيّ العبارات الآتية تصف العلاقة بينها؟', null, '[{"src":"qimg/phys1/c2l3-o07-three.svg","alt":"ثلاثة تمثيلات متجاورة. جدول بيانات بعمودين: الزمن (s) 0.0 و1.0 و2.0 و3.0 و4.0، والموقع (m) 0.0 و4.0 و8.0 و12.0 و16.0. منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 4 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 16 بتدريج 2، وخط مستقيم من (0, 0) إلى (4, 16). نموذج جسيمي نقطي: خمس نقاط فوق محور الموقع (m) المدرّج من 0 إلى 16 بتدريج 4، والنقاط عند 0 و4 و8 و12 و16، ومكتوب أن الفترة بين كل نقطتين ثانية واحدة."}]'::jsonb, '["تصف ثلاثة أجسام مختلفة تتحرك جنبًا إلى جنب في الوقت نفسه","تصف جسمًا واحدًا يبتعد عن نقطة الأصل 4 m كل ثانية","يصف الجدول والمنحنى جسمًا متحركًا، والنموذج الجسيمي جسمًا ساكنًا","تصف جسمًا يبدأ من 16 m ويقترب من نقطة الأصل 4 m كل ثانية"]'::jsonb, 'فهم', 'تفسير تمثيلات', 'متوسط', 'الكتاب ص 40 — التمثيلات المتكافئة'),
('mcq', 6, 'يريد مدرب أن يعرف بسرعة متى وأين يتجاوز أحد عدّاءين الآخر في سباق. أيّ التمثيلات الآتية أنسب لذلك؟', null, null, '["وصف لفظي منفصل ومفصّل لحركة كل عدّاء","صورة فوتوغرافية واحدة للعدّاءين لحظة الانطلاق","نموذج جسيمي نقطي لحركة أحد العدّاءين فقط","منحنى (الموقع – الزمن) للعدّاءين معًا"]'::jsonb, 'تطبيق', 'اختيار التمثيل الأنسب', 'متوسط', 'الكتاب ص 40 — التمثيلات المتكافئة ودراسة حركة عدة أجسام'),
('mcq', 7, 'رسم طالب نموذجًا جسيميًا نقطيًا ومنحنى (الموقع – الزمن) لحركة واحدة. ما الذي يجب أن يقارنه ليتحقق من أن التمثيلين متكافئان؟', null, null, '["موقع الجسم في التمثيلين عند الأزمنة نفسها","عدد النقاط في النموذج بعدد خطوط الشبكة في المنحنى","طول الخط البياني بطول محور الموقع في المنحنى","لون النقاط في النموذج بلون الخط في المنحنى"]'::jsonb, 'فهم', 'تحقق من التكافؤ', 'صعب', 'الكتاب ص 42 — مراجعة 2-3 (السؤال 24)'),
('essay', 1, 'وضّح المقصود بالتمثيلات المتكافئة لوصف حركة جسم، واذكر أربعًا منها، وبيّن لماذا قد نفضّل أحدها على غيره في مسألة معينة.', null, null, null, 'فهم', 'شرح مفهوم', 'سهل', 'الكتاب ص 40 — التمثيلات المتكافئة'),
('essay', 2, 'يبين الشكل الآتي ثلاثة تمثيلات لحركة عربة. فسّر لماذا تعد هذه التمثيلات متكافئة، ثم اذكر معلومة واحدة يسهل استخراجها من كل تمثيل أكثر من غيره.', null, '[{"src":"qimg/phys1/c2l3-o07-e2.svg","alt":"ثلاثة تمثيلات متجاورة. جدول بيانات بعمودين: الزمن (s) 0.0 و1.0 و2.0 و3.0 و4.0، والموقع (m) 2.0 و5.0 و8.0 و11.0 و14.0. منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 4 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 16 بتدريج 2، وخط مستقيم من (0, 2) إلى (4, 14). نموذج جسيمي نقطي: خمس نقاط فوق محور الموقع (m) المدرّج من 0 إلى 16 بتدريج 4، والنقاط عند 2 و5 و8 و11 و14، ومكتوب أن الفترة بين كل نقطتين ثانية واحدة."}]'::jsonb, null, 'تحليل', 'تفسير تمثيلات', 'متوسط', 'الكتاب ص 40 — التمثيلات المتكافئة'),
('essay', 3, 'قال طالب: «جدول البيانات ومنحنى (الموقع – الزمن) لا يمكن أن يكونا متكافئين؛ لأن الجدول يعطي أرقامًا دقيقة والمنحنى مجرد رسم». قوّم رأي الطالب.', null, null, null, 'تقويم', 'تقويم رأي', 'صعب', 'الكتاب ص 40 — التمثيلات المتكافئة')
