from (values
('mcq', 1, 2, 'التمثيلات المتكافئة طرق مختلفة لوصف حركة الجسم نفسه (الكلمات، والصور، ومخططات الحركة، وجداول البيانات، ومنحنيات الموقع – الزمن)، وهي متكافئة لأنها تحتوي على المعلومات نفسها.', '["التكافؤ يعني تساوي المعلومات عن الحركة نفسها، لا تطابق الشكل لأجسام مختلفة.","التمثيلات المتكافئة تحمل المعلومات نفسها، لا معلومات مختلفة.","","التكافؤ لا يعني تساوي قيم الموقع والزمن؛ بل تساوي المعلومات بين التمثيلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:59.252Z"}'::jsonb),
('mcq', 2, 1, 'يمكن وصف الحركة بالكلمات، وبالصور (التمثيل التصويري)، ومخططات الحركة التوضيحية، وجداول البيانات، ومنحنيات (الموقع – الزمن)، وجميعها طرق متكافئة.', '["الكتلة والحجم خصائص للجسم وليست طرقًا لوصف حركته.","","جداول البيانات طريقة واحدة من عدة طرق متكافئة، وليست الوحيدة.","المنحنى طريقة واحدة من عدة طرق متكافئة تبين الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.252Z"}'::jsonb),
('mcq', 3, 0, 'التمثيلات المتكافئة تحتوي على المعلومات نفسها؛ ففي النموذج تقابل النقطة الأولى 0 s والثانية 1 s والثالثة 2 s، فيجب أن تقع النقطة الثالثة عند الموقع 6 m كما في الجدول.', '["","النقطة الثانية تقابل اللحظة 1 s؛ لأن أول نقطة عند 0 s.","هذا تبديل للزمن والموقع؛ فالموقع 6 m واللحظة 2 s.","التمثيلات المتكافئة تحتوي على المعلومات نفسها، فلا يختلف الموقع بين الجدول والنموذج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:59.252Z"}'::jsonb),
('mcq', 4, 3, 'مع أن التمثيلات تحمل المعلومات نفسها، فقد يكون بعضها أكثر فائدة من الآخر وفقًا لما نريد معرفته، فنختار أنسبها لحل نوع المسألة.', '["التمثيلات المتكافئة تحمل المعلومات نفسها، فلا ينفرد أحدها بجزء من الحركة.","لا يلزم استخدامها جميعًا؛ بل نختار أنسبها للمسألة.","اختيار التمثيل لا يعتمد على سرعة الجسم بل على ما نريد معرفته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.253Z"}'::jsonb),
('mcq', 5, 1, 'الجدول والمنحنى والنموذج الجسيمي كلها تبين المواقع 0 و4 و8 و12 و16 m عند 0 و1 و2 و3 و4 s؛ فهي تمثيلات متكافئة لحركة جسم واحد يبتعد 4 m كل ثانية.', '["التمثيلات الثلاثة تحمل البيانات نفسها، فهي لجسم واحد.","","النقاط في النموذج متباعدة بانتظام، فهو يصف جسمًا متحركًا كذلك.","الموقع يزداد مع الزمن من 0 إلى 16 m، فالجسم يبتعد لا يقترب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.253Z"}'::jsonb),
('mcq', 6, 3, 'عند تمثيل العدّاءين على منحنى (الموقع – الزمن) واحد، تبين نقطة تقاطع الخطين مباشرة متى وأين يكونان في الموقع نفسه؛ فهو أنسب التمثيلات لهذا الغرض.', '["الوصفان اللفظيان يحتاجان إلى حسابات لمقارنتهما، ولا يبينان نقطة التجاوز مباشرة.","صورة واحدة تبين لحظة واحدة فقط، ولا تبين تطور الحركة.","نموذج عدّاء واحد لا يسمح بالمقارنة بين العدّاءين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:59.253Z"}'::jsonb),
('mcq', 7, 0, 'التمثيلان متكافئان إذا حملا المعلومات نفسها، أي إذا أعطيا موقع الجسم نفسه عند كل لحظة؛ لذا نقارن المواقع عند الأزمنة نفسها.', '["","عدد خطوط الشبكة يتعلق بالتدريج المختار، ولا علاقة له بمعلومات الحركة.","طول الخط البياني لا يمثل كمية فيزيائية يقارن بها النموذج.","الألوان لا تحمل معلومات عن الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.253Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التمثيلات المتكافئة طرق مختلفة لوصف حركة الجسم نفسه، تحتوي جميعها على المعلومات نفسها حول الحركة. ومنها: الوصف بالكلمات، والصور (التمثيل التصويري)، ومخططات الحركة التوضيحية (النموذج الجسيمي النقطي)، وجداول البيانات، ومنحنيات (الموقع – الزمن). ومع أنها متكافئة فقد يكون بعضها أكثر فائدة وفقًا لما نريد معرفته؛ فمثلًا يبين منحنى (الموقع – الزمن) لجسمين مباشرة متى وأين يلتقيان.', '["التعريف: طرق مختلفة تحمل المعلومات نفسها","ذكر أربعة تمثيلات","بعضها أنسب من غيره بحسب المطلوب مع مثال"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"ذكر أربعة تمثيلات","marks":1},{"element":"سبب التفضيل","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["القول إن كل تمثيل يحمل معلومات مختلفة.","ذكر خصائص الجسم (الكتلة) ضمن التمثيلات."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:59.253Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التمثيلات متكافئة لأنها تحمل المعلومات نفسها: العربة تبدأ عند 2.0 m وتبتعد عن نقطة الأصل 3.0 m كل ثانية حتى تصل إلى 14.0 m عند 4.0 s؛ ففي الجدول القيم مكتوبة، وفي المنحنى الخط يمر بالنقاط (0, 2) و(1, 5) و(2, 8) و(3, 11) و(4, 14)، وفي النموذج الجسيمي النقاط عند المواقع نفسها. ومن الأمثلة: الجدول يعطي القيم الدقيقة للمواقع المقيسة، والمنحنى يسهل منه قراءة الموقع عند لحظة غير مقيسة مثل 2.5 s (9.5 m)، والنموذج الجسيمي يبين بصريًا أن المسافات بين المواقع المتتالية متساوية.', '["المواقع والأزمنة نفسها في التمثيلات الثلاثة","وصف الحركة: البداية 2.0 m وزيادة 3.0 m كل ثانية","معلومة مناسبة لكل تمثيل"]'::jsonb, '["عند 2.5 s: $2.0 + 2.5 \\times 3.0 = 9.5\\ \\text{m}$"]'::jsonb, '[{"element":"تعليل التكافؤ","marks":1.5},{"element":"المعلومات المميزة للتمثيلات الثلاثة","marks":1.5}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["القول إن النموذج الجسيمي يبدأ من نقطة الأصل.","إهمال الموقع الابتدائي 2.0 m."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.253Z"}'::jsonb),
('essay', 3, null::int, null, null, 'رأي الطالب غير صحيح؛ فالتكافؤ يعني أن التمثيلين يحتويان على المعلومات نفسها عن الحركة: كل صف في الجدول (زمن وموقع) تقابله نقطة على المنحنى بالإحداثيين نفسيهما، ويمكن استخراج أرقام الجدول من المنحنى والعكس. واختلاف طريقة العرض لا يعني اختلاف المعلومات، بل إن المنحنى يتيح أيضًا قراءة مواقع عند لحظات بين القياسات. أما اختيار أحدهما فيعتمد على ما نريد معرفته.', '["الحكم: الرأي غير صحيح","كل صف في الجدول يقابل نقطة على المنحنى","التكافؤ يعني تساوي المعلومات لا تشابه طريقة العرض"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بالتقابل بين الجدول والمنحنى","marks":1},{"element":"معنى التكافؤ","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الموافقة على رأي الطالب.","الخلط بين التكافؤ والتطابق في الشكل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.253Z"}'::jsonb)
