('mcq', 6, 'خرج أحمد في نزهة سيرًا على الأقدام، وبعد مدة بدأ صديقه نبيل السير خلفه من النقطة نفسها، ومُثّلت حركتاهما بالمنحنى الآتي. ما الزمن الذي سار خلاله أحمد قبل أن يبدأ نبيل المشي؟', null, '[{"src":"qimg/phys1/c2l3-o08-hike2.svg","alt":"منحنى (الموقع – الزمن) لشخصين: الزمن (h) أفقيًا من 0 إلى 2.5 بتدريج 0.5، والموقع (km) رأسيًا من 0 إلى 12 بتدريج 1. خط أحمد (أزرق) مستقيم من (0, 0) إلى (2.5, 10). خط نبيل (أحمر) مستقيم من (0.5, 0) إلى (2.5, 12)."}]'::jsonb, '["0.5 h","1.0 h","2.5 h","1.5 h"]'::jsonb, 'تطبيق', 'قراءة لحظة', 'سهل', 'الكتاب ص 41 — مسائل تدريبية (السؤال 18a)'),
('mcq', 7, 'انطلقت السيارة A من المدرسة بسرعة منتظمة 60 km/h، وبعد 0.50 h انطلقت السيارة B من المدرسة في الاتجاه نفسه بسرعة منتظمة 90 km/h. إذا مُثّلت حركتاهما بمنحنى (الموقع – الزمن) يبدأ زمنه لحظة انطلاق A، فما إحداثيا نقطة تقاطع الخطين؟', null, null, '["(1.0 h, 90 km)","(0.50 h, 30 km)","(1.5 h, 135 km)","(1.5 h, 90 km)"]'::jsonb, 'تحليل', 'حساب نقطة الالتقاء', 'صعب', 'الكتاب ص 55 — تقويم الفصل (السؤالان 52 و53)'),
('essay', 1, 'يمثل المنحنى الآتي حركة دراجتين A وB تتحركان على طريق مستقيم إحداهما نحو الأخرى. (a) حدد متى وأين تلتقي الدراجتان، وفسّر كيف عرفت ذلك. (b) أين تكون كل منهما عند 30 s؟', null, '[{"src":"qimg/phys1/c2l3-o08-e1.svg","alt":"منحنى (الموقع – الزمن) لدراجتين: الزمن (s) أفقيًا من 0 إلى 30 بتدريج 5، والموقع (m) رأسيًا من 0 إلى 300 بتدريج 50. الخط A (أزرق) مستقيم من (0, 0) إلى (30, 150). الخط B (أحمر) مستقيم من (0, 300) إلى (30, 0)."}]'::jsonb, null, 'تطبيق', 'تحديد نقطة الالتقاء', 'متوسط', 'الكتاب ص 40 — دراسة حركة عدة أجسام (مثال 2)'),
('essay', 2, 'تقع المدرسة عند نقطة الأصل، ويقع الشاطئ على بُعد 80 km منها على طريق مستقيم. عند الساعة 12:00 انطلقت السيارة A نحو الشاطئ من متجر يبعد 20 km عن المدرسة (على الطريق نفسه بين المدرسة والشاطئ) بسرعة منتظمة 40 km/h، وعند الساعة 12:30 انطلقت السيارة B من المدرسة نحو الشاطئ بسرعة منتظمة 120 km/h. صف منحنى (الموقع – الزمن) لكل سيارة (اعتبر الزمن صفرًا عند 12:00)، ثم حدد منه: متى وأين تتجاوز B السيارة A؟ وأيّ السيارتين تصل الشاطئ أولًا؟', null, null, null, 'تحليل', 'رسم منحنيين وتحديد التجاوز', 'صعب', 'الكتاب ص 55 — تقويم الفصل (السؤال 53)'),
('essay', 3, 'يمثل المنحنى الآتي حركة عدّاءين A وB على مضمار مستقيم. حدد كل لحظة يكون فيها العدّاءان في الموقع نفسه وموقعهما عندها، وصف ما يحدث عند كل منها، ثم حدد المتقدم عند 20 s.', null, '[{"src":"qimg/phys1/c2l3-o08-e3.svg","alt":"منحنى (الموقع – الزمن) لعدّاءين: الزمن (s) أفقيًا من 0 إلى 20 بتدريج 2.5، والموقع (m) رأسيًا من 0 إلى 100 بتدريج 10. الخط A (أزرق) مستقيم من (0, 0) إلى (20, 80). الخط B (أحمر) أفقي من (0, 30) إلى (10, 30) ثم مستقيم صاعد إلى (20, 90)."}]'::jsonb, null, 'تحليل', 'تحليل منحنيين متقاطعين', 'صعب', 'الكتاب ص 54 — تقويم الفصل (السؤال 43)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
