('mcq', 1, 1, 'يكون العدّاءان في الموقع نفسه عند نقطة تقاطع خطيهما، وهي (20 s, 60 m)؛ فيتجاوز B العدّاء A عند 20 s وعلى بُعد 60 m من نقطة الأصل.', '["عند 8 s يمر B بنقطة الأصل، بينما يكون A عند 24 m؛ فهما ليسا في الموقع نفسه.","","عند 30 s يكون A عند 90 m وB عند 110 m؛ فقد تجاوزه B قبل ذلك.","هذا تبديل لإحداثيي نقطة التقاطع؛ فالزمن 20 s والموقع 60 m."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-18T12:34:59.254Z"}'::jsonb),
('mcq', 2, 3, 'عند 25 s يقع خط B فوق خط A (B عند 85 m وA عند 75 m)؛ لأن B تجاوز A عند 20 s، فهو المتقدم.', '["تقدم A في البداية لا يعني بقاءه متقدمًا؛ فقد تجاوزه B عند 20 s.","الخطان يتقاطعان عند 20 s فقط، وعند 25 s يكونان في موقعين مختلفين.","نقطة بداية الخط لا تحدد المتقدم عند 25 s؛ بل موقعا العدّاءين عند تلك اللحظة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (61%)"}],"at":"2026-11-18T12:34:59.254Z"}'::jsonb),
('mcq', 3, 0, 'عند 10 s يكون A عند 30 m وB عند 10 m، فالمسافة الفاصلة بينهما $30 - 10 = 20\ \text{m}$.', '["","40 m هي المسافة الفاصلة بينهما عند 0 s لا عند 10 s.","10 m هو موقع B عند 10 s، لا المسافة بين العدّاءين.","30 m هو موقع A عند 10 s، لا المسافة بين العدّاءين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (61%)"}],"at":"2026-11-18T12:34:59.254Z"}'::jsonb),
('mcq', 4, 2, 'كان A عند نقطة الأصل عند 0 s، وفي تلك اللحظة يبدأ خط B من الموقع $-40\ \text{m}$، أي على بُعد 40 m من نقطة الأصل في الاتجاه السالب (خلف خط البداية).', '["خط B لا يبدأ من نقطة الأصل؛ بل من $-40\\ \\text{m}$.","أُهملت الإشارة السالبة للموقع الابتدائي لـ B.","","60 m هو موقع A وB عند لحظة التقاطع، لا موقع B عند 0 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-18T12:34:59.254Z"}'::jsonb),
('mcq', 5, 2, 'يلحق نبيل بأحمد عند نقطة تقاطع خطيهما، وهي (1.5 h, 6 km).', '["عند 0.5 h بدأ نبيل السير، وكان أحمد حينها على بُعد 2 km منه.","عند 2.5 h يكون نبيل عند 12 km وأحمد عند 10 km؛ أي أنه تجاوزه سابقًا.","","1.0 h هي مدة سير نبيل حتى اللقاء لا لحظة اللقاء، و4 km موقع أحمد عند 1.0 h."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (62%)"}],"at":"2026-11-18T12:34:59.254Z"}'::jsonb),
('mcq', 6, 0, 'يبدأ خط نبيل من محور الزمن عند 0.5 h، أي أنه بدأ المشي بعد 0.5 h من بدء أحمد.', '["","1.0 h هي مدة سير نبيل حتى لحاقه بأحمد.","2.5 h هي نهاية الفترة الممثلة على المنحنى.","1.5 h هي لحظة لحاق نبيل بأحمد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (62%)"}],"at":"2026-11-18T12:34:59.255Z"}'::jsonb),
('mcq', 7, 3, 'موقع A بعد زمن $t$ هو $60t$، وموقع B هو $90(t - 0.50)$. عند التقاطع: $60t = 90(t - 0.50)$، ومنها $t = 1.5\ \text{h}$، والموقع $60 \times 1.5 = 90\ \text{km}$.', '["1.0 h هو زمن سير B حتى اللقاء مقيسًا من لحظة انطلاقه، لا قراءة الساعة منذ انطلاق A.","عند 0.50 h انطلقت B من المدرسة، وكانت A على بُعد 30 km؛ فهما ليسا في الموقع نفسه.","حُسب موقع B بضرب 90 km/h في 1.5 h مع إهمال تأخر انطلاقها 0.50 h.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.255Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) الدراجتان تكونان في الموقع نفسه عند نقطة تقاطع خطيهما، وهي (20 s, 100 m)؛ فتلتقيان عند 20 s على بُعد 100 m من نقطة الأصل. (b) عند 30 s تكون A عند 150 m، وتكون B عند نقطة الأصل (0 m)؛ أي أنهما تجاوزتا بعضهما.', '["نقطة التقاطع تعني الموقع نفسه في اللحظة نفسها","اللقاء عند 20 s","على بُعد 100 m","عند 30 s: A عند 150 m وB عند 0 m"]'::jsonb, '["A تبدأ من 0 m وتصل إلى 150 m عند 30 s (5 m كل ثانية)","B تبدأ من 300 m وتصل إلى 0 m عند 30 s (تقترب 10 m كل ثانية)","التقاطع: $5t = 300 - 10t$ ومنها $t = 20\\ \\text{s}$، والموقع $5 \\times 20 = 100\\ \\text{m}$"]'::jsonb, '[{"element":"تفسير نقطة التقاطع","marks":1},{"element":"زمن اللقاء","marks":1},{"element":"مكان اللقاء","marks":1},{"element":"الموقعان عند 30 s","marks":1}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["قراءة زمن التقاطع من محور الموقع.","القول إن الدراجتين تتوقفان عند نقطة التقاطع."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.255Z"}'::jsonb),
('essay', 2, null::int, null, null, 'خط A مستقيم يبدأ من (0 h, 20 km) ويزداد 40 km كل ساعة فيصل إلى (1.5 h, 80 km). خط B يبدأ من (0.5 h, 0 km) ويزداد 120 km كل ساعة فيصل إلى 80 km عند $0.5 + 80 \div 120 \approx 1.17\ \text{h}$. يتقاطع الخطان عند (1.0 h, 60 km)؛ أي أن B تتجاوز A الساعة 1:00 على بُعد 60 km من المدرسة. وتصل B إلى الشاطئ أولًا (نحو الساعة 1:10)، بينما تصل A الساعة 1:30.', '["خط A من (0, 20 km) إلى (1.5 h, 80 km)","خط B من (0.5 h, 0) إلى نحو (1.17 h, 80 km)","التجاوز عند 1.0 h (الساعة 1:00) وعلى بُعد 60 km","B تصل أولًا"]'::jsonb, '["موقع A: $\\boldsymbol{d} = 20 + 40t$","موقع B: $\\boldsymbol{d} = 120(t - 0.5)$","عند التقاطع: $20 + 40t = 120t - 60$، ومنها $t = 1.0\\ \\text{h}$ والموقع $60\\ \\text{km}$","وصول A: $(80 - 20) \\div 40 = 1.5\\ \\text{h}$، ووصول B: $0.5 + 80 \\div 120 \\approx 1.17\\ \\text{h}$"]'::jsonb, '[{"element":"المنحنيان","marks":1},{"element":"لحظة التجاوز ومكانه","marks":2},{"element":"السيارة الأسبق","marks":1}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["بدء خط A من نقطة الأصل بدل 20 km.","بدء خط B عند الزمن صفر بدل 0.5 h.","الاستنتاج أن A تصل أولًا لأنها بدأت أقرب."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.255Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يتقاطع الخطان مرتين: الأولى عند (7.5 s, 30 m)، وفيها يمر A بالعدّاء B وهو واقف عند 30 m (فخط B أفقي من 0 إلى 10 s)، فيصبح A متقدمًا. والثانية عند (15 s, 60 m)، وفيها يلحق B بالعدّاء A بعد أن بدأ الحركة عند 10 s ويتجاوزه. عند 20 s يكون B عند 90 m وA عند 80 m، فالمتقدم B.', '["التقاطع الأول (7.5 s, 30 m): A يتجاوز B الساكن","التقاطع الثاني (15 s, 60 m): B يتجاوز A","عند 20 s: B متقدم (90 m مقابل 80 m)"]'::jsonb, '["A: يزداد موقعه 4 m كل ثانية من نقطة الأصل","B: ساكن عند 30 m حتى 10 s، ثم يزداد موقعه 6 m كل ثانية","التقاطع الأول: $4t = 30$ ومنها $t = 7.5\\ \\text{s}$","التقاطع الثاني: $4t = 30 + 6(t - 10)$ ومنها $t = 15\\ \\text{s}$ والموقع 60 m"]'::jsonb, '[{"element":"التقاطع الأول ووصفه","marks":1.5},{"element":"التقاطع الثاني ووصفه","marks":1.5},{"element":"المتقدم عند 20 s","marks":1}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الاكتفاء بنقطة تقاطع واحدة.","اعتبار B متحركًا من البداية.","القول إن العدّاءين يتصادمان عند التقاطع."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:59.256Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
