select (select id from public.objectives where code = 'P1-C2-L3-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل المنحنى الآتي حركة قرص مطاطي ينزلق على الجليد. ما إزاحة القرص بين اللحظتين 2.0 s و5.0 s؟', null, '[{"src":"qimg/phys1/c2l3-o09-puck.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 6 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 100 بتدريج 10. خط مستقيم من النقطة (0, 0) إلى النقطة (6, 90)."}]'::jsonb, '["75 m","30 m","45 m","105 m"]'::jsonb, 'تطبيق', 'حساب إزاحة من منحنى', 'متوسط', 'الكتاب ص 42 — مراجعة 2-3 (السؤال 22)'),
('mcq', 2, 'يمثل المنحنى الآتي حركة سيارة على طريق مستقيم يمتد شرقًا وغربًا، والاتجاه الموجب نحو الشرق. ما إزاحة السيارة خلال الفترة من 0 s إلى 6 s؟', null, '[{"src":"qimg/phys1/c2l3-o09-neg.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 6 بتدريج 1، والموقع (m) رأسيًا من −40 إلى 70 بتدريج 10، ومحور الزمن عند الموقع 0. خط مستقيم من النقطة (0, 60) إلى النقطة (6, −30) يقطع محور الزمن عند 4."}]'::jsonb, '["90 m نحو الغرب","90 m نحو الشرق","30 m نحو الغرب","60 m نحو الشرق"]'::jsonb, 'تطبيق', 'حساب إزاحة سالبة', 'صعب', 'الكتاب ص 38 — تحديد إزاحة الجسم من منحنى (الموقع – الزمن)'),
('mcq', 3, 'يمثل المنحنى الآتي حركة عامل يتنقل في ممر مستقيم داخل مستودع. ما إزاحة العامل خلال الفترة من 0 s إلى 10 s؟', null, '[{"src":"qimg/phys1/c2l3-o09-trip.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 10 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 30 بتدريج 5. خط متكسر يصل النقاط (0, 5) ثم (4, 25) ثم (6, 25) ثم (10, 15)."}]'::jsonb, '["30 m","15 m","25 m","10 m"]'::jsonb, 'تحليل', 'التمييز بين الإزاحة والمسافة', 'متوسط', 'الكتاب ص 38 — تحديد إزاحة الجسم من منحنى (الموقع – الزمن)'),
('mcq', 4, 'يمثل المنحنى الآتي حركة جسم على خط مستقيم. ما إزاحة الجسم خلال الفترة من 3 s إلى 7 s؟', null, '[{"src":"qimg/phys1/c2l3-o09-flat.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 10 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 70 بتدريج 10. خط متكسر يصل النقاط (0, 0) ثم (3, 30) ثم (7, 30) ثم (10, 60)."}]'::jsonb, '["30 m","0 m","60 m","4 m"]'::jsonb, 'تطبيق', 'حساب إزاحة من منحنى', 'سهل', 'الكتاب ص 38 — تحديد إزاحة الجسم من منحنى (الموقع – الزمن)'),
('mcq', 5, 'كيف تحدد إزاحة جسم خلال فترة زمنية معينة من منحنى (الموقع – الزمن)؟', null, null, '["بقراءة الموقعين عند بداية الفترة ونهايتها، ثم طرح الموقع الابتدائي من النهائي","بقراءة الموقع عند نهاية الفترة فقط، فهو يساوي الإزاحة دائمًا","بقراءة طول الفترة الزمنية على المحور الأفقي للمنحنى","بقراءة الموقعين عند بداية الفترة ونهايتها، ثم جمعهما معًا"]'::jsonb, 'فهم', 'إجراء', 'سهل', 'الكتاب ص 38 — تحديد إزاحة الجسم من منحنى (الموقع – الزمن)'),
('mcq', 6, 'يمثل المنحنى الآتي حركة لعبة على مسار مستقيم. ما إزاحة اللعبة بين اللحظتين 1.0 s و4.0 s؟', null, '[{"src":"qimg/phys1/c2l3-o09-cross.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 5 بتدريج 1، والموقع (m) رأسيًا من −30 إلى 40 بتدريج 10، ومحور الزمن عند الموقع 0. خط مستقيم من النقطة (0, −20) إلى النقطة (5, 30)."}]'::jsonb, '["20 m","10 m","30 m","40 m"]'::jsonb, 'تطبيق', 'حساب إزاحة عبر نقطة الأصل', 'متوسط', 'الكتاب ص 38 — تحديد إزاحة الجسم من منحنى (الموقع – الزمن)'),
('mcq', 7, 'يمثل المنحنى الآتي حركة جسمين A وB خلال 4 s. أيّ العبارات الآتية صحيحة بشأن إزاحتيهما خلال هذه الفترة؟', null, '[{"src":"qimg/phys1/c2l3-o09-two.svg","alt":"منحنى (الموقع – الزمن) لجسمين: الزمن (s) أفقيًا من 0 إلى 4 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 70 بتدريج 10. الخط A (أزرق) مستقيم من (0, 0) إلى (4, 40). الخط B (أحمر) مستقيم من (0, 20) إلى (4, 60)."}]'::jsonb, '["إزاحة B أكبر؛ لأنه أبعد عن نقطة الأصل طوال الفترة","إزاحة A أكبر؛ لأنه بدأ الحركة من نقطة الأصل","إزاحة B تساوي 60 m وإزاحة A تساوي 40 m","لكل منهما إزاحة 40 m مع أن موقعيهما مختلفان"]'::jsonb, 'تحليل', 'مقارنة إزاحتين', 'صعب', 'الكتاب ص 38 — تحديد إزاحة الجسم من منحنى (الموقع – الزمن)'),
('essay', 1, 'يمثل المنحنى الآتي حركة روبوت على مسار مستقيم. حدد إزاحة الروبوت خلال كل من الفترات: (a) من 0 إلى 10 s، (b) من 10 s إلى 20 s، (c) من 20 s إلى 30 s، (d) من 0 إلى 40 s. ثم احسب المسافة الكلية التي قطعها خلال 40 s، وقارنها بالإزاحة الكلية.', null, '[{"src":"qimg/phys1/c2l3-o09-e1.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 40 بتدريج 5، والموقع (m) رأسيًا من 0 إلى 50 بتدريج 10. خط متكسر يصل النقاط (0, 0) ثم (10, 40) ثم (20, 40) ثم (30, 10) ثم (40, 10)."}]'::jsonb, null, 'تطبيق', 'حساب إزاحات من منحنى', 'سهل', 'الكتاب ص 38 — تحديد إزاحة الجسم من منحنى (الموقع – الزمن)'),
('essay', 2, 'يمثل المنحنى الآتي حركة حافلة على طريق مستقيم يمتد شرقًا وغربًا، والاتجاه الموجب نحو الشرق. حدد مقدار إزاحة الحافلة واتجاهها خلال الفترة من 0 إلى 6 s، وخلال الفترة من 2 s إلى 4 s.', null, '[{"src":"qimg/phys1/c2l3-o09-e2.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 6 بتدريج 1، والموقع (m) رأسيًا من −60 إلى 120 بتدريج 20، ومحور الزمن عند الموقع 0. خط مستقيم من النقطة (0, 100) إلى النقطة (6, −50) يقطع محور الزمن عند 4."}]'::jsonb, null, 'تطبيق', 'حساب إزاحة سالبة', 'متوسط', 'الكتاب ص 38 — تحديد إزاحة الجسم من منحنى (الموقع – الزمن)'),
('essay', 3, 'يمثل المنحنى الآتي حركة متزلج على مسار مستقيم. قال طالب: «إزاحة المتزلج خلال الفترة من 0 إلى 8 s تساوي 55 m؛ لأن هذا موقعه عند 8 s». قوّم قول الطالب، وحدد الإزاحة الصحيحة، ووضّح متى تكون طريقته صحيحة.', null, '[{"src":"qimg/phys1/c2l3-o09-e3.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 8 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 60 بتدريج 5. خط مستقيم من النقطة (0, 15) إلى النقطة (8, 55)."}]'::jsonb, null, 'تقويم', 'تقويم حل', 'صعب', 'الكتاب ص 38 — تحديد إزاحة الجسم من منحنى (الموقع – الزمن)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L3-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'من المنحنى: الموقع عند 2.0 s هو 30 m وعند 5.0 s هو 75 m، فالإزاحة $\Delta \boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 75 - 30 = 45\ \text{m}$ في الاتجاه الموجب.', '["75 m هو موقع القرص عند 5.0 s، لا إزاحته خلال الفترة.","30 m هو موقع القرص عند 2.0 s، لا إزاحته.","","جُمع الموقعان بدل طرح الموقع الابتدائي من النهائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-18T12:34:59.256Z"}'::jsonb),
('mcq', 2, 0, 'الموقع الابتدائي 60 m والموقع النهائي $-30\ \text{m}$، فالإزاحة $\Delta \boldsymbol{d} = -30 - 60 = -90\ \text{m}$، والإشارة السالبة تعني أنها نحو الغرب.', '["","المقدار صحيح لكن الإشارة أُهملت؛ فالموقع تناقص، فالإزاحة نحو الغرب.","30 m غربًا هو الموقع النهائي للسيارة، لا إزاحتها.","60 m شرقًا هو الموقع الابتدائي للسيارة، لا إزاحتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-18T12:34:59.256Z"}'::jsonb),
('mcq', 3, 3, 'الموقع عند 0 s هو 5 m وعند 10 s هو 15 m، فالإزاحة $15 - 5 = 10\ \text{m}$ في الاتجاه الموجب، بغض النظر عن ذهابه إلى 25 m ثم عودته.', '["30 m هي المسافة الكلية (20 m ذهابًا ثم 10 m عودة)، لا الإزاحة.","15 m هو الموقع النهائي للعامل، وقد أُهمل موقعه الابتدائي 5 m.","25 m هو أبعد موقع وصل إليه العامل، لا إزاحته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-18T12:34:59.256Z"}'::jsonb),
('mcq', 4, 1, 'في الفترة من 3 s إلى 7 s يبقى الموقع ثابتًا عند 30 m (خط أفقي)، فالإزاحة $30 - 30 = 0\ \text{m}$.', '["30 m هو موقع الجسم خلال الفترة، لا التغير في موقعه.","","60 m هو موقع الجسم عند 10 s، خارج الفترة المطلوبة.","4 هو طول الفترة الزمنية بالثواني، لا الإزاحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-18T12:34:59.256Z"}'::jsonb),
('mcq', 5, 0, 'الإزاحة هي التغير في الموقع: $\Delta \boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i$؛ فنقرأ من المنحنى الموقع عند نهاية الفترة والموقع عند بدايتها ثم نطرح.', '["","الموقع النهائي يساوي الإزاحة فقط إذا بدأ الجسم من نقطة الأصل، لا دائمًا.","طول الفترة الزمنية هو $\\Delta t$، وليس الإزاحة.","الإزاحة فرق بين الموقعين لا مجموعهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.257Z"}'::jsonb),
('mcq', 6, 2, 'الموقع عند 1.0 s هو $-10\ \text{m}$ وعند 4.0 s هو 20 m، فالإزاحة $\Delta \boldsymbol{d} = 20 - (-10) = 30\ \text{m}$.', '["20 m هو الموقع عند 4.0 s، وقد أُهمل الموقع الابتدائي.","أُهملت إشارة الموقع الابتدائي فطُرح 10 m بدل $-10\\ \\text{m}$.","","حُسبت الإزاحة من 0 s بدل 1.0 s: $20 - (-20) = 40\\ \\text{m}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-18T12:34:59.257Z"}'::jsonb),
('mcq', 7, 3, 'A: من 0 إلى 40 m، فإزاحته 40 m. B: من 20 m إلى 60 m، فإزاحته $60 - 20 = 40\ \text{m}$. فالإزاحتان متساويتان مع اختلاف الموقعين.', '["البعد عن نقطة الأصل (الموقع) لا يحدد الإزاحة؛ بل التغير في الموقع.","بداية الحركة من نقطة الأصل لا تجعل الإزاحة أكبر؛ فكلاهما تغير موقعه 40 m.","60 m هو الموقع النهائي لـ B، لا إزاحته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.257Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) من 0 إلى 40 m: الإزاحة $+40\ \text{m}$. (b) الموقع ثابت عند 40 m: الإزاحة 0 m. (c) من 40 m إلى 10 m: الإزاحة $-30\ \text{m}$ (نحو نقطة الأصل). (d) من 0 إلى 10 m: الإزاحة $+10\ \text{m}$. المسافة الكلية $40 + 30 = 70\ \text{m}$، وهي أكبر من مقدار الإزاحة الكلية 10 m لأن الروبوت عاد جزءًا من الطريق.', '["(a) $+40\\ \\text{m}$","(b) 0 m","(c) $-30\\ \\text{m}$","(d) $+10\\ \\text{m}$","المسافة 70 m أكبر من مقدار الإزاحة"]'::jsonb, '["$\\Delta \\boldsymbol{d} = \\boldsymbol{d}_f - \\boldsymbol{d}_i$ لكل فترة","(c) $10 - 40 = -30\\ \\text{m}$","(d) $10 - 0 = 10\\ \\text{m}$","المسافة $= 40 + 0 + 30 + 0 = 70\\ \\text{m}$"]'::jsonb, '[{"element":"(a) و(b)","marks":1},{"element":"(c) بالإشارة الصحيحة","marks":1},{"element":"(d)","marks":1},{"element":"المسافة والمقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["إهمال الإشارة السالبة في (c).","اعتبار الإزاحة الكلية 70 m.","اعتبار إزاحة الفترة (b) مساوية 40 m."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.257Z"}'::jsonb),
('essay', 2, null::int, null, null, 'من 0 إلى 6 s: الموقع الابتدائي 100 m والنهائي $-50\ \text{m}$، فالإزاحة $-50 - 100 = -150\ \text{m}$، أي 150 m نحو الغرب. من 2 s إلى 4 s: الموقع عند 2 s هو 50 m وعند 4 s هو 0 m، فالإزاحة $0 - 50 = -50\ \text{m}$، أي 50 m نحو الغرب.', '["قراءة المواقع 100 و50 و0 و$-50\\ \\text{m}$","الإزاحة الأولى 150 m غربًا","الإزاحة الثانية 50 m غربًا"]'::jsonb, '["$\\Delta \\boldsymbol{d} = \\boldsymbol{d}_f - \\boldsymbol{d}_i$","$\\Delta \\boldsymbol{d}_1 = -50 - 100 = -150\\ \\text{m}$","$\\Delta \\boldsymbol{d}_2 = 0 - 50 = -50\\ \\text{m}$"]'::jsonb, '[{"element":"قراءة المواقع","marks":1},{"element":"الإزاحة الأولى مقدارًا واتجاهًا","marks":1},{"element":"الإزاحة الثانية مقدارًا واتجاهًا","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["حساب الإزاحة الأولى 50 m بإهمال إشارة الموقع النهائي.","ذكر المقدار دون الاتجاه."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-18T12:34:59.257Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح؛ فالإزاحة هي التغير في الموقع لا الموقع النهائي. المتزلج بدأ من 15 m لا من نقطة الأصل، فالإزاحة $\Delta \boldsymbol{d} = 55 - 15 = 40\ \text{m}$ في الاتجاه الموجب. وتكون طريقة الطالب صحيحة فقط إذا كان الموقع الابتدائي صفرًا (بدأ الجسم من نقطة الأصل).', '["الحكم: القول غير صحيح","الإزاحة = 40 m","شرط صحة طريقة الطالب: البدء من نقطة الأصل"]'::jsonb, '["$\\boldsymbol{d}_i = 15\\ \\text{m}$ و$\\boldsymbol{d}_f = 55\\ \\text{m}$","$\\Delta \\boldsymbol{d} = 55 - 15 = 40\\ \\text{m}$"]'::jsonb, '[{"element":"الحكم والتعليل","marks":1},{"element":"الإزاحة الصحيحة","marks":1},{"element":"شرط الصحة","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الموافقة على قول الطالب.","جمع الموقعين: 70 m."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.257Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
