insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L3-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يجري عدّاء على مضمار أفقي مستقيم، لكن منحنى (الموقع – الزمن) لحركته خط مائل صاعد. ما تفسير ذلك؟', null, null, '["لأن المنحنى يبين تغير موقع العدّاء مع الزمن، وليس صورة لمسار حركته","لأن المضمار في الحقيقة كان صاعدًا ولم يكن أفقيًا","لأن الرسم خاطئ؛ فالمضمار الأفقي يمثله خط أفقي على المنحنى","لأن العدّاء كان يرتفع إلى أعلى مع كل خطوة أثناء الجري"]'::jsonb, 'فهم', 'تفسير مفهوم خاطئ', 'سهل', 'الكتاب ص 38 — منحنى (الموقع – الزمن) ليس تصويرًا للمسار'),
('mcq', 2, 'ماذا تعني نقطة تقاطع الخطين البيانيين لجسمين على منحنى (الموقع – الزمن) واحد؟', null, null, '["أن الجسمين تصادما حتمًا في تلك اللحظة","أن الجسمين بدآ الحركة من الموقع نفسه","أن الجسمين في الموقع نفسه في تلك اللحظة","أن الجسمين توقفا عن الحركة في تلك اللحظة"]'::jsonb, 'فهم', 'تفسير نقطة التقاطع', 'سهل', 'الكتاب ص 42 — نقطة تقاطع الخطين البيانيين'),
('mcq', 3, 'يتسابق عدّاءان على مضمار مستقيم، ولكل منهما ممر خاص به، وتقاطع خطاهما على منحنى (الموقع – الزمن). لماذا لا يعني هذا التقاطع أنهما تصادما؟', null, null, '["لأن خطي العدّاءين لا يتقاطعان أبدًا على المنحنى","لأنهما في الموقع نفسه على طول المضمار لكن كلٌّ في ممره","لأن التقاطع يعني أن أحدهما توقف في ممره لينتظر الآخر","لأنهما يكونان في موقعين مختلفين عند نقطة التقاطع"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 42 — نقطة تقاطع الخطين البيانيين'),
('mcq', 4, 'يمثل المنحنى الآتي حركة سيارة على طريق مستقيم أفقي. قال طالب: «صعدت السيارة تلًّا ثم نزلت منه». أيّ التفسيرات الآتية صحيح؟', null, '[{"src":"qimg/phys1/c2l3-o10-hill.svg","alt":"منحنى (الموقع – الزمن): الزمن (s) أفقيًا من 0 إلى 10 بتدريج 1، والموقع (m) رأسيًا من 0 إلى 60 بتدريج 10. خط متكسر يصل النقاط (0, 0) ثم (5, 50) ثم (10, 0)."}]'::jsonb, '["صعدت السيارة تلًّا ارتفاعه 50 m في 5 s ثم نزلت منه","تحركت السيارة مبتعدة عن نقطة الأصل مدة 10 s دون أن تعود","تحركت السيارة على مسار منحنٍ على شكل قوس","ابتعدت عن نقطة الأصل 50 m خلال 5 s، ثم عادت إليها"]'::jsonb, 'تحليل', 'تصحيح فهم خاطئ', 'متوسط', 'الكتاب ص 38 — منحنى (الموقع – الزمن) ليس تصويرًا للمسار'),
('mcq', 5, 'ظن طالب أن الجزء الأفقي في منحنى (الموقع – الزمن) لكرة يعني أنها كانت تتدحرج على أرض أفقية. ما المعنى الصحيح لهذا الجزء الأفقي؟', null, null, '["الكرة تتحرك بانتظام على أرض أفقية","الكرة تحركت ثم عادت إلى موقعها نفسه","الكرة ساكنة في موقع ثابت طوال تلك الفترة","الكرة موجودة عند نقطة الأصل طوال تلك الفترة"]'::jsonb, 'فهم', 'تصحيح فهم خاطئ', 'متوسط', 'الكتاب ص 38 — منحنى (الموقع – الزمن) ليس تصويرًا للمسار'),
('mcq', 6, 'يمثل المنحنى الآتي حركة سيارتين A وB في مسارين متجاورين على طريق سريع مستقيم. استنتج طالب أن السيارتين تصادمتا عند 20 s. ما تقويم هذا الاستنتاج؟', null, '[{"src":"qimg/phys1/c2l3-o10-cross.svg","alt":"منحنى (الموقع – الزمن) لسيارتين: الزمن (s) أفقيًا من 0 إلى 30 بتدريج 5، والموقع (m) رأسيًا من 0 إلى 100 بتدريج 10. الخط A (أزرق) مستقيم من (0, 0) إلى (30, 90). الخط B (أحمر) مستقيم من (0, 20) إلى (30, 80). يتقاطع الخطان عند (20, 60)."}]'::jsonb, '["غير صحيح؛ فالسيارتان متجاورتان عند 60 m لحظة 20 s","صحيح؛ لأن الخطين البيانيين للسيارتين يلتقيان في نقطة واحدة","غير صحيح؛ لأن التقاطع يعني أن المسافة بين السيارتين 60 m","صحيح؛ لأن خطي السيارتين يتوقفان عند نقطة التقاطع"]'::jsonb, 'تقويم', 'تقويم استنتاج', 'متوسط', 'الكتاب ص 42 — نقطة تقاطع الخطين البيانيين'),
('mcq', 7, 'ينزلق متزلج إلى أسفل منحدر مستقيم، واختير الاتجاه الموجب إلى أسفل المنحدر ونقطة الأصل عند قمته. رُسم منحنى (الموقع – الزمن) لحركته فكان خطًا صاعدًا، فاعترض طالب قائلًا إن الخط يجب أن يكون هابطًا لأن المتزلج ينزل. أيّ العبارات الآتية صحيحة؟', null, null, '["اعتراض الطالب صحيح؛ فالخط يجب أن يكون هابطًا لأن المتزلج ينزل","الخط يجب أن يكون أفقيًا؛ لأن المتزلج يتحرك على سطح مستوٍ","الخط الصاعد يعني أن المتزلج يصعد المنحدر لا ينزل منه","الخط الصاعد صحيح؛ لأن موقع المتزلج يزداد في الاتجاه الموجب المختار"]'::jsonb, 'تحليل', 'تصحيح فهم خاطئ', 'صعب', 'الكتاب ص 38 — منحنى (الموقع – الزمن) ليس تصويرًا للمسار'),
('essay', 1, 'فسّر لماذا لا يعد منحنى (الموقع – الزمن) تصويرًا لمسار حركة جسم، مستعينًا بمثال عدّاء يجري على مضمار أفقي مستقيم.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 38 — منحنى (الموقع – الزمن) ليس تصويرًا للمسار'),
('essay', 2, 'يمثل المنحنى الآتي حركة سبّاحين A وB في مسبح طوله 50 m، وكلٌّ منهما في حارة خاصة به: A ينطلق من أحد طرفي المسبح وB من الطرف الآخر. (a) حدد إحداثيي نقطة تقاطع الخطين، وفسّر معناها. (b) هل يتصادم السبّاحان؟ فسّر. (c) أين يكون كل منهما عند 30 s؟', null, '[{"src":"qimg/phys1/c2l3-o10-e2.svg","alt":"منحنى (الموقع – الزمن) لسبّاحين: الزمن (s) أفقيًا من 0 إلى 30 بتدريج 5، والموقع (m) رأسيًا من 0 إلى 50 بتدريج 5. الخط A (أزرق) مستقيم من (0, 0) إلى (30, 45). الخط B (أحمر) مستقيم من (0, 50) إلى (30, 20)."}]'::jsonb, null, 'تحليل', 'تفسير نقطة التقاطع', 'متوسط', 'الكتاب ص 42 — نقطة تقاطع الخطين البيانيين'),
('essay', 3, 'تتحرك حافلة على طريق جبلي كثير المنعطفات، وقيس موقعها على طول الطريق من نقطة البداية، فكان منحنى (الموقع – الزمن) لحركتها خطًا مستقيمًا صاعدًا. قال طالب: «هذا المنحنى خاطئ، لأن الطريق متعرج فيجب أن يكون المنحنى متعرجًا أيضًا». قوّم قول الطالب.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 38 — منحنى (الموقع – الزمن) ليس تصويرًا للمسار')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
