from (values
('mcq', 1, 0, 'منحنى (الموقع – الزمن) ليس تصويرًا لمسار الحركة؛ فميل الخط يعني أن موقع العدّاء يزداد مع الزمن، بينما مساره نفسه على مستوى أفقي.', '["","شكل الخط لا يدل على شكل المضمار؛ فالمضمار أفقي والخط مائل.","الخط الأفقي يعني أن الموقع ثابت (سكون)، لا أن المسار أفقي.","المحور الرأسي يمثل الموقع على المضمار، لا الارتفاع عن الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.258Z"}'::jsonb),
('mcq', 2, 2, 'نقطة تقاطع الخطين البيانيين تخبرك متى يكون الجسمان في الموقع نفسه، ولا تعني بالضرورة أنهما يتصادمان.', '["التقاطع لا يعني بالضرورة التصادم؛ فقد يكون لكل جسم مسار خاص به.","الموقع الابتدائي يُقرأ عند $t = 0$، والتقاطع قد يحدث عند أي لحظة.","","الخطان يستمران بعد نقطة التقاطع، فالجسمان لا يتوقفان بالضرورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.258Z"}'::jsonb),
('mcq', 3, 1, 'التقاطع يعني أن للعدّاءين الموقع نفسه على طول المضمار في تلك اللحظة، لكن كل منهما في ممره الخاص، فيتجاوز أحدهما الآخر دون تصادم.', '["الخطان قد يتقاطعان عندما يتجاوز أحد العدّاءين الآخر، وهذا ما حدث فعلًا.","","التقاطع لا يتطلب توقف أي منهما؛ فقد يكونان متحركين معًا.","عند نقطة التقاطع يكون موقعاهما متساويين لا مختلفين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.258Z"}'::jsonb),
('mcq', 4, 3, 'المنحنى ليس صورة للطريق؛ فالجزء الصاعد يعني أن الموقع يزداد من 0 إلى 50 m خلال 5 s (ابتعاد)، والجزء الهابط يعني أن الموقع يتناقص إلى الصفر عند 10 s (عودة إلى نقطة الأصل).', '["هذا خلط بين المنحنى ومسار الحركة؛ فالطريق أفقي، والمحور الرأسي يمثل الموقع لا الارتفاع.","بعد 5 s يتناقص الموقع، فالسيارة تعود نحو نقطة الأصل.","شكل المنحنى لا يصف شكل المسار؛ فالطريق مستقيم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.258Z"}'::jsonb),
('mcq', 5, 2, 'الخط الأفقي يعني أن موقع الكرة لا يتغير مع مرور الزمن؛ فهي ساكنة في موقع ثابت، ولا علاقة لذلك بشكل الأرض.', '["هذا خلط بين المنحنى والمسار؛ فالخط الأفقي يعني ثبات الموقع لا أفقية الأرض.","الذهاب والعودة يظهران خطًا صاعدًا ثم هابطًا، لا خطًا أفقيًا.","","الخط الأفقي قد يكون عند أي موقع، ويكون عند نقطة الأصل فقط إذا انطبق على محور الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.258Z"}'::jsonb),
('mcq', 6, 0, 'نقطة التقاطع (20 s, 60 m) تعني أن للسيارتين الموقع نفسه على طول الطريق في تلك اللحظة، ولأن لكل منهما مسارًا خاصًا فإنهما تتجاوران ولا تتصادمان، ثم يصبح خط A أعلى، أي أن A تتجاوز B.', '["","التقاطع يعني الموقع نفسه في اللحظة نفسها، ولا يعني بالضرورة التصادم؛ فكل سيارة في مسار مختلف.","عند التقاطع يكون موقعا السيارتين متساويين، و60 m هو موقعهما لا المسافة بينهما.","الخطان يستمران بعد 20 s، فالسيارتان تواصلان الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.259Z"}'::jsonb),
('mcq', 7, 3, 'المنحنى لا يصور المسار؛ بل يبين الموقع بدلالة الزمن. ولأن الاتجاه الموجب إلى أسفل المنحدر، فإن موقع المتزلج يزداد كلما نزل، فيكون الخط صاعدًا.', '["اتجاه ميل الخط يعتمد على تغير الموقع بالنسبة للاتجاه الموجب المختار، لا على نزول المتزلج.","الخط الأفقي يعني السكون، والمتزلج متحرك.","الخط الصاعد يعني تزايد الموقع في الاتجاه الموجب (إلى أسفل المنحدر)، لا الصعود.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.259Z"}'::jsonb),
('essay', 1, null::int, null, null, 'منحنى (الموقع – الزمن) رسم بياني يبين موقع الجسم (على المحور الرأسي) بدلالة الزمن (على المحور الأفقي)، فهو يبين كيف يتغير الموقع مع الزمن لا شكل الطريق. فعدّاء يجري على مضمار أفقي يكون الخط البياني لحركته مائلًا صاعدًا؛ لأن موقعه يزداد مع الزمن، مع أن مساره أفقي. ولو وقف العدّاء لأصبح الخط أفقيًا، ولو عاد لأصبح هابطًا، والمضمار في كل الحالات أفقي.', '["المنحنى يبين الموقع بدلالة الزمن","المحور الرأسي موقع لا ارتفاع","مثال العدّاء: خط مائل مع مسار أفقي"]'::jsonb, '[]'::jsonb, '[{"element":"المعنى الصحيح للمنحنى","marks":1},{"element":"التمييز بين المحور الرأسي والارتفاع","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["القول إن الخط المائل يعني طريقًا مائلًا.","الخلط بين المحور الرأسي والارتفاع."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.259Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) يتقاطع الخطان عند (20 s, 30 m)، أي أن السبّاحين يكونان على بُعد 30 m من طرف انطلاق A عند اللحظة 20 s نفسها. (b) لا يتصادمان؛ فنقطة التقاطع تعني أنهما في الموقع نفسه على طول المسبح، لكن كلًّا منهما في حارته الخاصة، فيمر أحدهما بجانب الآخر. (c) عند 30 s يكون A عند 45 m وB عند 20 m.', '["التقاطع (20 s, 30 m)","معناه: الموقع نفسه في اللحظة نفسها","لا تصادم لأن لكل منهما حارة","عند 30 s: A عند 45 m وB عند 20 m"]'::jsonb, '[]'::jsonb, '[{"element":"إحداثيا التقاطع ومعناهما","marks":1},{"element":"نفي التصادم وتعليله","marks":1.5},{"element":"الموقعان عند 30 s","marks":1.5}]'::jsonb, '[{"level":"4 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["القول إن السبّاحين يتصادمان.","تفسير التقاطع بأنه تساوي المسافة المقطوعة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.259Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح؛ فمنحنى (الموقع – الزمن) لا يصور شكل الطريق، بل يبين موقع الحافلة (مقيسًا على طول الطريق) بدلالة الزمن. والخط المستقيم الصاعد يعني أن موقعها يزداد بانتظام مع الزمن، أي أنها تقطع مسافات متساوية في أزمنة متساوية، مهما كانت منعطفات الطريق. ولو كان المنحنى متعرجًا لدل على تغير طريقة تزايد الموقع أو توقف الحافلة أو عودتها، لا على تعرج الطريق.', '["الحكم: القول غير صحيح","المنحنى يبين الموقع بدلالة الزمن لا شكل الطريق","معنى الخط المستقيم الصاعد: تزايد منتظم للموقع"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل","marks":1},{"element":"تفسير الخط المستقيم","marks":1}]'::jsonb, '[{"level":"3 درجات: إجابة كاملة","description":"يذكر جميع عناصر الإجابة بصورة صحيحة ودقيقة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يقع في خطأ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الموافقة على قول الطالب.","تفسير الخط الصاعد بأنه صعود الحافلة للجبل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.259Z"}'::jsonb)
