select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'السرعة المتجهة المتوسطة هي التغير في الموقع (الإزاحة) مقسومًا على الفترة الزمنية التي حدث خلالها هذا التغير: $\boldsymbol{\bar{v}} = \frac{\Delta \boldsymbol{d}}{\Delta t}$.', '["هذا تعريف التسارع المتوسط؛ فهو يقسم التغير في السرعة المتجهة لا التغير في الموقع.","","هذا وصف السرعة المتجهة اللحظية، لا المتوسطة التي تُحسب على فترة زمنية كاملة.","يهمل الموقع الابتدائي؛ فالتعريف يعتمد على التغير في الموقع $\\boldsymbol{d}_f - \\boldsymbol{d}_i$ لا على الموقع النهائي وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-18T12:34:59.260Z"}'::jsonb),
('mcq', 2, 3, 'السرعة المتجهة المتوسطة تساوي الإزاحة مقسومة على الفترة الزمنية: $\boldsymbol{\bar{v}} = \frac{\Delta \boldsymbol{d}}{\Delta t} = \frac{\boldsymbol{d}_f - \boldsymbol{d}_i}{t_f - t_i}$.', '["مقلوب العلاقة الصحيحة؛ هذا الناتج يعطي الزمن اللازم لكل متر لا السرعة المتجهة.","جمع الموقعين والزمنين بدل طرحهما؛ السرعة المتجهة المتوسطة تعتمد على التغير في الموقع وعلى الفترة الزمنية.","ضرب الإزاحة في الفترة الزمنية بدل القسمة عليها، ووحدة الناتج m·s لا m/s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-18T12:34:59.260Z"}'::jsonb),
('mcq', 3, 0, 'تُحسب السرعة المتجهة المتوسطة من الإزاحة، وهي كمية متجهة؛ لذا فهي متجهة لها مقدار واتجاه، وتحمل دائمًا إشارة إزاحة الجسم نفسها.', '["","هذا وصف السرعة المتوسطة (القياسية)؛ أما السرعة المتجهة المتوسطة فلها اتجاه وقد تكون سالبة.","اتجاهها هو اتجاه الإزاحة، وقد يكون مبتعدًا عن نقطة الأصل أو مقتربًا منها.","تعتمد السرعة المتجهة المتوسطة على الإزاحة لا على المسافة الكلية، وهي متجهة لا عددية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.260Z"}'::jsonb),
('mcq', 4, 2, 'بما أن $\boldsymbol{\bar{v}} = \frac{\boldsymbol{d}_f - \boldsymbol{d}_i}{t_f - t_i}$ فإنها تتحدد بالموقعين الابتدائي والنهائي (الإزاحة) وبالفترة الزمنية فقط.', '["المسافة الكلية تدخل في السرعة المتوسطة لا في السرعة المتجهة المتوسطة التي تعتمد على الإزاحة.","الكتلة لا تدخل في تعريف السرعة المتجهة المتوسطة؛ فهي تعتمد على التغير في الموقع والفترة الزمنية.","","التعريف يستخدم التغير في الموقع $\\boldsymbol{d}_f - \\boldsymbol{d}_i$؛ فالموقع الابتدائي ضروري، وكذلك الفترة الزمنية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.260Z"}'::jsonb),
('mcq', 5, 1, '$\Delta \boldsymbol{d} = 16.0 - 4.0 = 12.0\ \text{m}$ و$\Delta t = 6.0 - 2.0 = 4.0\ \text{s}$، إذن $\boldsymbol{\bar{v}} = \frac{12.0}{4.0} = 3.0\ \text{m/s}$.', '["قسم الموقع النهائي على الزمن النهائي ($16.0 \\div 6.0$) بدل قسمة الإزاحة على الفترة الزمنية.","","قسم الموقع النهائي على الفترة الزمنية ($16.0 \\div 4.0$) ناسيًا طرح الموقع الابتدائي.","قلب العلاقة فقسم الفترة الزمنية على الإزاحة ($4.0 \\div 12.0$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.260Z"}'::jsonb),
('mcq', 6, 0, 'الرمز $\boldsymbol{\bar{v}}$ يدل على السرعة المتجهة المتوسطة، والشرطة فوق الحرف تدل على أنها قيمة متوسطة خلال فترة زمنية، وتساوي الإزاحة مقسومة على الفترة الزمنية.', '["","السرعة المتجهة اللحظية يرمز لها بالرمز $\\boldsymbol{v}$ دون شرطة، وتخص لحظة واحدة لا فترة زمنية.","التغير في السرعة المتجهة يرمز له بالرمز $\\Delta \\boldsymbol{v}$، ولا يساوي $\\frac{\\Delta \\boldsymbol{d}}{\\Delta t}$.","التسارع المتوسط يرمز له بالرمز $\\boldsymbol{\\bar{a}}$، وهو معدل تغير السرعة المتجهة لا الموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.260Z"}'::jsonb),
('mcq', 7, 2, 'عاد العدّاء إلى موقعه الابتدائي، فإزاحته الكلية $\Delta \boldsymbol{d} = 0.0 - 0.0 = 0$، إذن $\boldsymbol{\bar{v}} = \frac{0}{50.0\ \text{s}} = 0$.', '["قسم المسافة الكلية 200.0 m على الزمن؛ وهذا لا يعطي السرعة المتجهة المتوسطة التي تعتمد على الإزاحة.","قسم مسافة الذهاب فقط 100.0 m على زمن الرحلة كلها.","","قسم إزاحة مرحلة العودة وحدها ($-100.0\\ \\text{m}$) على زمن الرحلة كلها، بدل الإزاحة الكلية للرحلة التي تساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.261Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السرعة المتجهة المتوسطة هي التغير في الموقع (الإزاحة) مقسومًا على الفترة الزمنية التي حدث خلالها هذا التغير. معادلتها: $\boldsymbol{\bar{v}} = \frac{\Delta \boldsymbol{d}}{\Delta t} = \frac{\boldsymbol{d}_f - \boldsymbol{d}_i}{t_f - t_i}$؛ حيث $\boldsymbol{\bar{v}}$ السرعة المتجهة المتوسطة، و$\Delta \boldsymbol{d}$ الإزاحة، و$\boldsymbol{d}_f$ الموقع النهائي، و$\boldsymbol{d}_i$ الموقع الابتدائي، و$\Delta t$ الفترة الزمنية، و$t_f$ الزمن النهائي، و$t_i$ الزمن الابتدائي. وحدتها m/s.', '["التعريف: الإزاحة مقسومة على الفترة الزمنية","المعادلة $\\boldsymbol{\\bar{v}} = \\frac{\\boldsymbol{d}_f - \\boldsymbol{d}_i}{t_f - t_i}$","دلالة الرموز","الوحدة m/s"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المعادلة","marks":1},{"element":"دلالة الرموز","marks":1},{"element":"الوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ومعادلة صحيحة مع دلالة جميع الرموز والوحدة"},{"level":"2–3 درجات","description":"تعريف أو معادلة صحيحة مع نقص في دلالة الرموز أو الوحدة"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال المسافة بدل الإزاحة في التعريف","كتابة المعادلة مقلوبة $\\frac{\\Delta t}{\\Delta \\boldsymbol{d}}$","كتابة الوحدة m/s² أو m"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.261Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لأن المخطط لا يعبر عما حدث خلال الفترة؛ فربما بقيت السرعة ثابتة أو زادت أو نقصت، أو توقف الجسم أو غيّر اتجاهه، وكل ما نستطيع تحديده هو الإزاحة الكلية مقسومة على الفترة الزمنية الكلية، وهذه قيمة متوسطة تمثل الفترة كلها لا لحظة معيّنة. ونصفها بأنها متجهة لأنها تُحسب من الإزاحة، وهي كمية متجهة، فيكون لها مقدار واتجاه هو اتجاه الإزاحة (وتظهر إشارتها في النظام الإحداثي).', '["المخطط يعطي الموقعين عند بداية الفترة ونهايتها فقط","لا نعرف ما حدث بينهما (ثبات/تغير السرعة، توقف، تغير اتجاه)","الناتج قيمة متوسطة للفترة كلها","متجهة لأنها تُحسب من الإزاحة فلها اتجاه"]'::jsonb, '[]'::jsonb, '[{"element":"المخطط يعطي موقعين فقط","marks":1},{"element":"عدم معرفة ما حدث خلال الفترة","marks":1},{"element":"معنى «متوسطة»","marks":1},{"element":"معنى «متجهة»","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يفسر الوصفين تفسيرًا صحيحًا كاملًا"},{"level":"2–3 درجات","description":"يفسر أحد الوصفين كاملًا أو كليهما بنقص"},{"level":"1 درجة","description":"يذكر عنصرًا صحيحًا واحدًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن بأن المخطط يحدد السرعة في كل لحظة","وصفها بالمتجهة لأنها «سرعة» دون ربطها بالإزاحة","الخلط بين السرعة المتجهة المتوسطة واللحظية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.261Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $\Delta \boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 40.0 - (-20.0) = 60.0\ \text{m}$. (ب) $\Delta t = 4.0 - 1.0 = 3.0\ \text{s}$، و$\boldsymbol{\bar{v}} = \frac{60.0}{3.0} = 20\ \text{m/s}$. (ج) الإشارة موجبة؛ أي أن السيارة تحركت في الاتجاه الموجب (نحو الشرق) بمعدل 20 m/s.', '["الإزاحة 60.0 m","الفترة الزمنية 3.0 s","السرعة المتجهة المتوسطة 20 m/s","الإشارة الموجبة تعني الحركة نحو الشرق"]'::jsonb, '["$\\Delta \\boldsymbol{d} = \\boldsymbol{d}_f - \\boldsymbol{d}_i = 40.0\\ \\text{m} - (-20.0\\ \\text{m}) = 60.0\\ \\text{m}$","$\\Delta t = t_f - t_i = 4.0\\ \\text{s} - 1.0\\ \\text{s} = 3.0\\ \\text{s}$","$\\boldsymbol{\\bar{v}} = \\frac{\\Delta \\boldsymbol{d}}{\\Delta t} = \\frac{60.0\\ \\text{m}}{3.0\\ \\text{s}} = 20\\ \\text{m/s}$","الإشارة موجبة: الحركة في الاتجاه الموجب (شرقًا)"]'::jsonb, '[{"element":"حساب الإزاحة","marks":1},{"element":"حساب الفترة الزمنية","marks":1},{"element":"حساب السرعة المتجهة المتوسطة بالوحدة","marks":1},{"element":"تفسير الإشارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة بالوحدات وتفسير صحيح للإشارة"},{"level":"2–3 درجات","description":"خطأ واحد في الإشارة أو الوحدة أو التفسير"},{"level":"1 درجة","description":"خطوة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح الموقعين دون مراعاة إشارة $-20.0\\ \\text{m}$ فيحصل على 20.0 m","القسمة على الزمن النهائي 4.0 s بدل الفترة الزمنية","إهمال تفسير الإشارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.261Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O01') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L4-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يُقال إن الجسم الأول يتحرك أسرع من الجسم الثاني إذا كان الأول:', null, null, '["يقطع إزاحة أكبر من الثاني خلال الفترة الزمنية نفسها","يقطع إزاحة أكبر من الثاني مهما كانت الفترة الزمنية","يستغرق فترة زمنية أطول ليقطع الإزاحة نفسها","يبدأ حركته من موقع أبعد عن نقطة الأصل"]'::jsonb, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 43 — السرعة المتجهة (مقارنة حركتي عدّاءين)'),
('mcq', 2, 'قطع عدّاءان الإزاحة نفسها 100.0 m في الاتجاه نفسه؛ فاستغرق الأول 12.5 s، واستغرق الثاني 14.0 s. أي العبارات الآتية صحيحة؟', null, null, '["الثاني أسرع؛ لأنه استمر في الحركة فترة زمنية أطول","لهما السرعة نفسها؛ لأن إزاحتيهما متساويتان","لا يمكن المقارنة بينهما دون معرفة موقعيهما الابتدائيين","الأول أسرع؛ لأنه قطع الإزاحة نفسها في فترة زمنية أقل"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 43 — السرعة المتجهة (مقارنة حركتي عدّاءين)'),
('mcq', 3, 'يمثل المنحنى الآتي حركة عدّاءين A وB انطلقا معًا من نقطة الأصل في الاتجاه نفسه. أي العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c2l4-o02-runners.svg","alt":"منحنى (الموقع – الزمن) لعدّاءين A وB. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 4 s كل 1 s، وتدريج الموقع من 0 إلى 10 m كل 2 m. الخط A (أزرق) مستقيم يبدأ من (0 s، 0 m) وينتهي عند (4 s، 8 m). الخط B (أحمر) مستقيم يبدأ من (0 s، 0 m) وينتهي عند (4 s، 4 m)."}]'::jsonb, '["العدّاء B أسرع؛ لأن ميل خطه البياني أصغر","لهما السرعة نفسها؛ لأنهما انطلقا معًا من نقطة الأصل","العدّاء A أسرع؛ لأن ميل خطه البياني أكبر","لهما السرعة نفسها؛ لأن كلا الخطين مستقيم"]'::jsonb, 'فهم', 'قراءة رسم بياني', 'سهل', 'الكتاب ص 43 — السرعة المتجهة (مقارنة حركتي عدّاءين)'),
('mcq', 4, 'يمثل المنحنى الآتي حركة درّاجين C وD في الاتجاه نفسه. اعتمادًا عليه، ما العلاقة بين سرعة C وسرعة D؟', null, '[{"src":"qimg/phys1/c2l4-o02-cyclists.svg","alt":"منحنى (الموقع – الزمن) لدرّاجين C وD. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 7 s كل 1 s، وتدريج الموقع من 0 إلى 14 m كل 2 m. الخط C (أزرق) مستقيم من (0 s، 0 m) إلى (3 s، 12 m). الخط D (أحمر) مستقيم من (0 s، 0 m) إلى (6 s، 12 m)."}]'::jsonb, '["سرعة C تساوي نصف سرعة D","سرعة C تساوي مثلي سرعة D","سرعة C تساوي سرعة D","سرعة C تساوي أربعة أمثال سرعة D"]'::jsonb, 'تطبيق', 'قراءة رسم بياني وحساب', 'متوسط', 'الكتاب ص 43 — السرعة المتجهة (مقارنة حركتي عدّاءين)'),
('mcq', 5, 'يبيّن المخطط التوضيحي الآتي حركة جسمين A وB، والتُقطت الصور على فترات زمنية متساوية. أي الجسمين أسرع، ولماذا؟', null, '[{"src":"qimg/phys1/c2l4-o02-dots.svg","alt":"مخطط توضيحي للحركة بنموذج الجسيم النقطي لجسمين A وB، والصور ملتقطة على فترات زمنية متساوية، والحركة نحو اليمين في اتجاه محور الموقع d. الصف الأول (الجسم A، نقاط زرقاء): ست نقاط متقاربة بين كل نقطتين متتاليتين مسافة صغيرة ثابتة. الصف الثاني (الجسم B، نقاط حمراء): ست نقاط متباعدة، والمسافة بين كل نقطتين متتاليتين ثابتة وتساوي مثلي المسافة في الصف الأول."}]'::jsonb, '["الجسم A؛ لأن صوره المتتالية أكثر تقاربًا","لهما السرعة نفسها؛ لأن عدد الصور متساوٍ","لهما السرعة نفسها؛ لأن الفترات الزمنية بين الصور متساوية","الجسم B؛ لأن المسافة بين صوره المتتالية أكبر"]'::jsonb, 'فهم', 'قراءة مخطط الحركة', 'متوسط', 'الكتاب ص 43 — مثال العدّاءين على مخطط توضيحي واحد'),
('mcq', 6, 'ماذا يعني أن السرعة المتجهة المتوسطة لدرّاج تساوي 2.0 m/s نحو الشرق؟', null, null, '["يحتاج الدرّاج إلى 2.0 s ليقطع مترًا واحدًا نحو الشرق","يتغير موقعه 2.0 m نحو الشرق في كل ثانية في المتوسط","يقع الدرّاج على بعد 2.0 m شرق نقطة الأصل","تزداد سرعة الدرّاج بمقدار 2.0 m/s في كل ثانية"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 44 — وحدة الميل m/s ومعناها'),
('mcq', 7, 'يبيّن الجدول الآتي إزاحتي سيارتين X وY تحركتا في الاتجاه نفسه والفترة الزمنية لكل منهما. أي العبارات الآتية صحيحة؟', '{"headers":["السيارة","الإزاحة (m)","الفترة الزمنية (s)"],"rows":[["X","150","10.0"],["Y","240","20.0"]]}'::jsonb, null, '["Y أسرع؛ لأن إزاحتها الكلية هي الأكبر","Y أسرع؛ لأنها تحركت فترة زمنية أطول","X أسرع؛ لأن إزاحتها في كل ثانية أكبر","لا يمكن المقارنة؛ لأن الفترتين الزمنيتين مختلفتان"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 43 — السرعة المتجهة (مقارنة حركتي عدّاءين)'),
('essay', 1, 'يمثل المنحنى الآتي حركة عدّاءين A وB انطلقا معًا من نقطة الأصل في الاتجاه نفسه. (أ) قارن بين إزاحتي العدّاءين خلال الثواني الثلاث الأولى. (ب) ما الزمن الذي يستغرقه كل منهما ليصل إلى الموقع 3 m؟ (ج) وضّح بالاعتماد على إجابتيك المقصود بأن العدّاء A أسرع من العدّاء B.', null, '[{"src":"qimg/phys1/c2l4-o02-essay.svg","alt":"منحنى (الموقع – الزمن) لعدّاءين A وB. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 3 s كل 0.5 s، وتدريج الموقع من 0 إلى 7 m كل 1 m. الخط A (أزرق) مستقيم من (0 s، 0 m) إلى (3 s، 6 m). الخط B (أحمر) مستقيم من (0 s، 0 m) إلى (3 s، 3 m)."}]'::jsonb, null, 'فهم', 'قراءة رسم بياني وتفسير', 'متوسط', 'الكتاب ص 43 — السرعة المتجهة (مقارنة حركتي عدّاءين)'),
('essay', 2, 'مشى أحمد في خط مستقيم نحو الشرق فقطع إزاحة 120.0 m خلال 80.0 s، وركض صالح نحو الشرق فقطع إزاحة 200.0 m خلال 160.0 s. (أ) احسب السرعة المتجهة المتوسطة لكل منهما. (ب) أيهما أسرع؟ (ج) فسّر لماذا لا تعني الإزاحة الأكبر بالضرورة أن صاحبها أسرع.', null, null, null, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 43 — السرعة المتجهة (مقارنة حركتي عدّاءين)'),
('essay', 3, 'قال طالب: «العدّاء الذي يقطع إزاحة أكبر هو دائمًا الأسرع». قوّم هذه العبارة، ثم أعد صياغتها صياغة صحيحة، ودعّم رأيك بمثال عددي.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 43 — السرعة المتجهة (مقارنة حركتي عدّاءين)')
