from (values
('mcq', 1, 0, 'الجسم الأسرع يتغير موقعه بمقدار أكبر (إزاحة أكبر) خلال الفترة الزمنية نفسها، أي أن $\frac{\Delta \boldsymbol{d}}{\Delta t}$ له أكبر.', '["","المقارنة بالإزاحة وحدها لا تكفي؛ فقد يقطع الأول إزاحة أكبر لأنه تحرك زمنًا أطول.","العكس هو الصحيح؛ الأسرع يستغرق فترة زمنية أقل لقطع الإزاحة نفسها.","الموقع الابتدائي لا يحدد السرعة؛ السرعة تعتمد على تغير الموقع خلال الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.262Z"}'::jsonb),
('mcq', 2, 3, 'للإزاحة نفسها يكون الأسرع هو من يستغرق فترة زمنية أقل: $\frac{100.0}{12.5} = 8.00\ \text{m/s}$ للأول، و$\frac{100.0}{14.0} \approx 7.14\ \text{m/s}$ للثاني.', '["استغراق زمن أطول للإزاحة نفسها يعني أن الجسم أبطأ لا أسرع.","تساوي الإزاحة لا يكفي؛ فالسرعة تعتمد أيضًا على الفترة الزمنية، وقد اختلفت هنا.","المقارنة ممكنة؛ فالإزاحة والفترة الزمنية معلومتان، والموقع الابتدائي لا يغيّر النتيجة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.262Z"}'::jsonb),
('mcq', 3, 2, 'خلال 4 s تغير موقع A بمقدار 8 m وموقع B بمقدار 4 m فقط؛ فخط A أكثر انحدارًا، وA يقطع إزاحة أكبر في الفترة الزمنية نفسها، فهو الأسرع.', '["الميل الأصغر يعني تغيرًا أقل في الموقع لكل ثانية، أي حركة أبطأ.","الانطلاق من النقطة نفسها في اللحظة نفسها لا يعني تساوي السرعة؛ فخطاهما مختلفان في الميل.","","استقامة الخط تعني أن السرعة ثابتة لكل عدّاء، لا أن السرعتين متساويتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.262Z"}'::jsonb),
('mcq', 4, 1, 'يقطع C الإزاحة 12 m في 3 s فسرعته $\frac{12}{3} = 4\ \text{m/s}$، ويقطعها D في 6 s فسرعته $\frac{12}{6} = 2\ \text{m/s}$؛ إذن سرعة C مثلا سرعة D.', '["قارن الزمنين بدل السرعتين؛ زمن C نصف زمن D للإزاحة نفسها، فسرعته ضعف سرعة D لا نصفها.","","كلاهما يصل إلى 12 m، لكن C يصل في نصف الزمن، فالسرعتان غير متساويتين.","ربّع النسبة بين الزمنين خطأً؛ النسبة بين السرعتين هي $\\frac{6}{3} = 2$ فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:59.262Z"}'::jsonb),
('mcq', 5, 3, 'في الفترة الزمنية نفسها بين صورتين متتاليتين يتغير موقع B بمقدار أكبر من A، أي أن إزاحة B أكبر خلال الفترة الزمنية نفسها، فهو الأسرع.', '["تقارب الصور يعني أن الجسم يتحرك مسافة أصغر في كل فترة زمنية، أي أنه أبطأ.","تساوي عدد الصور يعني تساوي الزمن الكلي فقط، والسرعة تعتمد على الإزاحة في هذا الزمن.","تساوي الفترات الزمنية شرط للمقارنة لا نتيجة لها؛ والإزاحة في كل فترة مختلفة بين الجسمين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.262Z"}'::jsonb),
('mcq', 6, 1, 'وحدة السرعة m/s تخبرنا كم مترًا يتغير موقع الجسم في ثانية واحدة؛ لذا يتغير موقع الدرّاج 2.0 m شرقًا في كل ثانية في المتوسط.', '["هذا قلب للعلاقة؛ 2.0 m/s تعني أمتارًا في كل ثانية لا ثواني لكل متر.","","هذا وصف لموقع لا لسرعة؛ السرعة تصف معدل تغير الموقع.","هذا وصف لتسارع لا لسرعة متجهة متوسطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.262Z"}'::jsonb),
('mcq', 7, 2, 'سرعة X $= \frac{150}{10.0} = 15\ \text{m/s}$، وسرعة Y $= \frac{240}{20.0} = 12\ \text{m/s}$؛ فـ X تقطع إزاحة أكبر في كل ثانية، فهي أسرع.', '["قارن الإزاحتين الكليتين دون مراعاة أن Y تحركت فترة زمنية مضاعفة.","طول فترة الحركة لا يعني أن الجسم أسرع؛ المهم الإزاحة في وحدة الزمن.","","يمكن المقارنة بحساب الإزاحة في كل ثانية ($\\frac{\\Delta \\boldsymbol{d}}{\\Delta t}$) لكل سيارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.263Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) خلال 3 s إزاحة A تساوي 6 m وإزاحة B تساوي 3 m، فإزاحة A أكبر (مثلا إزاحة B). (ب) يصل A إلى 3 m عند 1.5 s، ويصل B إليه عند 3 s. (ج) A أسرع يعني أنه يقطع إزاحة أكبر خلال الفترة الزمنية نفسها، أو يستغرق فترة زمنية أقل لقطع الإزاحة نفسها؛ ولذلك يكون ميل خطه البياني أكبر.', '["إزاحة A = 6 m وإزاحة B = 3 m خلال 3 s","زمن A = 1.5 s وزمن B = 3 s للوصول إلى 3 m","الأسرع: إزاحة أكبر في الزمن نفسه","الأسرع: زمن أقل للإزاحة نفسها/ميل أكبر"]'::jsonb, '["من الرسم: عند t = 3 s، موقع A = 6 m وموقع B = 3 m","من الرسم: A عند 3 m بعد 1.5 s، وB عند 3 m بعد 3 s","الربط بمفهوم السرعة المتجهة $\\frac{\\Delta \\boldsymbol{d}}{\\Delta t}$"]'::jsonb, '[{"element":"مقارنة الإزاحتين","marks":1},{"element":"الزمنان للوصول إلى 3 m","marks":1},{"element":"المقصود بالأسرع (الزمن نفسه)","marks":1},{"element":"المقصود بالأسرع (الإزاحة نفسها)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"قراءات صحيحة وتوضيح يجمع الحالتين"},{"level":"2–3 درجات","description":"قراءات صحيحة مع توضيح ناقص"},{"level":"1 درجة","description":"قراءة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قراءة الموقع من المحور الأفقي بدل الرأسي","القول إن B أسرع لأنه يحتاج زمنًا أطول","الاكتفاء بمقارنة الإزاحتين دون ربطهما بالزمن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.263Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) أحمد: $\boldsymbol{\bar{v}} = \frac{120.0}{80.0} = 1.50\ \text{m/s}$ شرقًا. صالح: $\boldsymbol{\bar{v}} = \frac{200.0}{160.0} = 1.25\ \text{m/s}$ شرقًا. (ب) أحمد أسرع. (ج) لأن السرعة هي الإزاحة في وحدة الزمن؛ وصالح قطع إزاحة أكبر لأنه تحرك فترة زمنية أطول (مثلي فترة أحمد)، لكن إزاحته في كل ثانية أقل.', '["سرعة أحمد 1.50 m/s","سرعة صالح 1.25 m/s","أحمد أسرع","التفسير: السرعة إزاحة لكل وحدة زمن، وصالح تحرك زمنًا أطول"]'::jsonb, '["أحمد: $\\boldsymbol{\\bar{v}} = \\frac{120.0\\ \\text{m}}{80.0\\ \\text{s}} = 1.50\\ \\text{m/s}$","صالح: $\\boldsymbol{\\bar{v}} = \\frac{200.0\\ \\text{m}}{160.0\\ \\text{s}} = 1.25\\ \\text{m/s}$","$1.50 > 1.25$ إذن أحمد أسرع"]'::jsonb, '[{"element":"سرعة أحمد","marks":1},{"element":"سرعة صالح","marks":1},{"element":"تحديد الأسرع","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وحكم صحيح وتفسير سليم"},{"level":"2–3 درجات","description":"حسابان صحيحان مع تفسير ناقص، أو خطأ حسابي واحد"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن صالح أسرع لأن إزاحته أكبر","قسمة الزمن على الإزاحة","إهمال ذكر الاتجاه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.263Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة على إطلاقها؛ لأنها تهمل الفترة الزمنية. فالعدّاء الأسرع هو الذي يقطع إزاحة أكبر خلال الفترة الزمنية نفسها، أو يقطع الإزاحة نفسها في فترة زمنية أقل. مثال: عدّاء قطع 100 m في 20 s (سرعته 5.0 m/s)، وآخر قطع 60 m في 10 s (سرعته 6.0 m/s)؛ فالثاني أسرع رغم أن إزاحته أصغر. الصياغة الصحيحة: «العدّاء الذي يقطع إزاحة أكبر خلال الفترة الزمنية نفسها هو الأسرع».', '["الحكم: العبارة غير صحيحة على إطلاقها","السبب: تهمل الفترة الزمنية","صياغة صحيحة تتضمن «خلال الفترة الزمنية نفسها»","مثال عددي صحيح يدعم الحكم"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل","marks":1},{"element":"الصياغة الصحيحة","marks":1},{"element":"المثال العددي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم وتعليل وصياغة ومثال صحيح"},{"level":"2–3 درجات","description":"حكم وتعليل صحيحان مع نقص في الصياغة أو المثال"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","ذكر مثال حساباته خاطئة","إعادة الصياغة بالاعتماد على المسافة الكلية بدل الإزاحة في الزمن نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-18T12:34:59.263Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
