insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L4-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ماذا يمثل ميل الخط البياني في منحنى (الموقع – الزمن) لجسم متحرك؟', null, null, '["التسارع المتوسط للجسم","الإزاحة الكلية للجسم","السرعة المتجهة المتوسطة","الموقع الابتدائي للجسم"]'::jsonb, 'تذكر', 'تذكر مبدأ', 'سهل', 'الكتاب ص 44 — ميل منحنى (الموقع – الزمن) يمثل السرعة المتجهة المتوسطة'),
('mcq', 2, 'من الأخطاء الشائعة القول إن ميل الخط البياني لمنحنى (الموقع – الزمن) يمثل سرعة الجسم فحسب. ما سبب ذلك؟', null, null, '["لأن للميل إشارة تدل على اتجاه الحركة إضافة إلى مقدارها","لأن الميل يمثل المسافة الكلية التي قطعها الجسم لا سرعته","لأن الميل لا تتغير إشارته مهما تغير اتجاه الحركة","لأن الميل يمثل الزمن اللازم لقطع متر واحد"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 45 — الميل يدل على السرعة المتجهة المتوسطة لا على مقدار السرعة فحسب'),
('mcq', 3, 'ما وحدة ميل الخط البياني لمنحنى (الموقع – الزمن) إذا قيس الموقع بالمتر والزمن بالثانية؟', null, null, '["m/s²","s/m","m·s","m/s"]'::jsonb, 'فهم', 'وحدات', 'سهل', 'الكتاب ص 44 — وحدات الميل m/s'),
('mcq', 4, 'في منحنى (الموقع – الزمن) الآتي رُسم مثلث على الخط البياني. ماذا يمثل ناتج قسمة الضلع الرأسي $\Delta \boldsymbol{d}$ على الضلع الأفقي $\Delta t$؟', null, '[{"src":"qimg/phys1/c2l4-o03-triangle.svg","alt":"منحنى (الموقع – الزمن) لجسم. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من 0 إلى 14 m كل 2 m. خط مستقيم أزرق يبدأ من (0 s، 2 m) ويصعد إلى (6 s، 14 m). عُلّمت عليه نقطتان: (1 s، 4 m) و(5 s، 12 m)، ورُسم بينهما مثلث بخطوط متقطعة: ضلع أفقي من (1 s، 4 m) إلى (5 s، 4 m) كُتب عليه Δt، وضلع رأسي من (5 s، 4 m) إلى (5 s، 12 m) كُتب عليه Δd."}]'::jsonb, '["الإزاحة التي قطعها الجسم خلال الفترة $\\Delta t$","السرعة المتجهة المتوسطة للجسم خلال الفترة $\\Delta t$","التسارع المتوسط للجسم خلال الفترة $\\Delta t$","الموقع الابتدائي للجسم عند بداية الفترة $\\Delta t$"]'::jsonb, 'فهم', 'قراءة رسم بياني', 'متوسط', 'الكتاب ص 44 — ميل منحنى (الموقع – الزمن) يمثل السرعة المتجهة المتوسطة'),
('mcq', 5, 'ماذا يحدث لميل الخط البياني في منحنى (الموقع – الزمن) إذا ازدادت إزاحة الجسم خلال الفترة الزمنية نفسها؟', null, null, '["يقل الميل، وتزداد السرعة المتجهة المتوسطة","لا يتغير الميل؛ لأن الفترة الزمنية ثابتة","يزداد الميل، وتقل السرعة المتجهة المتوسطة","يزداد الميل، وتزداد السرعة المتجهة المتوسطة"]'::jsonb, 'فهم', 'علاقة', 'سهل', 'الكتاب ص 44 — يزداد الميل عندما تزداد Δd ويقل عندما تزداد Δt'),
('mcq', 6, 'ماذا يمثل ميل الخط البياني في منحنى (الموقع – الزمن) الآتي، وما قيمته؟', null, '[{"src":"qimg/phys1/c2l4-o03-negline.svg","alt":"منحنى (الموقع – الزمن) لجسم. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 18 m كل 3 m. خط مستقيم أزرق هابط يبدأ من (0 s، 15 m) وينتهي عند (5 s، 0 m)."}]'::jsonb, '["السرعة المتجهة المتوسطة، وقيمتها $-3.0\\ \\text{m/s}$","السرعة المتجهة المتوسطة، وتساوي 3.0 m/s","الإزاحة الكلية للجسم، وتساوي $-15\\ \\text{m}$","التسارع المتوسط للجسم، ويساوي $-3.0\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'قراءة رسم بياني وحساب', 'متوسط', 'الكتاب ص 45 — الميل يدل على السرعة المتجهة المتوسطة لا على مقدار السرعة فحسب'),
('mcq', 7, 'منحنى (الموقع – الزمن) لجسم ليس خطًا مستقيمًا؛ لأن سرعته تغيّرت في أثناء الحركة. رُسم خط مستقيم يصل بين نقطتي المنحنى عند اللحظتين $t_i = 2\ \text{s}$ و$t_f = 6\ \text{s}$. ماذا يمثل ميل هذا الخط الواصل؟', null, null, '["السرعة المتجهة اللحظية للجسم عند اللحظة 6 s","السرعة المتجهة المتوسطة بين اللحظتين 2 s و6 s","التسارع المتوسط للجسم بين اللحظتين 2 s و6 s","المسافة الكلية التي قطعها الجسم بين اللحظتين"]'::jsonb, 'تحليل', 'تحليل تمثيل', 'صعب', 'الكتاب ص 47 — السرعة المتجهة المتوسطة تُحسب من الإزاحة الكلية والفترة الزمنية'),
('essay', 1, 'وضّح ما يمثله ميل الخط البياني في منحنى (الموقع – الزمن)، مبيّنًا: (أ) العلاقة الرياضية التي يُحسب بها. (ب) وحدته ومعناها. (ج) لماذا لا يصح القول إنه يمثل مقدار السرعة فقط.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 45 — الميل يدل على السرعة المتجهة المتوسطة لا على مقدار السرعة فحسب'),
('essay', 2, 'يمثل المنحنى الآتي حركة جسم في خط مستقيم. (أ) احسب ميل الخط البياني مستخدمًا نقطتين عليه. (ب) ماذا يمثل هذا الميل فيزيائيًا؟ (ج) فسّر معنى وحدة الميل في هذه الحركة. (د) إذا استمر الجسم في الحركة بالنمط نفسه، فاستخدم الميل لتتوقع موقعه عند الزمن 8 s.', null, '[{"src":"qimg/phys1/c2l4-o03-essay.svg","alt":"منحنى (الموقع – الزمن) لجسم. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من 0 إلى 14 m كل 2 m. خط مستقيم أزرق يبدأ من (0 s، 2 m) وينتهي عند (6 s، 14 m)، ويمر بالنقاط (1 s، 4 m) و(3 s، 8 m) و(5 s، 12 m)."}]'::jsonb, null, 'تطبيق', 'حساب وتفسير', 'صعب', 'الكتاب ص 44 — ميل منحنى (الموقع – الزمن) يمثل السرعة المتجهة المتوسطة'),
('essay', 3, 'يمثل المنحنى الآتي حركة جسمين E وF. (أ) احسب ميل كل خط. (ب) ماذا تستنتج عن السرعة المتجهة المتوسطة للجسمين؟ (ج) بماذا تختلف حركتاهما؟ (د) فسّر لماذا لا يتأثر ما يمثله الميل بموقع الخط على الرسم.', null, '[{"src":"qimg/phys1/c2l4-o03-parallel.svg","alt":"منحنى (الموقع – الزمن) لجسمين E وF. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط E (أزرق) مستقيم من (0 s، 2 m) إلى (5 s، 12 m). الخط F (أحمر) مستقيم من (0 s، 8 m) إلى (5 s، 18 m). الخطان متوازيان."}]'::jsonb, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 44 — ميل منحنى (الموقع – الزمن) يمثل السرعة المتجهة المتوسطة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
