('mcq', 2, 'في منحنى (الموقع – الزمن) الآتي، احسب السرعة المتجهة المتوسطة في الفترة الزمنية بين اللحظتين 1.0 s و3.0 s.', null, '[{"src":"qimg/phys1/c2l4-o04-neg.svg","alt":"منحنى (الموقع – الزمن) لجسم. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من −4 إلى 12 m كل 2 m، ومحور الزمن عند الموقع 0. خط مستقيم أخضر هابط يبدأ من (0 s، 12 m) ويمر بالنقاط (1 s، 9 m) و(3 s، 3 m) و(4 s، 0 m) وينتهي عند (5 s، −3 m)."}]'::jsonb, '["$3.0\\ \\text{m/s}$","$-3.0\\ \\text{m/s}$","$-6.0\\ \\text{m/s}$","$1.0\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'متوسط', 'الكتاب ص 46 — مثال 3 ومسائل تدريبية (حساب السرعة المتجهة المتوسطة من منحنى الموقع – الزمن)'),
('mcq', 3, 'يمثل المنحنى الآتي حركة درّاجة هوائية في خط مستقيم، والموقع فيه بالكيلومتر والزمن بالدقيقة. ما السرعة المتجهة المتوسطة للدرّاجة بوحدة m/s؟', null, '[{"src":"qimg/phys1/c2l4-o04-bike.svg","alt":"منحنى (الموقع – الزمن) لدرّاجة هوائية. المحور الأفقي: الزمن t بالدقيقة (min) من 0 إلى 40 كل 5 min، والمحور الرأسي: الموقع d بالكيلومتر (km) من 0 إلى 24 كل 4 km. خط مستقيم أخضر يبدأ من (0 min، 0 km) وينتهي عند (40 min، 24 km)."}]'::jsonb, '["$10\\ \\text{m/s}$","$0.60\\ \\text{m/s}$","$36\\ \\text{m/s}$","$600\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدات', 'صعب', 'الكتاب ص 46 — مسألة تدريبية 27 (منحنى درّاجة بالكيلومتر والدقيقة)'),
('mcq', 4, 'يتكون المنحنى الآتي لحركة عربة من ثلاثة أجزاء مستقيمة. ما سرعتها المتجهة المتوسطة خلال الحركة كلها من 0 s إلى 6 s؟', null, '[{"src":"qimg/phys1/c2l4-o04-piecewise.svg","alt":"منحنى (الموقع – الزمن) لجسم يتكون من ثلاثة أجزاء مستقيمة. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من 0 إلى 10 m كل 1 m. الجزء الأول من (0 s، 0 m) إلى (2 s، 6 m)، والجزء الثاني أفقي من (2 s، 6 m) إلى (5 s، 6 m)، والجزء الثالث من (5 s، 6 m) إلى (6 s، 9 m)."}]'::jsonb, '["$3.0\\ \\text{m/s}$","$2.0\\ \\text{m/s}$","$1.5\\ \\text{m/s}$","$0.67\\ \\text{m/s}$"]'::jsonb, 'تحليل', 'حساب من رسم بياني', 'صعب', 'الكتاب ص 46 — مثال 3 ومسائل تدريبية (حساب السرعة المتجهة المتوسطة من منحنى الموقع – الزمن)'),
('mcq', 5, 'مُثّلت البيانات في الجدول الآتي لحركة جسم بمنحنى (الموقع – الزمن) فكان خطًا مستقيمًا. ما السرعة المتجهة المتوسطة للجسم؟', '{"headers":["الزمن t (s)","الموقع d (m)"],"rows":[["0.0","5.0"],["2.0","9.0"],["4.0","13.0"],["6.0","17.0"]]}'::jsonb, null, '["$2.8\\ \\text{m/s}$","$2.0\\ \\text{m/s}$","$0.50\\ \\text{m/s}$","$12\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'حساب من بيانات', 'متوسط', 'الكتاب ص 46 — مثال 3 ومسائل تدريبية (حساب السرعة المتجهة المتوسطة من منحنى الموقع – الزمن)'),
('mcq', 6, 'لحساب السرعة المتجهة المتوسطة لجسم من منحنى (الموقع – الزمن) المستقيم، نختار نقطتين على الخط البياني ثم نحسب:', null, null, '["$\\frac{t_2 - t_1}{\\boldsymbol{d}_2 - \\boldsymbol{d}_1}$","$\\frac{\\boldsymbol{d}_2 + \\boldsymbol{d}_1}{t_2 + t_1}$","$(\\boldsymbol{d}_2 - \\boldsymbol{d}_1)(t_2 - t_1)$","$\\frac{\\boldsymbol{d}_2 - \\boldsymbol{d}_1}{t_2 - t_1}$"]'::jsonb, 'فهم', 'إجراء', 'سهل', 'الكتاب ص 46 — مثال 3 ومسائل تدريبية (حساب السرعة المتجهة المتوسطة من منحنى الموقع – الزمن)'),
('mcq', 7, 'يمثل المنحنى الآتي حركة قارب في خط مستقيم، والاتجاه الموجب هو الشمال. ما السرعة المتجهة المتوسطة للقارب؟', null, '[{"src":"qimg/phys1/c2l4-o04-boat.svg","alt":"منحنى (الموقع – الزمن) لقارب. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من 0 إلى 30 m كل 5 m. خط مستقيم أخضر هابط يبدأ من (0 s، 30 m) وينتهي عند (6 s، 0 m)."}]'::jsonb, '["5.0 m/s نحو الجنوب","5.0 m/s نحو الشمال","0.20 m/s نحو الجنوب","30 m/s نحو الجنوب"]'::jsonb, 'تطبيق', 'حساب وتفسير الاتجاه', 'متوسط', 'الكتاب ص 46 — مسألة تدريبية 25 (حركة سفينة والاتجاه الموجب)'),
('essay', 1, 'استعن بمنحنى (الموقع – الزمن) الآتي لإيجاد السرعة المتجهة المتوسطة لعدّاء بين اللحظتين 2.0 s و8.0 s، موضحًا خطوات الحل.', null, '[{"src":"qimg/phys1/c2l4-o04-essay1.svg","alt":"منحنى (الموقع – الزمن) لجسم. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 10 s كل 1 s، وتدريج الموقع من 0 إلى 24 m كل 2 m. خط مستقيم أخضر يبدأ من (0 s، 4 m) وينتهي عند (10 s، 24 m)، ويمر بالنقطتين (2 s، 8 m) و(8 s، 20 m)."}]'::jsonb, null, 'تطبيق', 'حساب من رسم بياني', 'سهل', 'الكتاب ص 46 — مثال 3 ومسائل تدريبية (حساب السرعة المتجهة المتوسطة من منحنى الموقع – الزمن)'),
('essay', 2, 'يمثل المنحنى الآتي حركة جسم في خط مستقيم خلال 10 s. (أ) احسب السرعة المتجهة المتوسطة للجسم في كل جزء من الأجزاء الثلاثة. (ب) احسب السرعة المتجهة المتوسطة للجسم خلال الفترة كلها. (ج) لماذا لا تساوي إجابة (ب) المتوسط الحسابي لإجابات (أ)؟', null, '[{"src":"qimg/phys1/c2l4-o04-essay2.svg","alt":"منحنى (الموقع – الزمن) لجسم يتكون من ثلاثة أجزاء مستقيمة. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 10 s كل 1 s، وتدريج الموقع من −6 إلى 10 m كل 2 m، ومحور الزمن عند الموقع 0. الجزء الأول من (0 s، 0 m) إلى (4 s، 8 m)، والجزء الثاني أفقي من (4 s، 8 m) إلى (6 s، 8 m)، والجزء الثالث هابط من (6 s، 8 m) إلى (10 s، −4 m)."}]'::jsonb, null, 'تحليل', 'حساب من رسم بياني', 'صعب', 'الكتاب ص 46 — مثال 3 ومسائل تدريبية (حساب السرعة المتجهة المتوسطة من منحنى الموقع – الزمن)'),
('essay', 3, 'يمثل المنحنى الآتي حركة جسم في خط مستقيم. حسب طالب السرعة المتجهة المتوسطة للجسم خلال 5 s هكذا: $\boldsymbol{\bar{v}} = \frac{16\ \text{m}}{5\ \text{s}} = 3.2\ \text{m/s}$. (أ) حدّد الخطأ الذي وقع فيه الطالب. (ب) احسب القيمة الصحيحة.', null, '[{"src":"qimg/phys1/c2l4-o04-essay3.svg","alt":"منحنى (الموقع – الزمن) لجسم. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 18 m كل 2 m. خط مستقيم أخضر يبدأ من (0 s، 6 m) وينتهي عند (5 s، 16 m)."}]'::jsonb, null, 'تحليل', 'تحليل خطأ', 'متوسط', 'الكتاب ص 46 — مثال 3 ومسائل تدريبية (حساب السرعة المتجهة المتوسطة من منحنى الموقع – الزمن)')
