('mcq', 2, 1, 'من الرسم: $\boldsymbol{d}_i = 9\ \text{m}$ عند 1.0 s و$\boldsymbol{d}_f = 3\ \text{m}$ عند 3.0 s، إذن $\boldsymbol{\bar{v}} = \frac{3 - 9}{3.0 - 1.0} = \frac{-6}{2.0} = -3.0\ \text{m/s}$.', '["أهمل الإشارة؛ الموقع تناقص من 9 m إلى 3 m فالإزاحة سالبة.","","استعمل الإزاحة $-6\\ \\text{m}$ دون قسمتها على الفترة الزمنية 2.0 s.","قسم الموقع عند 3.0 s على الزمن ($3 \\div 3$) بدل قسمة الإزاحة على الفترة الزمنية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.265Z"}'::jsonb),
('mcq', 3, 0, '$\Delta \boldsymbol{d} = 24\ \text{km} = 24000\ \text{m}$، و$\Delta t = 40\ \text{min} = 2400\ \text{s}$، إذن $\boldsymbol{\bar{v}} = \frac{24000}{2400} = 10\ \text{m/s}$.', '["","قسم 24 km على 40 min دون تحويل الوحدتين، فالناتج 0.60 km/min لا m/s.","حسب السرعة بوحدة km/h ($24 \\div \\frac{40}{60} = 36$) ثم كتب الوحدة m/s.","حوّل الكيلومترات إلى أمتار ونسي تحويل الدقائق إلى ثوانٍ ($24000 \\div 40$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-18T12:34:59.265Z"}'::jsonb),
('mcq', 4, 2, 'السرعة المتجهة المتوسطة للفترة كلها = الإزاحة الكلية ÷ الفترة الزمنية الكلية: $\boldsymbol{\bar{v}} = \frac{9 - 0}{6 - 0} = 1.5\ \text{m/s}$.', '["حسب ميل الجزء الأول (أو الأخير) فقط، لا السرعة المتجهة المتوسطة للفترة كلها.","حسب المتوسط الحسابي لميول الأجزاء الثلاثة ($\\frac{3 + 0 + 3}{3}$)، والأجزاء ليست متساوية في المدة.","","قلب العلاقة فقسم الفترة الزمنية على الإزاحة ($6 \\div 9$)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.266Z"}'::jsonb),
('mcq', 5, 1, 'باستعمال أول نقطة وآخرها: $\boldsymbol{\bar{v}} = \frac{17.0 - 5.0}{6.0 - 0.0} = \frac{12.0}{6.0} = 2.0\ \text{m/s}$، ويؤكد ذلك أن الموقع يزداد 4.0 m كل 2.0 s.', '["قسم الموقع الأخير على الزمن الأخير ($17.0 \\div 6.0$) متجاهلًا الموقع الابتدائي 5.0 m.","","قلب العلاقة فقسم الفترة الزمنية على الإزاحة ($6.0 \\div 12.0$).","استعمل الإزاحة 12.0 m وحدها دون قسمتها على الفترة الزمنية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.266Z"}'::jsonb),
('mcq', 6, 3, 'السرعة المتجهة المتوسطة هي ميل الخط: التغير في الموقع بين النقطتين مقسومًا على الفترة الزمنية بينهما $\boldsymbol{\bar{v}} = \frac{\boldsymbol{d}_2 - \boldsymbol{d}_1}{t_2 - t_1}$.', '["هذا مقلوب الميل، ويعطي الزمن لكل متر لا السرعة المتجهة.","يجمع الموقعين والزمنين بدل حساب التغير فيهما.","يضرب الإزاحة في الفترة الزمنية بدل القسمة عليها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.266Z"}'::jsonb),
('mcq', 7, 0, '$\boldsymbol{\bar{v}} = \frac{0 - 30}{6 - 0} = -5.0\ \text{m/s}$؛ والإشارة السالبة تعني الاتجاه السالب، أي نحو الجنوب، بمقدار 5.0 m/s.', '["","أهمل الإشارة السالبة للميل؛ الموقع يتناقص فالقارب يتحرك في الاتجاه السالب (الجنوب).","قلب العلاقة فقسم الفترة الزمنية على الإزاحة ($6 \\div 30$).","استعمل الإزاحة 30 m وحدها دون قسمتها على الفترة الزمنية 6 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-18T12:34:59.266Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من الرسم: عند 2.0 s يكون الموقع 8 m، وعند 8.0 s يكون 20 m. $\Delta \boldsymbol{d} = 20 - 8 = 12\ \text{m}$، و$\Delta t = 8.0 - 2.0 = 6.0\ \text{s}$، إذن $\boldsymbol{\bar{v}} = \frac{12}{6.0} = 2.0\ \text{m/s}$ في الاتجاه الموجب.', '["قراءة الموقعين 8 m و20 m","الإزاحة 12 m والفترة 6.0 s","السرعة المتجهة المتوسطة 2.0 m/s","الاتجاه موجب"]'::jsonb, '["من الرسم: $\\boldsymbol{d}_1 = 8\\ \\text{m}$ عند $t_1 = 2.0\\ \\text{s}$، و$\\boldsymbol{d}_2 = 20\\ \\text{m}$ عند $t_2 = 8.0\\ \\text{s}$","$\\Delta \\boldsymbol{d} = 20\\ \\text{m} - 8\\ \\text{m} = 12\\ \\text{m}$","$\\Delta t = 8.0\\ \\text{s} - 2.0\\ \\text{s} = 6.0\\ \\text{s}$","$\\boldsymbol{\\bar{v}} = \\frac{12\\ \\text{m}}{6.0\\ \\text{s}} = 2.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"قراءة الموقعين من الرسم","marks":1},{"element":"حساب الإزاحة والفترة الزمنية","marks":1},{"element":"الناتج بالوحدة","marks":1},{"element":"تحديد الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"قراءة صحيحة وحساب صحيح بالوحدة والاتجاه"},{"level":"2–3 درجات","description":"خطأ واحد في القراءة أو الوحدة أو الاتجاه"},{"level":"1 درجة","description":"قراءة صحيحة دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الموقع 20 m على الزمن 8.0 s مباشرة (2.5 m/s)","قراءة الموقع عند 0 s بدل 2.0 s","إهمال الوحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.266Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الجزء الأول (0–4 s): $\frac{8 - 0}{4} = 2.0\ \text{m/s}$. الجزء الثاني (4–6 s): $\frac{8 - 8}{2} = 0$. الجزء الثالث (6–10 s): $\frac{-4 - 8}{4} = -3.0\ \text{m/s}$. (ب) $\boldsymbol{\bar{v}} = \frac{-4 - 0}{10 - 0} = -0.40\ \text{m/s}$. (ج) لأن السرعة المتجهة المتوسطة = الإزاحة الكلية ÷ الفترة الزمنية الكلية، والأجزاء مختلفة في مددها الزمنية، فلا يصح أخذ متوسط حسابي بسيط لسرعاتها (الذي يساوي $\frac{2.0 + 0 - 3.0}{3} \approx -0.33\ \text{m/s}$).', '["الجزء الأول 2.0 m/s","الجزء الثاني 0","الجزء الثالث $-3.0\\ \\text{m/s}$","الفترة كلها $-0.40\\ \\text{m/s}$","التعليل: الإزاحة الكلية ÷ الزمن الكلي، والمدد مختلفة"]'::jsonb, '["$\\boldsymbol{\\bar{v}}_1 = \\frac{8\\ \\text{m} - 0}{4\\ \\text{s}} = 2.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{v}}_2 = \\frac{8\\ \\text{m} - 8\\ \\text{m}}{2\\ \\text{s}} = 0$","$\\boldsymbol{\\bar{v}}_3 = \\frac{-4\\ \\text{m} - 8\\ \\text{m}}{4\\ \\text{s}} = -3.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{v}} = \\frac{-4\\ \\text{m} - 0}{10\\ \\text{s}} = -0.40\\ \\text{m/s}$"]'::jsonb, '[{"element":"سرعات الأجزاء الثلاثة","marks":2},{"element":"سرعة الفترة كلها","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة بإشاراتها وتعليل سليم"},{"level":"2–3 درجات","description":"خطأ في إشارة أو جزء واحد، أو تعليل ناقص"},{"level":"1 درجة","description":"حساب جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال إشارة الجزء الثالث","حساب المتوسط الحسابي للسرعات بدل الإزاحة الكلية على الزمن الكلي","استعمال المسافة الكلية 20 m بدل الإزاحة $-4\\ \\text{m}$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:59.267Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) قسم الطالب الموقع النهائي 16 m على الزمن، متجاهلًا أن الجسم لم يبدأ من نقطة الأصل بل من الموقع 6 m؛ والصحيح قسمة التغير في الموقع (الإزاحة) على الفترة الزمنية. (ب) $\boldsymbol{\bar{v}} = \frac{16 - 6}{5 - 0} = \frac{10}{5} = 2.0\ \text{m/s}$.', '["الخطأ: استعمل الموقع النهائي بدل الإزاحة","الموقع الابتدائي 6 m","الإزاحة 10 m","السرعة المتجهة المتوسطة 2.0 m/s"]'::jsonb, '["من الرسم: $\\boldsymbol{d}_i = 6\\ \\text{m}$ و$\\boldsymbol{d}_f = 16\\ \\text{m}$ و$\\Delta t = 5\\ \\text{s}$","$\\Delta \\boldsymbol{d} = 16\\ \\text{m} - 6\\ \\text{m} = 10\\ \\text{m}$","$\\boldsymbol{\\bar{v}} = \\frac{10\\ \\text{m}}{5\\ \\text{s}} = 2.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"تحديد الخطأ","marks":2},{"element":"الحساب الصحيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تحديد دقيق للخطأ وحساب صحيح"},{"level":"2–3 درجات","description":"تحديد الخطأ دون حساب صحيح أو العكس"},{"level":"1 درجة","description":"إشارة عامة إلى الخطأ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على حل الطالب","قراءة الموقع الابتدائي خطأ","قلب النسبة عند التصحيح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:59.267Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O04') and x.type = v.type and x.number = v.number
