insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L4-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل المنحنى الآتي حركة جسم على خط مستقيم في أربعة أجزاء. في أي جزء كان الجسم يتحرك في الاتجاه السالب؟', null, '[{"src":"qimg/phys1/c2l4-o05-segs1.svg","alt":"منحنى (الموقع – الزمن) لجسم مكوّن من أربعة أجزاء مستقيمة مسمّاة A وB وC وD. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 10 s كل 1 s، وتدريج الموقع من −6 إلى 10 m كل 2 m، ومحور الزمن عند الموقع 0. الجزء A من (0 s، 0 m) إلى (2 s، 8 m). الجزء B أفقي من (2 s، 8 m) إلى (5 s، 8 m). الجزء C هابط من (5 s، 8 m) إلى (7 s، −4 m). الجزء D صاعد من (7 s، −4 m) إلى (10 s، −1 m)."}]'::jsonb, '["الجزء D","الجزء B","الجزء C","الجزء A"]'::jsonb, 'تحليل', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 45 — ميل سالب: الحركة في الاتجاه السالب بمعدل 5.0 m/s (الشكل 2-21)'),
('mcq', 2, 'ماذا يدل عليه جزء أفقي (موازٍ لمحور الزمن) في منحنى (الموقع – الزمن) لجسم؟', null, null, '["الجسم ساكن، وسرعته المتجهة صفر","الجسم يتحرك بسرعة متجهة ثابتة لا تساوي صفرًا","الجسم يتحرك في الاتجاه السالب","الجسم موجود عند نقطة الأصل"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 23 — معنى الحصول على خط أفقي في منحنى المسافة مع الزمن'),
('mcq', 3, 'يمثل المنحنى الآتي حركة جسم على خط مستقيم في أربعة أجزاء. في أي جزء كان مقدار سرعة الجسم أكبر ما يمكن؟', null, '[{"src":"qimg/phys1/c2l4-o05-segs2.svg","alt":"منحنى (الموقع – الزمن) لجسم مكوّن من أربعة أجزاء مستقيمة مسمّاة A وB وC وD. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 10 s كل 1 s، وتدريج الموقع من 0 إلى 10 m كل 2 m. الجزء A من (0 s، 2 m) إلى (3 s، 8 m). الجزء B أفقي من (3 s، 8 m) إلى (5 s، 8 m). الجزء C هابط من (5 s، 8 m) إلى (7 s، 0 m). الجزء D صاعد من (7 s، 0 m) إلى (10 s، 3 m)."}]'::jsonb, '["الجزء A","الجزء B","الجزء D","الجزء C"]'::jsonb, 'تحليل', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 43 — الميل الأكبر يدل على تغير أكبر في الإزاحة خلال الفترة نفسها'),
('mcq', 4, 'وُجد أن ميل منحنى (الموقع – الزمن) لجسم يساوي $-5.0\ \text{m/s}$. أي العبارات الآتية تصف حركته وصفًا صحيحًا؟', null, null, '["يتباطأ بمقدار 5.0 m/s في كل ثانية","يتحرك في الاتجاه السالب بمعدل 5.0 m/s","يقع دائمًا في الجانب السالب من نقطة الأصل","يتحرك في الاتجاه الموجب بمعدل 5.0 m/s"]'::jsonb, 'تحليل', 'تفسير', 'متوسط', 'الكتاب ص 45 — ميل سالب: الحركة في الاتجاه السالب بمعدل 5.0 m/s (الشكل 2-21)'),
('mcq', 5, 'يمثل المنحنى الآتي حركة جسم على خط مستقيم. ماذا يحدث للجسم عند اللحظة 4 s؟', null, '[{"src":"qimg/phys1/c2l4-o05-cross.svg","alt":"منحنى (الموقع – الزمن) لجسم. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من −8 إلى 12 m كل 2 m، ومحور الزمن عند الموقع 0. خط مستقيم أزرق هابط يبدأ من (0 s، 12 m) ويقطع محور الزمن عند (4 s، 0 m) ويستمر إلى (6 s، −6 m)."}]'::jsonb, '["يتوقف لحظيًا عند نقطة الأصل ثم يعكس اتجاه حركته","يبدأ بالتحرك في الاتجاه الموجب؛ لأن مواقعه تصبح سالبة بعدها","تصبح سرعته المتجهة صفرًا لأن موقعه صفر","يمر بنقطة الأصل ويستمر في الاتجاه السالب بالسرعة نفسها"]'::jsonb, 'تحليل', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 45 — ميل سالب: الحركة في الاتجاه السالب بمعدل 5.0 m/s (الشكل 2-21)'),
('mcq', 6, 'يمثل المنحنى الآتي حركة جسمين E وF على خط مستقيم. أي العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c2l4-o05-twoneg.svg","alt":"منحنى (الموقع – الزمن) لجسمين E وF. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من −12 إلى 12 m كل 2 m، ومحور الزمن عند الموقع 0. الخط E (أزرق) مستقيم هابط من (0 s، 10 m) إلى (5 s، 0 m). الخط F (أحمر) مستقيم هابط من (0 s، 4 m) إلى (5 s، −11 m)."}]'::jsonb, '["F أسرع من E، ويتحركان في الاتجاه نفسه","E أسرع من F؛ لأن ميل E أكبر عدديًا من ميل F","يتحركان في اتجاهين متعاكسين؛ لأن مواقع F تصبح سالبة","F أبطأ من E؛ لأن خط F يقع أسفل خط E"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 43 — الميل الأكبر يدل على تغير أكبر في الإزاحة خلال الفترة نفسها'),
('mcq', 7, 'كلما ازداد انحدار الخط البياني في منحنى (الموقع – الزمن) لجسم، دلّ ذلك على:', null, null, '["موقع ابتدائي أبعد للجسم عن نقطة الأصل عند بدء الحركة","فترة زمنية أطول يستغرقها الجسم لقطع الإزاحة نفسها","تغير أكبر في الموقع خلال الفترة الزمنية نفسها","تسارع أكبر للجسم، أي تزايد سرعته مع مرور الزمن"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 43 — الميل الأكبر يدل على تغير أكبر في الإزاحة خلال الفترة نفسها'),
('essay', 1, 'يمثل المنحنى الآتي حركة طالب ذهابًا وإيابًا في ممر مستقيم، والاتجاه الموجب بعيدًا عن بداية الممر. (أ) صف حركة الطالب في كل جزء من الأجزاء الخمسة (هل يتحرك؟ في أي اتجاه؟). (ب) في أي جزء كان أسرع ما يمكن؟ برّر إجابتك بالحساب.', null, '[{"src":"qimg/phys1/c2l4-o05-essay1.svg","alt":"منحنى (الموقع – الزمن) لحركة طالب في ممر مستقيم، مكوّن من خمسة أجزاء مستقيمة. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 60 s كل 5 s، وتدريج الموقع من 0 إلى 14 m كل 2 m. النقاط المتتالية: (0 s، 0 m) ثم (10 s، 6 m) ثم (30 s، 6 m) ثم (40 s، 12 m) ثم (45 s، 12 m) ثم (55 s، 0 m)."}]'::jsonb, null, 'تحليل', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 55–56 — السؤال 54 (حركة علي في ممر)'),
('essay', 2, 'هل يمكن أن يكون منحنى (الموقع – الزمن) لجسم خطًا أفقيًا؟ وهل يمكن أن يكون خطًا رأسيًا؟ فسّر إجابتك في كل حالة اعتمادًا على معنى الميل، وصف الحركة بالكلمات إن كانت ممكنة.', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 56 — السؤال 56 (تفسير الرسوم البيانية)'),
('essay', 3, 'يمثل المنحنى الآتي حركة جسمين G وH. قال طالب: «الجسم G يتحرك في الاتجاه السالب لأن مواقعه سالبة، والجسم H يتحرك في الاتجاه الموجب لأن مواقعه موجبة». قوّم قول الطالب، ثم صف حركة كل جسم وصفًا صحيحًا مدعّمًا بالحساب، وقارن بين سرعتيهما.', null, '[{"src":"qimg/phys1/c2l4-o05-essay3.svg","alt":"منحنى (الموقع – الزمن) لجسمين G وH. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 4 s كل 1 s، وتدريج الموقع من −10 إلى 12 m كل 2 m، ومحور الزمن عند الموقع 0. الخط G (أزرق) مستقيم صاعد من (0 s، −8 m) إلى (4 s، −2 m) ويبقى كله تحت محور الزمن. الخط H (أحمر) مستقيم هابط من (0 s، 10 m) إلى (4 s، 4 m) ويبقى كله فوق محور الزمن."}]'::jsonb, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 45 — ميل سالب: الحركة في الاتجاه السالب بمعدل 5.0 m/s (الشكل 2-21)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'اتجاه الحركة تحدده إشارة الميل لا إشارة الموقع. في C يتناقص الموقع من 8 m إلى $-4\ \text{m}$، فالميل $\frac{-4 - 8}{7 - 5} = -6\ \text{m/s}$ سالب، والحركة في الاتجاه السالب.', '["مواقع الجسم في D سالبة، لكن الموقع يزداد مع الزمن (ميل موجب)، فالحركة في الاتجاه الموجب.","الخط أفقي في B؛ أي أن الموقع لا يتغير والجسم ساكن، فلا يتحرك في أي اتجاه.","","الموقع يزداد في A من 0 m إلى 8 m، فالميل موجب والحركة في الاتجاه الموجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-18T12:34:59.267Z"}'::jsonb),
('mcq', 2, 0, 'الخط الأفقي يعني أن الموقع لا يتغير مع مرور الزمن، فميله صفر؛ أي أن السرعة المتجهة صفر والجسم ساكن.', '["","الحركة بسرعة ثابتة غير صفرية تعطي خطًا مائلًا مستقيمًا، لا خطًا أفقيًا.","الحركة في الاتجاه السالب تعطي خطًا هابطًا (ميله سالب)، لا أفقيًا.","الخط الأفقي قد يكون عند أي موقع؛ ولا يكون عند نقطة الأصل إلا إذا انطبق على محور الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.267Z"}'::jsonb),
('mcq', 3, 3, 'مقدار السرعة يُعرف من شدة الانحدار بغض النظر عن الإشارة: A: $+2$، B: $0$، C: $\frac{0 - 8}{7 - 5} = -4$، D: $+1$ (بوحدة m/s). أشد الأجزاء انحدارًا C، فمقدار السرعة فيه 4 m/s.', '["ميل A $= +2\\ \\text{m/s}$ هو أكبر ميل موجب، لكن مقدار ميل C ($4\\ \\text{m/s}$) أكبر؛ والإشارة تدل على الاتجاه لا على المقدار.","B أفقي، فالجسم ساكن وسرعته صفر، وهي أصغر قيمة لا أكبرها.","ميل D $= +1\\ \\text{m/s}$ فقط، وهو أقل الأجزاء المتحركة انحدارًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-18T12:34:59.268Z"}'::jsonb),
('mcq', 4, 1, 'الميل هو السرعة المتجهة المتوسطة؛ مقداره 5.0 m/s يدل على سرعة الحركة، وإشارته السالبة تدل على أن الحركة في الاتجاه السالب.', '["هذا وصف لتسارع؛ أما ميل منحنى (الموقع – الزمن) فهو سرعة متجهة.","","الإشارة السالبة للميل تخص اتجاه الحركة لا قيمة الموقع؛ فقد تكون مواقعه موجبة.","الميل السالب يعني أن الموقع يتناقص، أي حركة في الاتجاه السالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.268Z"}'::jsonb),
('mcq', 5, 3, 'عند 4 s يقطع الخط محور الزمن، أي أن موقع الجسم صفر (نقطة الأصل). وبما أن الخط مستقيم ميله ثابت $\frac{-6 - 12}{6 - 0} = -3\ \text{m/s}$، يستمر الجسم في الاتجاه السالب بالسرعة نفسها.', '["التوقف وعكس الاتجاه يظهران بتغير الميل، والخط هنا مستقيم بميل ثابت.","اتجاه الحركة تحدده إشارة الميل، والميل سالب قبل 4 s وبعدها.","الموقع صفر لا يعني أن السرعة صفر؛ السرعة هي الميل ويبقى $-3\\ \\text{m/s}$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-18T12:34:59.268Z"}'::jsonb),
('mcq', 6, 0, 'ميل E $= \frac{0 - 10}{5} = -2\ \text{m/s}$، وميل F $= \frac{-11 - 4}{5} = -3\ \text{m/s}$. كلاهما سالب فالاتجاه واحد (السالب)، وخط F أشد انحدارًا فهو أسرع.', '["","صحيح أن $-2 > -3$، لكن مقدار السرعة يُقارن بشدة الانحدار؛ و$|-3| > |-2|$ فـ F أسرع.","إشارة الموقع لا تحدد الاتجاه؛ كلا الخطين هابط، فكلاهما يتحرك في الاتجاه السالب.","موقع الخط على الرسم يدل على الموقع لا على السرعة؛ السرعة تُعرف من الانحدار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-18T12:34:59.268Z"}'::jsonb),
('mcq', 7, 2, 'الانحدار الأكبر يعني أن مقدار التغير في الإزاحة أكبر خلال الفترة الزمنية نفسها، أي أن الجسم يتحرك بسرعة أكبر.', '["الموقع الابتدائي يُقرأ من تقاطع الخط مع محور الموقع، ولا علاقة له بالانحدار.","الانحدار الأكبر يعني أن الجسم يحتاج زمنًا أقل لتغيير موقعه بالمقدار نفسه.","","الخط المستقيم في منحنى (الموقع – الزمن) يدل على سرعة ثابتة؛ والانحدار يمثل السرعة لا التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.268Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) من 0 إلى 10 s: يتحرك في الاتجاه الموجب (الميل $\frac{6}{10} = 0.6\ \text{m/s}$). من 10 إلى 30 s: ساكن عند 6 m (خط أفقي). من 30 إلى 40 s: يتحرك في الاتجاه الموجب ($\frac{12 - 6}{10} = 0.6\ \text{m/s}$). من 40 إلى 45 s: ساكن عند 12 m. من 45 إلى 55 s: يعود في الاتجاه السالب نحو بداية الممر ($\frac{0 - 12}{10} = -1.2\ \text{m/s}$). (ب) كان أسرع في الجزء الأخير (45–55 s)؛ لأن خطه الأشد انحدارًا ومقدار ميله 1.2 m/s أكبر من 0.6 m/s، والإشارة السالبة تعني الاتجاه فقط.', '["الجزءان 0–10 و30–40 s حركة في الاتجاه الموجب","الجزءان 10–30 و40–45 s سكون","الجزء 45–55 s حركة في الاتجاه السالب","الأسرع: الجزء الأخير بمقدار 1.2 m/s"]'::jsonb, '["ميل 0–10 s: $\\frac{6 - 0}{10} = 0.6\\ \\text{m/s}$","ميل 30–40 s: $\\frac{12 - 6}{10} = 0.6\\ \\text{m/s}$","ميل 45–55 s: $\\frac{0 - 12}{10} = -1.2\\ \\text{m/s}$","المقارنة: $1.2 > 0.6$"]'::jsonb, '[{"element":"وصف أجزاء الحركة الموجبة","marks":1},{"element":"وصف أجزاء السكون","marks":1},{"element":"وصف الجزء السالب","marks":1},{"element":"تحديد الأسرع مع الحساب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح لكل الأجزاء وتحديد الأسرع بحساب صحيح"},{"level":"2–3 درجات","description":"وصف صحيح لمعظم الأجزاء أو تحديد الأسرع دون حساب"},{"level":"1 درجة","description":"وصف جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف الخط الأفقي بأنه حركة بسرعة ثابتة","اعتبار الجزء الأخير أبطأ لأن ميله سالب","الحكم على السرعة من ارتفاع الخط لا من انحداره"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.268Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخط الأفقي ممكن: يعني أن الموقع لا يتغير مع الزمن، فالميل (السرعة المتجهة) صفر، أي أن الجسم ساكن في موقع ثابت. أما الخط الرأسي فغير ممكن: لأنه يعني أن الموقع يتغير دون أن يمر أي زمن ($\Delta t = 0$)، فيكون الجسم في أكثر من موقع في اللحظة نفسها، وتكون سرعته لا نهائية، وهذا مستحيل.', '["الخط الأفقي ممكن","معناه: ميل صفر، الجسم ساكن","الخط الرأسي غير ممكن","تعليله: تغير الموقع دون مرور زمن (سرعة لا نهائية/جسم في موقعين في اللحظة نفسها)"]'::jsonb, '[]'::jsonb, '[{"element":"حكم الخط الأفقي","marks":1},{"element":"وصف حركة الخط الأفقي","marks":1},{"element":"حكم الخط الرأسي","marks":1},{"element":"تعليل الخط الرأسي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكمان صحيحان مع تفسير كامل"},{"level":"2–3 درجات","description":"حكمان صحيحان مع تفسير ناقص"},{"level":"1 درجة","description":"حكم واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخط الأفقي يعني سرعة ثابتة غير صفرية","القول إن الخط الرأسي يعني جسمًا ساكنًا","عدم ربط التفسير بالميل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.268Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب خاطئ؛ لأن اتجاه الحركة تحدده إشارة الميل (السرعة المتجهة) لا إشارة الموقع. ميل G $= \frac{-2 - (-8)}{4 - 0} = 1.5\ \text{m/s}$، فـ G يتحرك في الاتجاه الموجب مقتربًا من نقطة الأصل رغم أن مواقعه سالبة. وميل H $= \frac{4 - 10}{4 - 0} = -1.5\ \text{m/s}$، فـ H يتحرك في الاتجاه السالب مقتربًا من نقطة الأصل رغم أن مواقعه موجبة. للجسمين مقدار السرعة نفسه 1.5 m/s، لكنهما يتحركان في اتجاهين متعاكسين.', '["الحكم: القول خاطئ","الاتجاه تحدده إشارة الميل لا الموقع","G: ميل $+1.5\\ \\text{m/s}$، اتجاه موجب","H: ميل $-1.5\\ \\text{m/s}$، اتجاه سالب","مقدار السرعة متساوٍ والاتجاهان متعاكسان"]'::jsonb, '["ميل G: $\\frac{-2\\ \\text{m} - (-8\\ \\text{m})}{4\\ \\text{s}} = 1.5\\ \\text{m/s}$","ميل H: $\\frac{4\\ \\text{m} - 10\\ \\text{m}}{4\\ \\text{s}} = -1.5\\ \\text{m/s}$"]'::jsonb, '[{"element":"الحكم مع التعليل","marks":1},{"element":"حساب ميل G وتفسيره","marks":1},{"element":"حساب ميل H وتفسيره","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتعليل وحسابان صحيحان ومقارنة سليمة"},{"level":"2–3 درجات","description":"حكم صحيح مع حساب واحد أو مقارنة ناقصة"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين إشارة الموقع وإشارة السرعة المتجهة","خطأ في طرح العددين السالبين $(-2) - (-8)$","الحكم بأن أحدهما أسرع لأنه أعلى في الرسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.268Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
