select (select id from public.objectives where code = 'P1-C2-L4-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالسرعة المتوسطة لجسم متحرك؟', null, null, '["التغير في الموقع مقسومًا على الفترة الزمنية مع إشارته","القيمة المطلقة للسرعة المتجهة المتوسطة للجسم","السرعة المتجهة عند لحظة زمنية تؤول إلى الصفر","التغير في السرعة المتجهة مقسومًا على الفترة الزمنية"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 53 — السرعة المتوسطة هي القيمة المطلقة للسرعة المتجهة المتوسطة'),
