('mcq', 2, 'يمثل المنحنى الآتي حركة قارب على خط مستقيم، والاتجاه الموجب نحو الشرق. أي العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c2l4-o07-boat.svg","alt":"منحنى (الموقع – الزمن) لقارب، والاتجاه الموجب نحو الشرق. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من −16 إلى 2 m كل 2 m، ومحور الزمن عند الموقع 0. خط مستقيم أزرق هابط يبدأ من (0 s، 0 m) وينتهي عند (5 s، −15 m)."}]'::jsonb, '["سرعته المتجهة المتوسطة 3.0 m/s، وسرعته المتوسطة $-3.0\\ \\text{m/s}$","سرعته المتجهة المتوسطة $-3.0\\ \\text{m/s}$، وسرعته المتوسطة 3.0 m/s","سرعته المتجهة المتوسطة $-3.0\\ \\text{m/s}$، وسرعته المتوسطة $-3.0\\ \\text{m/s}$","سرعته المتجهة المتوسطة 3.0 m/s، وسرعته المتوسطة 3.0 m/s"]'::jsonb, 'تطبيق', 'حساب ومقارنة', 'سهل', 'الكتاب ص 45 — التمييز بين السرعة المتجهة المتوسطة والسرعة المتوسطة'),
('mcq', 3, 'جسمان A وB يتحرك كل منهما على خط مستقيم دون أن يغيّر اتجاه حركته، ولكل منهما السرعة المتوسطة نفسها 5.0 m/s. ماذا يمكن أن نستنتج عن سرعتيهما المتجهتين المتوسطتين؟', null, null, '["متساويتان مقدارًا، وقد تختلفان اتجاهًا","متساويتان في المقدار والاتجاه حتمًا","مختلفتان في المقدار حتمًا لاختلاف الجسمين","إحداهما سالبة حتمًا والأخرى موجبة"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 45 — التمييز بين السرعة المتجهة المتوسطة والسرعة المتوسطة'),
('mcq', 4, 'في أي حالة تختلف قيمة السرعة المتجهة المتوسطة لجسم يتحرك على خط مستقيم دون أن يغيّر اتجاه حركته عن قيمة سرعته المتوسطة؟', null, null, '["عندما يتحرك الجسم في الاتجاه الموجب","عندما يكون الموقع الابتدائي للجسم سالبًا","عندما يتحرك الجسم في الاتجاه السالب","عندما يتحرك الجسم بسرعة متجهة ثابتة"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 45 — التمييز بين السرعة المتجهة المتوسطة والسرعة المتوسطة'),
('mcq', 5, 'أيّ الكميتين تحدد اتجاه حركة الجسم؟', null, null, '["السرعة المتوسطة؛ لأنها قيمة مطلقة موجبة دائمًا","السرعة المتجهة المتوسطة؛ لأن لها إشارة","كلتاهما؛ لأن لهما الوحدة نفسها m/s","كلتاهما؛ لأنهما تُحسبان من ميل الخط نفسه"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 45 — التمييز بين السرعة المتجهة المتوسطة والسرعة المتوسطة'),
('mcq', 6, 'يحسب نظام الرصد الآلي على الطرق سرعة السيارة خلال إزاحة محددة بين موقعين مع إمكانية تحديد الاتجاه، بينما يحسب حساس AVG في السيارة المسافة الكلية على الزمن الكلي دون اعتبار الاتجاه. أي العبارات الآتية صحيحة؟', null, null, '["الأول يقيس السرعة المتوسطة، والثاني يقيس السرعة المتجهة المتوسطة","كلاهما يقيس السرعة المتجهة المتوسطة","الأول يقيس السرعة المتجهة المتوسطة، والثاني يقيس السرعة المتوسطة","الأول يقيس السرعة المتجهة اللحظية، والثاني يقيس السرعة المتوسطة"]'::jsonb, 'تحليل', 'تطبيق في الحياة', 'متوسط', 'الكتاب ص 45 — تطبيق الفيزياء (نظام ساهر، حساس السرعة، نظام الرصد الآلي)'),
('mcq', 7, 'تتحرك سيارتان على طريق مستقيم دون أن تغيّر أيّ منهما اتجاه حركتها؛ السرعة المتجهة المتوسطة للأولى $-20\ \text{m/s}$، وللثانية $+15\ \text{m/s}$. أي العبارات الآتية صحيحة؟', null, null, '["السرعة المتوسطة للثانية أكبر؛ لأن سرعتها المتجهة المتوسطة موجبة","للسيارتين السرعة المتوسطة نفسها؛ لأن كلتيهما تتحرك بسرعة ثابتة","الأولى أصغر من الثانية في السرعة المتجهة المتوسطة وفي السرعة المتوسطة","السرعة المتوسطة للأولى أكبر، مع أن سرعتها المتجهة المتوسطة أصغر عدديًا"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 45 — التمييز بين السرعة المتجهة المتوسطة والسرعة المتوسطة'),
('essay', 1, 'قارن بين السرعة المتجهة المتوسطة والسرعة المتوسطة من حيث: (أ) التعريف. (ب) نوع الكمية (متجهة أم عددية). (ج) إمكانية أن تكون سالبة. (د) طريقة الحصول عليها من منحنى (الموقع – الزمن).', null, null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 45 — التمييز بين السرعة المتجهة المتوسطة والسرعة المتوسطة'),
('essay', 2, 'يمثل المنحنى الآتي حركة جسمين K وM على خط مستقيم. (أ) احسب السرعة المتجهة المتوسطة لكل جسم. (ب) احسب السرعة المتوسطة لكل جسم. (ج) قارن بين الجسمين في كل من الكميتين، وفسّر سبب اختلاف نتيجتي المقارنة.', null, '[{"src":"qimg/phys1/c2l4-o07-essay.svg","alt":"منحنى (الموقع – الزمن) لجسمين K وM. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 4 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط K (أزرق) مستقيم صاعد من (0 s، 0 m) إلى (4 s، 12 m). الخط M (أحمر) مستقيم هابط من (0 s، 20 m) إلى (4 s، 8 m)."}]'::jsonb, null, 'تحليل', 'حساب ومقارنة', 'متوسط', 'الكتاب ص 45 — التمييز بين السرعة المتجهة المتوسطة والسرعة المتوسطة'),
('essay', 3, 'قال طالب: «السرعة المتجهة المتوسطة والسرعة المتوسطة اسمان لكمية واحدة؛ لأن لهما الوحدة نفسها m/s وتُحسبان من ميل الخط نفسه». قوّم هذا القول، ودعّم رأيك بمثال عددي.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 49 — السؤال 32 (العلاقة بين السرعة المتوسطة والسرعة المتجهة المتوسطة)')
