from (values
('mcq', 1, 3, 'السرعة المتجهة المتوسطة تساوي ميل منحنى (الموقع – الزمن) بإشارته، فلها مقدار واتجاه؛ أما السرعة المتوسطة فهي قيمتها المطلقة، أي المقدار فقط.', '["عكس الصحيح؛ السرعة المتجهة المتوسطة هي المتجهة، والسرعة المتوسطة هي العددية.","السرعة المتوسطة قيمة مطلقة فلا تحمل إشارة ولا اتجاهًا.","تختلفان في الإشارة عندما تكون الحركة في الاتجاه السالب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.270Z"}'::jsonb),
('mcq', 2, 1, 'الميل $= \frac{-15 - 0}{5 - 0} = -3.0\ \text{m/s}$، وهو السرعة المتجهة المتوسطة (3.0 m/s نحو الغرب)، والسرعة المتوسطة قيمته المطلقة 3.0 m/s.', '["بدّل بين الكميتين؛ الإشارة السالبة تخص السرعة المتجهة المتوسطة، والسرعة المتوسطة لا تكون سالبة.","","السرعة المتوسطة قيمة مطلقة، فلا تحمل الإشارة السالبة.","أهمل أن القارب يتحرك نحو الغرب (الاتجاه السالب)، فسرعته المتجهة المتوسطة سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.270Z"}'::jsonb),
('mcq', 3, 0, 'السرعة المتوسطة هي القيمة المطلقة للسرعة المتجهة المتوسطة، فمقدار كل منهما 5.0 m/s، لكن كل منهما قد تكون $+5.0$ أو $-5.0\ \text{m/s}$ بحسب اتجاه الحركة. إذن السرعتان المتجهتان المتوسطتان متساويتان مقدارًا، وقد تختلفان اتجاهًا.', '["","تساوي السرعة المتوسطة لا يضمن تساوي الاتجاه؛ فقد تكون إحداهما $+5.0\\ \\text{m/s}$ والأخرى $-5.0\\ \\text{m/s}$.","مقدار السرعة المتجهة المتوسطة يساوي السرعة المتوسطة، فالمقداران متساويان 5.0 m/s.","قد تكون كلتاهما موجبة أو كلتاهما سالبة؛ فلا شيء يفرض أن تكون إحداهما سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:59.270Z"}'::jsonb),
('mcq', 4, 2, 'السرعة المتوسطة قيمة مطلقة دائمًا؛ فتختلف عن السرعة المتجهة المتوسطة فقط عندما تكون الأخيرة سالبة، أي عندما يتحرك الجسم في الاتجاه السالب.', '["في الاتجاه الموجب تكون السرعة المتجهة المتوسطة موجبة فتساوي قيمتها المطلقة.","إشارة الموقع لا تحدد إشارة السرعة المتجهة؛ المهم اتجاه الحركة.","","ثبات السرعة لا يغير العلاقة بين الكميتين؛ يحددها اتجاه الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:59.271Z"}'::jsonb),
('mcq', 5, 1, 'السرعة المتجهة المتوسطة كمية متجهة، وإشارتها (موجبة أو سالبة) تدل على اتجاه الحركة؛ أما السرعة المتوسطة فتعبر عن المقدار فقط.', '["كونها قيمة مطلقة يعني أنها لا تحمل أي معلومة عن الاتجاه.","","تساوي الوحدة لا يعني أن الكميتين تحملان المعلومات نفسها؛ إحداهما فقط لها اتجاه.","السرعة المتوسطة تُؤخذ من القيمة المطلقة للميل، فتفقد الإشارة التي تدل على الاتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.271Z"}'::jsonb),
('mcq', 6, 2, 'حساب السرعة خلال إزاحة محددة مع الاتجاه هو السرعة المتجهة المتوسطة، وحسابها دون اعتبار الاتجاه يعطي مقدار السرعة فقط، أي السرعة المتوسطة.', '["بدّل بين الكميتين؛ تحديد الاتجاه والإزاحة صفتا السرعة المتجهة المتوسطة.","الحساس AVG لا يعتبر الاتجاه، فهو لا يقيس كمية متجهة.","","الرصد الآلي يحسب السرعة خلال إزاحة بين موقعين، لا في لحظة زمنية تؤول إلى الصفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.271Z"}'::jsonb),
('mcq', 7, 3, 'بالإشارة: $-20 < +15$، فالسرعة المتجهة المتوسطة للأولى أصغر عدديًا. وبالقيمة المطلقة: 20 m/s > 15 m/s، فالسرعة المتوسطة للأولى أكبر، أي أنها أسرع لكنها تتحرك في الاتجاه السالب.', '["السرعة المتوسطة تقارن بالقيم المطلقة: 20 m/s أكبر من 15 m/s.","السرعتان المتوسطتان 20 m/s و15 m/s، وهما مختلفتان.","هي أصغر عدديًا في السرعة المتجهة المتوسطة فقط، لكنها أكبر في السرعة المتوسطة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.271Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) السرعة المتجهة المتوسطة: الإزاحة مقسومة على الفترة الزمنية؛ والسرعة المتوسطة: القيمة المطلقة للسرعة المتجهة المتوسطة. (ب) الأولى متجهة لها مقدار واتجاه، والثانية عددية لها مقدار فقط. (ج) الأولى قد تكون موجبة أو سالبة بحسب اتجاه الحركة، والثانية لا تكون سالبة. (د) الأولى هي ميل الخط البياني بإشارته، والثانية هي القيمة المطلقة لهذا الميل.', '["التعريفان","متجهة / عددية","الأولى قد تكون سالبة والثانية لا","الميل بإشارته / القيمة المطلقة للميل"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"نوع الكمية","marks":1},{"element":"الإشارة","marks":1},{"element":"الاستخراج من المنحنى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الجوانب الأربعة"},{"level":"2–3 درجات","description":"مقارنة صحيحة في جانبين أو ثلاثة"},{"level":"1 درجة","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس نوعي الكميتين","القول إن السرعة المتوسطة قد تكون سالبة","تعريف السرعة المتجهة المتوسطة بالمسافة بدل الإزاحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.271Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) K: $\boldsymbol{\bar{v}} = \frac{12 - 0}{4} = 3.0\ \text{m/s}$؛ M: $\boldsymbol{\bar{v}} = \frac{8 - 20}{4} = -3.0\ \text{m/s}$. (ب) السرعة المتوسطة لكل منهما 3.0 m/s. (ج) السرعة المتوسطة متساوية (يتحركان بالمقدار نفسه)، أما السرعة المتجهة المتوسطة فمختلفة لأن K يتحرك في الاتجاه الموجب وM في الاتجاه السالب؛ فالاختلاف سببه أن السرعة المتجهة المتوسطة تتضمن الاتجاه والسرعة المتوسطة لا تتضمنه.', '["K: $+3.0\\ \\text{m/s}$","M: $-3.0\\ \\text{m/s}$","السرعة المتوسطة لكليهما 3.0 m/s","متساويان في السرعة المتوسطة ومختلفان في السرعة المتجهة المتوسطة بسبب الاتجاه"]'::jsonb, '["K: $\\frac{12\\ \\text{m} - 0}{4\\ \\text{s}} = 3.0\\ \\text{m/s}$","M: $\\frac{8\\ \\text{m} - 20\\ \\text{m}}{4\\ \\text{s}} = -3.0\\ \\text{m/s}$","السرعة المتوسطة: $|3.0| = |-3.0| = 3.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"السرعتان المتجهتان المتوسطتان","marks":1},{"element":"السرعتان المتوسطتان","marks":1},{"element":"المقارنة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة ومقارنة وتفسير كاملان"},{"level":"2–3 درجات","description":"حسابات صحيحة مع تفسير ناقص"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال إشارة M","الحكم بأن M أسرع لأنه بدأ من موقع أعلى","كتابة سرعة متوسطة سالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.271Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القول غير صحيح. صحيح أن لهما الوحدة نفسها وتُستخرجان من الميل نفسه، لكن السرعة المتجهة المتوسطة هي الميل بإشارته، فهي كمية متجهة تحدد الاتجاه، أما السرعة المتوسطة فهي القيمة المطلقة للميل، أي المقدار فقط. مثال: جسم يتحرك في الاتجاه السالب بميل $-5.0\ \text{m/s}$؛ سرعته المتجهة المتوسطة $-5.0\ \text{m/s}$، وسرعته المتوسطة 5.0 m/s؛ فالقيمتان مختلفتان. وتتساويان (لجسم لا يغيّر اتجاه حركته) فقط عندما تكون الحركة في الاتجاه الموجب.', '["الحكم: القول غير صحيح","الأولى الميل بإشارته (متجهة)","الثانية القيمة المطلقة للميل (عددية)","مثال عددي صحيح","تتساويان في الاتجاه الموجب فقط"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التمييز بين الكميتين","marks":1},{"element":"المثال العددي","marks":1},{"element":"بيان متى تتساويان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تمييز ومثال وبيان حالة التساوي"},{"level":"2–3 درجات","description":"حكم وتمييز صحيحان دون مثال أو دون حالة التساوي"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على القول","مثال عددي تكون فيه السرعة المتوسطة سالبة","الاعتماد على الوحدة وحدها في التمييز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.271Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O07') and x.type = v.type and x.number = v.number
