insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L4-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل المنحنى الآتي حركة أربعة أجسام. ما ترتيبها وفق السرعة المتجهة المتوسطة من الأكبر إلى الأصغر؟', null, '[{"src":"qimg/phys1/c2l4-o08-rank1.svg","alt":"منحنى (الموقع – الزمن) لأربعة أجسام A وB وC وD. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط A (أزرق) من (0 s، 4 m) إلى (5 s، 19 m). الخط B (أحمر) من (0 s، 0 m) إلى (5 s، 5 m). الخط C (أخضر) هابط من (0 s، 16 m) إلى (5 s، 6 m). الخط D (برتقالي) أفقي عند 8 m من 0 s إلى 5 s."}]'::jsonb, '["A، ثم B، ثم D، ثم C","A، ثم C، ثم B، ثم D","C، ثم D، ثم A، ثم B","A، ثم D، ثم C، ثم B"]'::jsonb, 'تحليل', 'ترتيب', 'سهل', 'الكتاب ص 49 — مراجعة 2-4 السؤالان 30 و32'),
('mcq', 2, 'يمثل المنحنى الآتي حركة أربعة طلاب في طريق عودتهم من المدرسة. ما ترتيبهم وفق السرعة المتجهة المتوسطة من الأبطأ إلى الأسرع؟', null, '[{"src":"qimg/phys1/c2l4-o08-rank2.svg","alt":"منحنى (الموقع – الزمن) لأربعة طلاب X وY وZ وW. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 8 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط X (أزرق) من (0 s، 0 m) إلى (6 s، 18 m). الخط Y (أحمر) من (0 s، 6 m) إلى (8 s، 18 m). الخط Z (أخضر) يبدأ متأخرًا من (2 s، 0 m) إلى (7 s، 15 m). الخط W (برتقالي) من (0 s، 10 m) إلى (8 s، 14 m)."}]'::jsonb, '["W، ثم Y، ثم X، ثم Z","W، ثم Z، ثم X وY متساويان","W، ثم Y، ثم X وZ متساويان","X وZ متساويان، ثم Y، ثم W"]'::jsonb, 'تحليل', 'ترتيب', 'متوسط', 'الكتاب ص 54 — السؤال 44 (ترتيب الطلاب بحسب السرعة المتجهة المتوسطة)'),
('mcq', 3, 'يبيّن الجدول الآتي ميل منحنى (الموقع – الزمن) لأربعة أجسام. ما ترتيبها وفق السرعة المتجهة المتوسطة من الأكبر إلى الأصغر؟', '{"headers":["الجسم","الميل (m/s)"],"rows":[["P","$+2.5$"],["Q","$-4.0$"],["R","$+1.0$"],["S","$-1.5$"]]}'::jsonb, null, '["Q، ثم P، ثم S، ثم R","P، ثم R، ثم Q، ثم S","Q، ثم S، ثم R، ثم P","P، ثم R، ثم S، ثم Q"]'::jsonb, 'تحليل', 'ترتيب', 'سهل', 'الكتاب ص 49 — مراجعة 2-4 السؤالان 30 و32'),
('mcq', 4, 'يمثل المنحنى الآتي حركة ثلاثة أجسام تتحرك جميعها في الاتجاه السالب. ما ترتيبها وفق السرعة المتجهة المتوسطة من الأكبر إلى الأصغر؟', null, '[{"src":"qimg/phys1/c2l4-o08-rank3.svg","alt":"منحنى (الموقع – الزمن) لثلاثة أجسام E وF وG، وكل الخطوط هابطة. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط E (أزرق) من (0 s، 12 m) إلى (5 s، 7 m). الخط F (أحمر) من (0 s، 18 m) إلى (5 s، 3 m). الخط G (أخضر) من (0 s، 20 m) إلى (5 s، 10 m)."}]'::jsonb, '["F، ثم G، ثم E","E، ثم G، ثم F","G، ثم F، ثم E","G، ثم E، ثم F"]'::jsonb, 'تحليل', 'ترتيب', 'صعب', 'الكتاب ص 49 — مراجعة 2-4 السؤالان 30 و32'),
('mcq', 5, 'عند ترتيب منحنيات (الموقع – الزمن) لعدة أجسام وفق السرعة المتجهة المتوسطة، نعتمد على:', null, null, '["القيمة المطلقة لميل كل خط","تقاطع كل خط مع محور الموقع","ميل كل خط بإشارته","الموقع النهائي لكل جسم"]'::jsonb, 'فهم', 'إجراء', 'سهل', 'الكتاب ص 49 — مراجعة 2-4 السؤالان 30 و32'),
('mcq', 6, 'يبيّن الجدول الآتي بيانات حركة ثلاثة أجسام على خط مستقيم. ما ترتيبها وفق السرعة المتجهة المتوسطة من الأكبر إلى الأصغر؟', '{"headers":["الجسم","الموقع الابتدائي (m)","الموقع النهائي (m)","الفترة الزمنية (s)"],"rows":[["1","2.0","14.0","4.0"],["2","20.0","4.0","4.0"],["3","$-6.0$","2.0","2.0"]]}'::jsonb, null, '["2 و3 متساويان، ثم 1","3، ثم 1، ثم 2","1، ثم 2، ثم 3","2، ثم 1، ثم 3"]'::jsonb, 'تطبيق', 'حساب وترتيب', 'متوسط', 'الكتاب ص 49 — مراجعة 2-4 السؤالان 30 و32'),
('mcq', 7, 'يمثل المنحنى الآتي حركة أربعة أجسام. أي العبارات الآتية ترتبها وفق السرعة المتجهة المتوسطة ترتيبًا صحيحًا؟', null, '[{"src":"qimg/phys1/c2l4-o08-rank5.svg","alt":"منحنى (الموقع – الزمن) لأربعة أجسام M وN وO وP. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط M (برتقالي) أفقي عند 12 m. الخط N (أزرق) من (0 s، 6 m) إلى (5 s، 11 m). الخط O (أخضر) هابط من (0 s، 18 m) إلى (5 s، 13 m). الخط P (أحمر) من (0 s، 0 m) إلى (5 s، 5 m)."}]'::jsonb, '["$N = O = P$، ثم M","O، ثم M، ثم N، ثم P","N، ثم P، ثم M، ثم O","$N = P$، ثم M، ثم O"]'::jsonb, 'تحليل', 'ترتيب', 'متوسط', 'الكتاب ص 49 — مراجعة 2-4 السؤالان 30 و32'),
('essay', 1, 'يمثل المنحنى الآتي حركة أربعة أجسام A وB وC وD. (أ) احسب السرعة المتجهة المتوسطة لكل جسم. (ب) رتّب الأجسام وفق السرعة المتجهة المتوسطة من الأكبر إلى الأصغر.', null, '[{"src":"qimg/phys1/c2l4-o08-essay1.svg","alt":"منحنى (الموقع – الزمن) لأربعة أجسام A وB وC وD. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 4 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط A (أزرق) من (0 s، 0 m) إلى (4 s، 16 m). الخط B (أحمر) هابط من (0 s، 12 m) إلى (4 s، 4 m). الخط C (أخضر) من (0 s، 2 m) إلى (4 s، 10 m). الخط D (برتقالي) هابط من (0 s، 18 m) إلى (4 s، 2 m)."}]'::jsonb, null, 'تحليل', 'حساب وترتيب', 'متوسط', 'الكتاب ص 49 — مراجعة 2-4 السؤالان 30 و32'),
('essay', 2, 'يمثل المنحنى الآتي حركة أربعة أجسام Q وR وS وU. (أ) رتّب الأجسام وفق السرعة المتجهة المتوسطة من الأكبر إلى الأصغر، مشيرًا إلى أي تساوٍ. (ب) بدأ الجسم R حركته متأخرًا، وبدأ U من موقع ابتدائي أبعد عن نقطة الأصل؛ فسّر لماذا لا يؤثر ذلك في ترتيبهما.', null, '[{"src":"qimg/phys1/c2l4-o08-essay2.svg","alt":"منحنى (الموقع – الزمن) لأربعة أجسام Q وR وS وU. المحور الأفقي: الزمن t بالثانية (s)، والمحور الرأسي: الموقع d بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط Q (أزرق) من (0 s، 0 m) إلى (5 s، 20 m). الخط R (أحمر) يبدأ متأخرًا من (1 s، 0 m) إلى (6 s، 10 m). الخط S (أخضر) هابط من (0 s، 20 m) إلى (5 s، 0 m). الخط U (برتقالي) من (0 s، 6 m) إلى (6 s، 18 m)."}]'::jsonb, null, 'تحليل', 'ترتيب وتفسير', 'صعب', 'الكتاب ص 49 — مراجعة 2-4 السؤالان 30 و32'),
('essay', 3, 'صمّم منحنى (الموقع – الزمن) لثلاثة أجسام X وY وZ تبدأ جميعها من الموقع 10 m عند $t = 0$، بحيث يكون ترتيبها وفق السرعة المتجهة المتوسطة من الأكبر إلى الأصغر: X ثم Y ثم Z، على أن تكون السرعة المتجهة المتوسطة لـ Y صفرًا. (أ) اقترح قيمة عددية لميل كل خط. (ب) احسب موقع كل جسم عند $t = 4\ \text{s}$ وفق اقتراحك. (ج) صف شكل كل خط.', null, null, null, 'إبداع', 'تصميم', 'صعب', 'الكتاب ص 49 — مراجعة 2-4 السؤالان 30 و32')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
