insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الميول: A $= \frac{19 - 4}{5} = +3$، B $= \frac{5 - 0}{5} = +1$، D $= 0$، C $= \frac{6 - 16}{5} = -2$ (بوحدة m/s). الترتيب بالإشارة: $+3 > +1 > 0 > -2$.', '["","رتّب بحسب شدة الانحدار (القيمة المطلقة للميل) فأهمل أن ميل C سالب، وهذا ترتيب السرعة المتوسطة.","رتّب بحسب الموقع الابتدائي (التقاطع مع محور الموقع) لا بحسب الميل.","رتّب بحسب الموقع النهائي عند 5 s لا بحسب الميل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-18T12:34:59.272Z"}'::jsonb),
