('mcq', 4, 1, 'الميول: E $= \frac{7 - 12}{5} = -1$، G $= \frac{10 - 20}{5} = -2$، F $= \frac{3 - 18}{5} = -3$ (بوحدة m/s). وبما أن $-1 > -2 > -3$ فالترتيب E ثم G ثم F.', '["رتّب بحسب شدة الانحدار (مقدار السرعة)، لكن الميل الأشد انحدارًا هنا هو الأصغر عدديًا لأنه سالب.","","رتّب بحسب الموقع الابتدائي لكل جسم لا بحسب الميل.","رتّب بحسب الموقع النهائي لكل جسم عند 5 s لا بحسب الميل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-18T12:34:59.273Z"}'::jsonb),
