('mcq', 6, 1, 'الجسم 1: $\frac{14.0 - 2.0}{4.0} = +3.0$، الجسم 2: $\frac{4.0 - 20.0}{4.0} = -4.0$، الجسم 3: $\frac{2.0 - (-6.0)}{2.0} = +4.0$ (بوحدة m/s). الترتيب: $+4.0 > +3.0 > -4.0$.', '["قارن مقداري السرعتين (4.0 m/s) وأهمل أن سرعة الجسم 2 سالبة.","","رتّب بحسب الموقع النهائي لا بحسب السرعة المتجهة المتوسطة.","رتّب بحسب مقدار الإزاحة دون قسمتها على الفترة الزمنية ودون مراعاة الإشارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-18T12:34:59.273Z"}'::jsonb),
('mcq', 7, 3, 'الميول: N $= \frac{11 - 6}{5} = +1$، P $= \frac{5 - 0}{5} = +1$، M $= 0$، O $= \frac{13 - 18}{5} = -1$ (بوحدة m/s). إذن $N = P > M > O$.', '["قارن مقادير الميول فقط؛ لكن ميل O سالب فهو الأصغر.","رتّب بحسب ارتفاع الخطوط على الرسم (المواقع) لا بحسب ميولها.","ظن أن N أكبر من P لأن خطه أعلى، مع أن الخطين متوازيان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-18T12:34:59.273Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) A: $\frac{16 - 0}{4} = 4.0\ \text{m/s}$؛ B: $\frac{4 - 12}{4} = -2.0\ \text{m/s}$؛ C: $\frac{10 - 2}{4} = 2.0\ \text{m/s}$؛ D: $\frac{2 - 18}{4} = -4.0\ \text{m/s}$. (ب) الترتيب: A ثم C ثم B ثم D؛ لأن $+4.0 > +2.0 > -2.0 > -4.0$.', '["A = $+4.0\\ \\text{m/s}$","B = $-2.0\\ \\text{m/s}$","C = $+2.0\\ \\text{m/s}$","D = $-4.0\\ \\text{m/s}$","الترتيب A ثم C ثم B ثم D"]'::jsonb, '["A: $\\frac{16\\ \\text{m} - 0}{4\\ \\text{s}} = 4.0\\ \\text{m/s}$","B: $\\frac{4\\ \\text{m} - 12\\ \\text{m}}{4\\ \\text{s}} = -2.0\\ \\text{m/s}$","C: $\\frac{10\\ \\text{m} - 2\\ \\text{m}}{4\\ \\text{s}} = 2.0\\ \\text{m/s}$","D: $\\frac{2\\ \\text{m} - 18\\ \\text{m}}{4\\ \\text{s}} = -4.0\\ \\text{m/s}$","الترتيب بالإشارة: $A > C > B > D$"]'::jsonb, '[{"element":"حساب السرعات الأربع","marks":2},{"element":"الترتيب الصحيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة بإشاراتها وترتيب صحيح"},{"level":"2–3 درجات","description":"حسابات صحيحة مع خطأ في الترتيب بسبب الإشارة، أو خطأ في حساب واحد"},{"level":"1 درجة","description":"حساب سرعتين صحيحتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الترتيب بحسب القيمة المطلقة ($A = D$ ثم $B = C$)","إهمال إشارات B وD","الترتيب بحسب الموقع الابتدائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-18T12:34:59.273Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الميول: Q $= \frac{20 - 0}{5} = 4.0\ \text{m/s}$، R $= \frac{10 - 0}{6 - 1} = 2.0\ \text{m/s}$، U $= \frac{18 - 6}{6} = 2.0\ \text{m/s}$، S $= \frac{0 - 20}{5} = -4.0\ \text{m/s}$. الترتيب: Q ثم R وU متساويان ثم S. (ب) لأن السرعة المتجهة المتوسطة هي الميل $\frac{\Delta \boldsymbol{d}}{\Delta t}$، وهو يعتمد على التغير في الموقع والفترة الزمنية فقط، لا على لحظة البدء ولا على الموقع الابتدائي؛ وخطا R وU متوازيان فميلاهما متساويان.', '["Q = $+4.0\\ \\text{m/s}$","$R = U$ = $+2.0\\ \\text{m/s}$","S = $-4.0\\ \\text{m/s}$","الترتيب Q ثم ($R = U$) ثم S","التفسير: الميل يعتمد على التغير لا على لحظة البدء أو الموقع الابتدائي"]'::jsonb, '["Q: $\\frac{20\\ \\text{m} - 0}{5\\ \\text{s}} = 4.0\\ \\text{m/s}$","R: $\\frac{10\\ \\text{m} - 0}{6\\ \\text{s} - 1\\ \\text{s}} = 2.0\\ \\text{m/s}$","U: $\\frac{18\\ \\text{m} - 6\\ \\text{m}}{6\\ \\text{s}} = 2.0\\ \\text{m/s}$","S: $\\frac{0 - 20\\ \\text{m}}{5\\ \\text{s}} = -4.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"حساب الميول","marks":1},{"element":"الترتيب مع التساوي","marks":1},{"element":"تفسير أثر البدء المتأخر","marks":1},{"element":"تفسير أثر الموقع الابتدائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح مع التساوي وتفسير كامل"},{"level":"2–3 درجات","description":"ترتيب صحيح مع تفسير ناقص، أو خطأ في حساب ميل واحد"},{"level":"1 درجة","description":"حساب ميلين صحيحين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة إزاحة R على 6 s بدل 5 s","وضع S بعد Q مباشرة لأن مقدار ميلها 4.0 m/s","الحكم بأن U أسرع من R لأن خطه أعلى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-18T12:34:59.273Z"}'::jsonb),
('essay', 3, null::int, null, null, 'مثال لإجابة مقبولة: (أ) X: $+2.0\ \text{m/s}$، Y: 0، Z: $-1.5\ \text{m/s}$ (أي ميل موجب لـ X وميل سالب لـ Z يحقق الترتيب). (ب) X: $10 + 2.0 \times 4 = 18\ \text{m}$، Y: 10 m، Z: $10 + (-1.5) \times 4 = 4.0\ \text{m}$. (ج) الخطوط الثلاثة تبدأ من النقطة (0 s، 10 m): X خط صاعد، وY خط أفقي، وZ خط هابط. ويتحقق الترتيب لأن $+2.0 > 0 > -1.5$.', '["ميل X موجب","ميل Y صفر","ميل Z سالب (أصغر من صفر)","حساب المواقع عند 4 s صحيح وفق القيم المقترحة","وصف الخطوط: صاعد، أفقي، هابط من النقطة نفسها"]'::jsonb, '["اختيار الميول: $\\boldsymbol{\\bar{v}}_X > 0$، $\\boldsymbol{\\bar{v}}_Y = 0$، $\\boldsymbol{\\bar{v}}_Z < 0$","الموقع: $\\boldsymbol{d} = \\boldsymbol{\\bar{v}} t + \\boldsymbol{d}_i$ مع $\\boldsymbol{d}_i = 10\\ \\text{m}$ و$t = 4\\ \\text{s}$"]'::jsonb, '[{"element":"اقتراح ميول تحقق الترتيب","marks":2},{"element":"حساب المواقع","marks":1},{"element":"وصف الخطوط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ميول صحيحة تحقق الشروط مع حسابات ووصف صحيحين"},{"level":"2–3 درجات","description":"ميول صحيحة مع خطأ في الحساب أو الوصف"},{"level":"1 درجة","description":"ميل واحد فقط يحقق شرطه"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار ميل موجب لـ Z مع أن ميل Y صفر، فيجب أن يكون ميل Z سالبًا","رسم خط Y رأسيًا بدل أفقي","إهمال الموقع الابتدائي 10 m عند حساب المواقع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:59.273Z"}'::jsonb)
