('mcq', 2, 'يبيّن الجدول الآتي ميل منحنى (الموقع – الزمن) لأربعة أجسام، وكل جسم يتحرك في خط مستقيم دون أن يغيّر اتجاه حركته. ما ترتيبها وفق السرعة المتوسطة من الأكبر إلى الأصغر؟', '{"headers":["الجسم","ميل منحنى (الموقع – الزمن) (m/s)"],"rows":[["P","$+2.0$"],["Q","$-5.0$"],["R","$+4.0$"],["S","$-1.0$"]]}'::jsonb, null, '["R، ثم P، ثم S، ثم Q","S، ثم P، ثم R، ثم Q","Q، ثم S، ثم R، ثم P","Q، ثم R، ثم P، ثم S"]'::jsonb, 'تحليل', 'ترتيب', 'سهل', 'الكتاب ص 49 — مراجعة 2-4 السؤال 29 (ترتيب المنحنيات وفق السرعة المتوسطة)'),
('mcq', 3, 'يمثل المنحنى الآتي حركة أربعة أجسام E وF وG وH، وكل جسم يتحرك في خط مستقيم دون أن يغيّر اتجاه حركته. أي الأجسام لها السرعة المتوسطة نفسها؟', null, '[{"src":"qimg/phys1/c2l4-o09-equal.svg","alt":"منحنى (الموقع – الزمن) لأربعة أجسام E وF وG وH. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 18 m كل 2 m. الخط E (أزرق) من (0 s، 0 m) إلى (5 s، 10 m). الخط F (أحمر) هابط من (0 s، 16 m) إلى (5 s، 6 m). الخط G (أخضر) من (0 s، 6 m) إلى (5 s، 16 m). الخط H (برتقالي) من (0 s، 6 m) إلى (5 s، 11 m)."}]'::jsonb, '["E وF وG","E وG فقط","G وH فقط","E وF فقط"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 49 — مراجعة 2-4 السؤال 29 (ترتيب المنحنيات وفق السرعة المتوسطة)'),
('mcq', 4, 'يمثل المنحنى الآتي حركة ثلاثة أجسام K وL وM، وكل جسم يتحرك في خط مستقيم دون أن يغيّر اتجاه حركته. أي الأجسام سرعته المتوسطة أكبر؟', null, '[{"src":"qimg/phys1/c2l4-o09-steep.svg","alt":"منحنى (الموقع – الزمن) لثلاثة أجسام K وL وM. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 4 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط K (أزرق) من (0 s، 4 m) إلى (4 s، 8 m). الخط L (أحمر) هابط من (0 s، 18 m) إلى (4 s، 2 m). الخط M (أخضر) من (0 s، 0 m) إلى (4 s، 12 m)."}]'::jsonb, '["الجسم M وحده","الجسم K وحده","الجسم L وحده","M وL بالتساوي"]'::jsonb, 'تحليل', 'مقارنة', 'سهل', 'الكتاب ص 45 — السرعة المتوسطة (القيمة المطلقة للميل)'),
('mcq', 5, 'يبيّن الجدول الآتي إزاحة أربعة طلاب والفترة الزمنية لحركة كل منهم، وكل طالب يتحرك في خط مستقيم دون أن يغيّر اتجاه حركته. ما ترتيبهم وفق السرعة المتوسطة من الأصغر إلى الأكبر؟', '{"headers":["الطالب","الإزاحة (m)","الفترة الزمنية (s)"],"rows":[["A","$+30$","10"],["B","$-40$","10"],["C","$+60$","30"],["D","$-15$","3.0"]]}'::jsonb, null, '["D، ثم B، ثم C، ثم A","D، ثم A، ثم B، ثم C","C، ثم A، ثم B، ثم D","D، ثم B، ثم A، ثم C"]'::jsonb, 'تحليل', 'ترتيب', 'متوسط', 'الكتاب ص 49 — مراجعة 2-4 السؤال 29 (ترتيب المنحنيات وفق السرعة المتوسطة)'),
('mcq', 6, 'يمثل المنحنى الآتي حركة أربعة أجسام P وQ وR وS، بعضها بدأ الحركة متأخرًا، وكل جسم يتحرك في خط مستقيم دون أن يغيّر اتجاه حركته. ما ترتيبها وفق السرعة المتوسطة من الأكبر إلى الأصغر؟', null, '[{"src":"qimg/phys1/c2l4-o09-late.svg","alt":"منحنى (الموقع – الزمن) لأربعة أجسام P وQ وR وS. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 8 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط P (أزرق) من (0 s، 0 m) إلى (2 s، 10 m). الخط Q (أحمر) هابط من (1 s، 20 m) إلى (5 s، 0 m). الخط R (أخضر) من (0 s، 10 m) إلى (8 s، 18 m). الخط S (برتقالي) من (2 s، 0 m) إلى (6 s، 12 m)."}]'::jsonb, '["P وQ متساويان، ثم S، ثم R","P، ثم S، ثم R، ثم Q","Q، ثم P، ثم S، ثم R","R، ثم S، ثم P وQ متساويان"]'::jsonb, 'تحليل', 'ترتيب', 'صعب', 'الكتاب ص 49 — مراجعة 2-4 السؤال 29 (ترتيب المنحنيات وفق السرعة المتوسطة)'),
('mcq', 7, 'رتّب طالب منحنيات (الموقع – الزمن) لعدة أجسام، يتحرك كل منها في خط مستقيم دون أن يغيّر اتجاه حركته، وفق السرعة المتوسطة، فجاء ترتيبه مختلفًا عن ترتيبها وفق السرعة المتجهة المتوسطة. ما سبب هذا الاختلاف؟', null, null, '["الخطوط تبدأ من مواقع ابتدائية مختلفة على محور الموقع","بعض الخطوط أطول من غيرها على المنحنى البياني","السرعة المتوسطة تُحسب من الموقع النهائي للجسم فقط","ميل بعض الخطوط سالب، والسرعة المتوسطة تعتمد على القيمة المطلقة للميل"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 45 — السرعة المتوسطة (القيمة المطلقة للميل)'),
('essay', 1, 'يمثل المنحنى الآتي حركة أربعة أجسام A وB وC وD، وكل جسم يتحرك في خط مستقيم دون أن يغيّر اتجاه حركته. (أ) احسب ميل كل خط. (ب) رتّب المنحنيات وفق السرعة المتوسطة من الأكبر إلى الأصغر، وأشر إلى الروابط إن وجدت. (ج) رتّبها وفق السرعة المتجهة المتوسطة من الأكبر إلى الأصغر، وفسّر سبب اختلاف الترتيبين.', null, '[{"src":"qimg/phys1/c2l4-o09-essay1.svg","alt":"منحنى (الموقع – الزمن) لأربعة أجسام A وB وC وD. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من −8 إلى 16 m كل 2 m، ومحور الزمن عند الموقع 0. الخط A (أزرق) هابط من (0 s، 12 m) إلى (4 s، −4 m). الخط B (أحمر) صاعد من (0 s، −2 m) إلى (4 s، 14 m). الخط C (أخضر) هابط من (0 s، 6 m) إلى (6 s، −6 m). الخط D (برتقالي) صاعد من (0 s، −4 m) إلى (6 s، 8 m)."}]'::jsonb, null, 'تحليل', 'ترتيب', 'صعب', 'الكتاب ص 49 — مراجعة 2-4 السؤال 29 (ترتيب المنحنيات وفق السرعة المتوسطة)'),
('essay', 2, 'يبيّن الجدول الآتي مواقع ثلاث سيارات X وY وZ عند أزمنة مختلفة، وكل سيارة تتحرك في خط مستقيم دون أن تغيّر اتجاه حركتها وبسرعة منتظمة. (أ) احسب السرعة المتجهة المتوسطة لكل سيارة. (ب) رتّب السيارات وفق السرعة المتوسطة من الأكبر إلى الأصغر. (ج) هل يتطابق هذا الترتيب مع ترتيبها وفق السرعة المتجهة المتوسطة؟ وضّح.', '{"headers":["الزمن (s)","موقع X (m)","موقع Y (m)","موقع Z (m)"],"rows":[["0.0","0","40","$-10$"],["2.0","10","28","$-4$"],["4.0","20","16","2"]]}'::jsonb, null, null, 'تحليل', 'ترتيب', 'متوسط', 'الكتاب ص 49 — مراجعة 2-4 السؤال 29 (ترتيب المنحنيات وفق السرعة المتوسطة)'),
('essay', 3, 'يمثل المنحنى الآتي حركة ثلاثة أجسام M وN وO خلال 5 s، وكل جسم يتحرك في خط مستقيم دون أن يغيّر اتجاه حركته. قال طالب: «الجسم M هو الأكبر سرعة متوسطة؛ لأن خطه يقع أعلى الخطوط على المنحنى». قوّم قول الطالب، ثم رتّب الأجسام وفق السرعة المتوسطة من الأكبر إلى الأصغر مدعمًا إجابتك بالحساب.', null, '[{"src":"qimg/phys1/c2l4-o09-essay3.svg","alt":"منحنى (الموقع – الزمن) لثلاثة أجسام M وN وO. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط M (أزرق) من (0 s، 10 m) إلى (5 s، 18 m). الخط N (أحمر) هابط من (0 s، 16 m) إلى (5 s، 1 m). الخط O (أخضر) من (0 s، 0 m) إلى (5 s، 10 m)."}]'::jsonb, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 49 — مراجعة 2-4 السؤال 29 (ترتيب المنحنيات وفق السرعة المتوسطة)')
