from (values
('mcq', 1, 1, 'الميول: A $= \frac{17 - 2}{5} = +3$، B $= \frac{3 - 18}{5} = -3$، C $= \frac{9 - 4}{5} = +1$، D $= \frac{4 - 14}{5} = -2$ (بوحدة m/s). السرعة المتوسطة هي القيمة المطلقة للميل: A وB كلاهما 3 m/s، ثم D بـ 2 m/s، ثم C بـ 1 m/s.', '["رتّب الميول بإشارتها ($+3 > +1 > -2 > -3$)، وهذا ترتيب السرعة المتجهة المتوسطة لا السرعة المتوسطة.","","هذا الترتيب من الأصغر إلى الأكبر، أي عكس المطلوب.","عدّ ميل D السالب أصغر من ميل C، لكن السرعة المتوسطة تقارن القيم المطلقة: $|-2| > |+1|$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (61%)"}],"at":"2026-11-18T12:34:59.274Z"}'::jsonb),
('mcq', 2, 3, 'السرعة المتوسطة = القيمة المطلقة للميل: Q $= 5.0$، R $= 4.0$، P $= 2.0$، S $= 1.0$ (بوحدة m/s)، فالترتيب Q ثم R ثم P ثم S.', '["رتّب الميول بإشارتها، وهذا ترتيب السرعة المتجهة المتوسطة؛ أما السرعة المتوسطة فتعتمد على القيمة المطلقة فيكون Q الأكبر.","هذا الترتيب من الأصغر إلى الأكبر، أي عكس المطلوب.","قدّم الأجسام ذات الميل السالب على غيرها، لكن الإشارة تدل على الاتجاه فقط ولا أثر لها في السرعة المتوسطة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (49%)"}],"at":"2026-11-18T12:34:59.274Z"}'::jsonb),
('mcq', 3, 0, 'الميول: E $= \frac{10 - 0}{5} = +2$، F $= \frac{6 - 16}{5} = -2$، G $= \frac{16 - 6}{5} = +2$، H $= \frac{11 - 6}{5} = +1$ (بوحدة m/s). القيمة المطلقة للميل 2 m/s للأجسام E وF وG، فلها السرعة المتوسطة نفسها.', '["","استبعد F لأن ميله سالب، لكن السرعة المتوسطة هي القيمة المطلقة للميل، و$|-2| = 2$.","اعتمد على تساوي الموقع الابتدائي (6 m)، والموقع الابتدائي لا يحدد السرعة؛ فميل H يساوي 1 m/s فقط.","استبعد G لأنه يبدأ من موقع مختلف، لكن خطّي E وG متوازيان فلهما الميل نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-18T12:34:59.274Z"}'::jsonb),
('mcq', 4, 2, 'الميول: K $= \frac{8 - 4}{4} = +1$، L $= \frac{2 - 18}{4} = -4$، M $= \frac{12 - 0}{4} = +3$ (بوحدة m/s). أكبر قيمة مطلقة للميل هي 4 m/s للجسم L، فسرعته المتوسطة هي الأكبر رغم أنه يتحرك في الاتجاه السالب.', '["اختار أكبر ميل موجب، وهذا أكبر سرعة متجهة متوسطة؛ أما السرعة المتوسطة فأكبرها لأشد الخطوط انحدارًا وهو L.","اعتمد على أن K يبدأ من موقع أعلى من M، والموقع الابتدائي لا علاقة له بمقدار السرعة.","","ميل M يساوي 3 m/s والقيمة المطلقة لميل L تساوي 4 m/s، فهما غير متساويين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-18T12:34:59.275Z"}'::jsonb),
('mcq', 5, 2, 'السرعة المتوسطة $\bar{v} = \frac{|\Delta \boldsymbol{d}|}{\Delta t}$: A $= \frac{30}{10} = 3.0$، B $= \frac{40}{10} = 4.0$، C $= \frac{60}{30} = 2.0$، D $= \frac{15}{3.0} = 5.0$ (بوحدة m/s). الترتيب من الأصغر: C ثم A ثم B ثم D.', '["رتّب السرعات المتجهة المتوسطة بإشارتها ($-5.0 < -4.0 < +2.0 < +3.0$)، لا السرعات المتوسطة.","رتّب الطلاب بحسب مقدار الإزاحة فقط دون القسمة على الفترة الزمنية.","","رتّب السرعات المتوسطة من الأكبر إلى الأصغر، أي عكس المطلوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-18T12:34:59.275Z"}'::jsonb),
('mcq', 6, 0, 'الميول: P $= \frac{10 - 0}{2 - 0} = +5$، Q $= \frac{0 - 20}{5 - 1} = -5$، S $= \frac{12 - 0}{6 - 2} = +3$، R $= \frac{18 - 10}{8 - 0} = +1$ (بوحدة m/s). بالقيم المطلقة: P وQ (5 m/s) ثم S (3 m/s) ثم R (1 m/s).', '["","رتّب الميول بإشارتها، فوضع Q أخيرًا لأن ميله سالب؛ وهذا ترتيب السرعة المتجهة المتوسطة.","جعل Q أسرع من P لأن إزاحته (20 m) أكبر، لكنه استغرق 4 s بينما استغرق P ثانيتين، فميلاهما متساويان في المقدار.","هذا الترتيب من الأصغر إلى الأكبر، أي عكس المطلوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (61%)"}],"at":"2026-11-18T12:34:59.275Z"}'::jsonb),
('mcq', 7, 3, 'السرعة المتجهة المتوسطة هي الميل بإشارته، والسرعة المتوسطة هي قيمته المطلقة؛ فإذا كان لبعض الخطوط ميل سالب اختلف الترتيبان، ولو كانت جميع الميول موجبة لتطابقا.', '["الموقع الابتدائي لا يؤثر في أي من الترتيبين؛ فكلاهما يعتمد على الميل.","طول الخط المرسوم لا يحدد السرعة؛ المهم هو الميل.","السرعة المتوسطة تُحسب من الميل (الإزاحة على الفترة الزمنية) لا من الموقع النهائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.275Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) A $= \frac{-4 - 12}{4} = -4$، B $= \frac{14 - (-2)}{4} = +4$، C $= \frac{-6 - 6}{6} = -2$، D $= \frac{8 - (-4)}{6} = +2$ (بوحدة m/s). (ب) وفق السرعة المتوسطة (القيمة المطلقة للميل): A وB متساويان (4 m/s)، ثم C وD متساويان (2 m/s). (ج) وفق السرعة المتجهة المتوسطة: B ثم D ثم C ثم A، لأن $+4 > +2 > -2 > -4$. يختلف الترتيبان لأن السرعة المتجهة المتوسطة تراعي الإشارة (الاتجاه)، والسرعة المتوسطة تهملها.', '["ميول الخطوط الأربعة بإشاراتها","ترتيب السرعة المتوسطة مع رابطتين: A = B ثم C = D","ترتيب السرعة المتجهة المتوسطة: B ثم D ثم C ثم A","تفسير الاختلاف بالإشارة (الاتجاه)"]'::jsonb, '["$\\text{A}: \\frac{-4\\ \\text{m} - 12\\ \\text{m}}{4\\ \\text{s}} = -4\\ \\text{m/s}$","$\\text{B}: \\frac{14\\ \\text{m} - (-2\\ \\text{m})}{4\\ \\text{s}} = +4\\ \\text{m/s}$","$\\text{C}: \\frac{-6\\ \\text{m} - 6\\ \\text{m}}{6\\ \\text{s}} = -2\\ \\text{m/s}$","$\\text{D}: \\frac{8\\ \\text{m} - (-4\\ \\text{m})}{6\\ \\text{s}} = +2\\ \\text{m/s}$","السرعات المتوسطة: 4، 4، 2، 2 m/s"]'::jsonb, '[{"element":"حساب الميول","marks":2},{"element":"ترتيب السرعة المتوسطة والروابط","marks":1},{"element":"ترتيب السرعة المتجهة المتوسطة","marks":1},{"element":"تفسير الاختلاف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ميول صحيحة وترتيبان صحيحان مع الروابط وتفسير سليم"},{"level":"3–4 درجات","description":"خطأ في ميل واحد أو إغفال الروابط أو تفسير ناقص"},{"level":"1–2 درجة","description":"حساب بعض الميول دون ترتيب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترتيب السرعة المتوسطة بإشارة الميل","إغفال أن A وB متساويان وأن C وD متساويان","الخطأ في طرح الموقع الابتدائي السالب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-11-18T12:34:59.275Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) X: $\frac{20 - 0}{4.0} = +5.0\ \text{m/s}$؛ Y: $\frac{16 - 40}{4.0} = -6.0\ \text{m/s}$؛ Z: $\frac{2 - (-10)}{4.0} = +3.0\ \text{m/s}$. (ب) السرعات المتوسطة 5.0 و6.0 و3.0 m/s، فالترتيب: Y ثم X ثم Z. (ج) لا؛ وفق السرعة المتجهة المتوسطة يكون الترتيب X ثم Z ثم Y، لأن Y تتحرك في الاتجاه السالب فسرعتها المتجهة المتوسطة أصغر قيمة رغم أنها الأسرع.', '["السرعات المتجهة المتوسطة الثلاث بإشاراتها","ترتيب السرعة المتوسطة: Y ثم X ثم Z","ترتيب السرعة المتجهة المتوسطة: X ثم Z ثم Y","التعليل بإشارة سرعة Y"]'::jsonb, '["$\\boldsymbol{\\bar{v}}_X = \\frac{20\\ \\text{m} - 0\\ \\text{m}}{4.0\\ \\text{s} - 0.0\\ \\text{s}} = +5.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{v}}_Y = \\frac{16\\ \\text{m} - 40\\ \\text{m}}{4.0\\ \\text{s}} = -6.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{v}}_Z = \\frac{2\\ \\text{m} - (-10\\ \\text{m})}{4.0\\ \\text{s}} = +3.0\\ \\text{m/s}$","$\\bar{v}$: Y $= 6.0$، X $= 5.0$، Z $= 3.0$ (m/s)"]'::jsonb, '[{"element":"حساب السرعات المتجهة المتوسطة","marks":2},{"element":"ترتيب السرعة المتوسطة","marks":1},{"element":"المقارنة بالترتيب الآخر والتعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة بإشاراتها وترتيب صحيح ومقارنة معللة"},{"level":"2–3 درجات","description":"خطأ في إشارة أو ترتيب، أو مقارنة دون تعليل"},{"level":"1 درجة","description":"حساب سرعة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال إشارة سرعة Y عند حساب السرعة المتجهة المتوسطة","ترتيب السرعة المتوسطة بالإشارة فتأتي Y أخيرة","الخطأ في طرح الموقع السالب للسيارة Z"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.276Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح؛ فارتفاع الخط يدل على موقع الجسم لا على سرعته، والسرعة المتوسطة هي القيمة المطلقة لميل الخط. الميول: M $= \frac{18 - 10}{5} = +1.6$، N $= \frac{1 - 16}{5} = -3.0$، O $= \frac{10 - 0}{5} = +2.0$ (بوحدة m/s). السرعات المتوسطة: N = 3.0، O = 2.0، M = 1.6 m/s؛ فالترتيب N ثم O ثم M، أي إن M هو الأبطأ رغم أن خطه الأعلى، وN الأسرع رغم أن ميله سالب.', '["الحكم بخطأ القول","التعليل: ارتفاع الخط يعبر عن الموقع والسرعة يحددها الميل","حساب الميول الثلاثة","الترتيب N ثم O ثم M باستعمال القيمة المطلقة"]'::jsonb, '["$\\text{M}: \\frac{18\\ \\text{m} - 10\\ \\text{m}}{5\\ \\text{s}} = +1.6\\ \\text{m/s}$","$\\text{N}: \\frac{1\\ \\text{m} - 16\\ \\text{m}}{5\\ \\text{s}} = -3.0\\ \\text{m/s}$","$\\text{O}: \\frac{10\\ \\text{m} - 0\\ \\text{m}}{5\\ \\text{s}} = +2.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"الحكم والتعليل","marks":2},{"element":"حساب الميول","marks":2},{"element":"الترتيب الصحيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح معلل وحسابات صحيحة وترتيب صحيح"},{"level":"3–4 درجات","description":"حكم صحيح مع خطأ في ميل أو في الترتيب"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل أو حساب"},{"level":"صفر","description":"تأييد قول الطالب أو لا إجابة"}]'::jsonb, '["الخلط بين ارتفاع الخط (الموقع) وانحداره (السرعة)","استبعاد N لأن ميله سالب","قسمة الموقع النهائي على الزمن بدل الإزاحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-18T12:34:59.276Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
