from (values
('mcq', 1, 'السرعة المتجهة اللحظية لجسم متحرك هي:', null, null, '["مقدار سرعة الجسم واتجاه حركته عند لحظة زمنية تؤول إلى الصفر","الإزاحة الكلية للجسم مقسومة على الفترة الزمنية الكلية لحركته","القيمة المطلقة لميل منحنى (الموقع – الزمن) خلال الرحلة كلها","مقدار سرعة الجسم عند لحظة معينة دون تحديد اتجاه حركته"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 53 — دليل مراجعة الفصل (السرعة المتجهة اللحظية)'),
('mcq', 2, 'ما الرمز المستخدم للتعبير عن السرعة المتجهة اللحظية لجسم؟', null, null, '["$\\boldsymbol{\\bar{v}}$","$\\Delta\\boldsymbol{d}$","$\\boldsymbol{v}$","$\\boldsymbol{d}_i$"]'::jsonb, 'تذكر', 'رموز', 'سهل', 'الكتاب ص 47 — السرعة المتجهة اللحظية'),
('mcq', 3, 'يقيس نظام ساهر لمراقبة الطرق السرعة المتجهة اللحظية للسيارة. ما سبب ذلك؟', null, null, '["لأنه يحسب المسافة الكلية التي تقطعها السيارة خلال الزمن الكلي للرحلة","لأنه يحسب سرعة السيارة خلال إزاحة محددة بين موقعين متباعدين على الطريق","لأنه يحدد موقع السيارة على الطريق عند لحظة إطلاق الفلاش فقط","لأنه يحسب سرعة السيارة خلال فترة قصيرة جدًا لحظة إطلاق الفلاش مع تحديد الاتجاه"]'::jsonb, 'فهم', 'تفسير تطبيق حياتي', 'متوسط', 'الكتاب ص 45 — تطبيق الفيزياء (نظام ساهر وحساس السرعة ونظام الرصد الآلي)'),
('mcq', 4, 'قطعت سيارة إزاحة 120 km نحو الشمال خلال 2.0 h، فكانت سرعتها المتجهة المتوسطة 60 km/h نحو الشمال. ماذا نستنتج عن سرعتها المتجهة اللحظية خلال الرحلة؟', null, null, '["كانت 60 km/h نحو الشمال في كل لحظة من لحظات الرحلة","قد تكون أكبر من 60 km/h أو أقل منها في لحظات مختلفة","لا يمكن أن تتجاوز 60 km/h في أي لحظة من لحظات الرحلة","تساوي 60 km/h في كل لحظة ولكن دون اتجاه محدد"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 47 — السرعة المتجهة اللحظية'),
('mcq', 5, 'يمثل المنحنى الآتي حركة جسم على خط مستقيم، ويتكون من ثلاثة أجزاء مستقيمة. ما السرعة المتجهة اللحظية للجسم عند اللحظة 9.0 s؟', null, '[{"src":"qimg/phys1/c2l4-o10-piece.svg","alt":"منحنى (الموقع – الزمن) لجسم يتكون من ثلاثة أجزاء مستقيمة. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 10 s كل 1 s، وتدريج الموقع من 0 إلى 14 m كل 2 m. الجزء الأول صاعد من (0 s، 0 m) إلى (4 s، 12 m)، والجزء الثاني أفقي من (4 s، 12 m) إلى (8 s، 12 m)، والجزء الثالث هابط من (8 s، 12 m) إلى (10 s، 2 m)."}]'::jsonb, '["$+5.0\\ \\text{m/s}$","$-5.0\\ \\text{m/s}$","$0.78\\ \\text{m/s}$","$7.0\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'قراءة رسم بياني', 'صعب', 'الكتاب ص 47 — السرعة المتجهة اللحظية'),
('mcq', 6, 'عُلّقت كتلة بخيط وسُحبت إلى أحد الجانبين ثم تُركت تتأرجح ذهابًا وإيابًا. عند أي موقع تكون سرعتها المتجهة اللحظية صفرًا؟', null, null, '["عند أدنى نقطة في منتصف المسار","في منتصف المسافة بين القمة والقاع","عند أقصى ارتفاع في طرفي الاهتزازة","لا تكون صفرًا في أي موقع من المسار"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 47 — تجربة متجهات السرعة اللحظية'),
('mcq', 7, 'أيّ العبارات الآتية تصف سرعة متجهة لحظية؟', null, null, '["سرعة سيارة 25 m/s نحو الشمال لحظة مرورها أمام الإشارة","سرعة سيارة 25 m/s لحظة مرورها أمام الإشارة","سرعة سيارة 25 m/s نحو الشمال خلال رحلتها كلها","موقع سيارة 300 m شمال الإشارة عند اللحظة 12 s"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 53 — دليل مراجعة الفصل (السرعة المتجهة اللحظية)'),
('essay', 1, 'أجب عما يأتي: (أ) وضّح المقصود بالسرعة المتجهة اللحظية، واذكر رمزها. (ب) بماذا تختلف عن السرعة المتجهة المتوسطة $\boldsymbol{\bar{v}}$؟ (ج) يقيس نظام ساهر السرعة المتجهة اللحظية للسيارة؛ فسّر ذلك.', null, null, null, 'فهم', 'تعريف وتفسير', 'سهل', 'الكتاب ص 47 — السرعة المتجهة اللحظية'),
('essay', 2, 'يمثل المنحنى الآتي حركة جسم على خط مستقيم، ويتكون من ثلاثة أجزاء مستقيمة. (أ) أوجد السرعة المتجهة اللحظية للجسم عند كل من اللحظات 1.0 s و4.5 s و8.0 s. (ب) احسب السرعة المتجهة المتوسطة للجسم خلال الفترة من 0 s إلى 10 s. (ج) لماذا لا تساوي إجابة (ب) أيًّا من إجابات (أ)؟', null, '[{"src":"qimg/phys1/c2l4-o10-essay2.svg","alt":"منحنى (الموقع – الزمن) لجسم يتكون من ثلاثة أجزاء مستقيمة. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 10 s كل 1 s، وتدريج الموقع من 0 إلى 10 m كل 1 m. الجزء الأول صاعد من (0 s، 0 m) إلى (3 s، 9 m)، والجزء الثاني أفقي من (3 s، 9 m) إلى (6 s، 9 m)، والجزء الثالث هابط من (6 s، 9 m) إلى (10 s، 1 m)."}]'::jsonb, null, 'تحليل', 'حساب من رسم بياني', 'صعب', 'الكتاب ص 47 — السرعة المتجهة اللحظية'),
('essay', 3, 'قال طالب: «إذا علمت موقع سيارة عند نقطتين على طريق مستقيم، والزمن الذي استغرقته للانتقال من الأولى إلى الثانية، أستطيع أن أحدد سرعتها المتجهة اللحظية في أي لحظة بينهما». قوّم قول الطالب، وبيّن ما الذي يمكن تحديده فعلًا من هذه المعلومات، ومتى يصح قوله.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 54 — التقويم السؤال 42')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
