from (values
('mcq', 1, 0, 'السرعة المتجهة اللحظية هي مقدار سرعة الجسم واتجاه حركته عند لحظة زمنية تؤول إلى الصفر، أي عند لحظة بعينها لا خلال فترة زمنية.', '["","هذا تعريف السرعة المتجهة المتوسطة لا اللحظية.","هذه السرعة المتوسطة، وهي كمية عددية تصف الرحلة كلها لا لحظة بعينها.","أهمل الاتجاه؛ والسرعة المتجهة اللحظية كمية متجهة لها مقدار واتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:34:59.276Z"}'::jsonb),
('mcq', 2, 2, 'يُستخدم مصطلح السرعة المتجهة للتعبير عن السرعة المتجهة اللحظية، ويُرمز لها بالرمز $\boldsymbol{v}$ دون شرطة، تمييزًا لها عن السرعة المتجهة المتوسطة $\boldsymbol{\bar{v}}$.', '["الرمز ذو الشرطة يدل على السرعة المتجهة المتوسطة.","هذا رمز الإزاحة، أي التغير في الموقع.","","هذا رمز الموقع الابتدائي للجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:34:59.276Z"}'::jsonb),
('mcq', 3, 3, 'السرعة المتجهة اللحظية تصف الحركة عند لحظة تؤول فترتها الزمنية إلى الصفر، ونظام ساهر يحسب السرعة خلال فترة قصيرة جدًا هي لحظة إطلاق الفلاش مع تحديد الاتجاه.', '["هذا ما يفعله حساس السرعة AVG، وهو يقيس السرعة المتوسطة.","هذا ما يفعله نظام الرصد الآلي، وهو يقيس السرعة المتجهة المتوسطة.","تحديد الموقع وحده لا يعطي السرعة؛ فالسرعة تتطلب تغير الموقع خلال زمن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.276Z"}'::jsonb),
('mcq', 4, 1, 'السرعة المتجهة المتوسطة تُحسب من الإزاحة الكلية والفترة الزمنية الكلية فقط، ولا تعبر عما حدث خلال الفترة؛ فربما بقيت السرعة ثابتة أو زادت أو نقصت أو توقفت السيارة، لذا قد تكون السرعة المتجهة اللحظية أكبر من 60 km/h أو أقل منها في لحظات مختلفة.', '["السرعة المتجهة المتوسطة لا تخبرنا بما حدث خلال الفترة؛ فقد تكون السيارة توقفت أو تسارعت.","","إذا توقفت السيارة أو أبطأت في بعض اللحظات فلا بد أن تتجاوز 60 km/h في لحظات أخرى.","السرعة المتجهة اللحظية كمية متجهة لها اتجاه، والمعطيات لا تدل على ثباتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.277Z"}'::jsonb),
('mcq', 5, 1, 'من 8 s إلى 10 s يتحرك الجسم بسرعة متجهة ثابتة لأن هذا الجزء خط مستقيم، فسرعته المتجهة اللحظية عند أي لحظة فيه تساوي ميله: $\frac{2 - 12}{10 - 8} = -5.0\ \text{m/s}$.', '["أهمل الإشارة؛ فالموقع يتناقص في الجزء الأخير، فالجسم يتحرك في الاتجاه السالب.","","قسم الموقع عند 9.0 s على الزمن ($\\frac{7.0}{9.0}$)، وهذه السرعة المتجهة المتوسطة من 0 s إلى 9.0 s لا اللحظية.","هذه قراءة موقع الجسم (7.0 m) عند 9.0 s وليست سرعته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:34:59.277Z"}'::jsonb),
('mcq', 6, 2, 'عند طرفي الاهتزازة تتوقف الكتلة لحظة ثم تعكس اتجاه حركتها، فسرعتها المتجهة اللحظية عندئذ صفر، بينما تكون أكبر ما يمكن عند أدنى نقطة.', '["عند أدنى نقطة تكون السرعة أكبر ما يمكن لا صفرًا.","الكتلة تتحرك عند هذا الموقع فسرعتها لا تساوي صفرًا.","","عند طرفي الاهتزازة تتوقف الكتلة لحظيًا قبل أن تعكس اتجاه حركتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.277Z"}'::jsonb),
('mcq', 7, 0, 'السرعة المتجهة اللحظية تحتاج إلى مقدار واتجاه عند لحظة بعينها، وهذا متحقق في عبارة «25 m/s نحو الشمال لحظة مرورها أمام الإشارة».', '["","العبارة تخلو من الاتجاه، فهي تصف مقدار السرعة فقط.","السرعة المحسوبة خلال الرحلة كلها سرعة متجهة متوسطة لا لحظية.","هذا موقع لحظي للسيارة وليس سرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-18T12:34:59.277Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) السرعة المتجهة اللحظية هي مقدار سرعة الجسم واتجاه حركته عند لحظة زمنية تؤول إلى الصفر، ويُرمز لها بالرمز $\boldsymbol{v}$. (ب) السرعة المتجهة المتوسطة تُحسب بقسمة الإزاحة الكلية على الفترة الزمنية كلها، فلا تخبرنا بما حدث خلال الفترة، أما اللحظية فتصف الحركة عند لحظة بعينها. (ج) لأن نظام ساهر يحسب سرعة السيارة خلال فترة قصيرة جدًا هي لحظة إطلاق الفلاش، مع تحديد الاتجاه.', '["التعريف: المقدار والاتجاه عند لحظة تؤول إلى الصفر","الرمز $\\boldsymbol{v}$","الفرق: المتوسطة لفترة كاملة واللحظية للحظة بعينها","تفسير ساهر: فترة قصيرة جدًا مع تحديد الاتجاه"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف والرمز","marks":2},{"element":"الفرق بين السرعتين","marks":1},{"element":"تفسير نظام ساهر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح بالمقدار والاتجاه ورمز صحيح وفرق واضح وتفسير سليم"},{"level":"2–3 درجات","description":"إغفال الاتجاه أو الرمز أو نقص في الفرق أو التفسير"},{"level":"1 درجة","description":"تعريف ناقص فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال الاتجاه في التعريف","استعمال الرمز $\\boldsymbol{\\bar{v}}$ للسرعة اللحظية","الخلط بين نظام ساهر ونظام الرصد الآلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.277Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) كل جزء خط مستقيم، فالسرعة المتجهة اللحظية عند أي لحظة فيه تساوي ميله: عند 1.0 s: $\frac{9 - 0}{3 - 0} = +3.0\ \text{m/s}$؛ عند 4.5 s: الجزء أفقي فالسرعة صفر؛ عند 8.0 s: $\frac{1 - 9}{10 - 6} = -2.0\ \text{m/s}$. (ب) $\boldsymbol{\bar{v}} = \frac{1 - 0}{10 - 0} = +0.10\ \text{m/s}$. (ج) لأن السرعة المتجهة المتوسطة تعتمد على الموقعين الابتدائي والنهائي والفترة الكلية فقط، ولا تعبر عما حدث خلال الفترة؛ فالجسم تحرك في الاتجاه الموجب ثم توقف ثم عاد في الاتجاه السالب، فتغيرت سرعته اللحظية.', '["عند 1.0 s: $+3.0\\ \\text{m/s}$","عند 4.5 s: صفر","عند 8.0 s: $-2.0\\ \\text{m/s}$","السرعة المتجهة المتوسطة $+0.10\\ \\text{m/s}$","التعليل: المتوسطة لا تصف ما حدث خلال الفترة"]'::jsonb, '["$\\boldsymbol{v}(1.0\\ \\text{s}) = \\frac{9\\ \\text{m} - 0\\ \\text{m}}{3\\ \\text{s} - 0\\ \\text{s}} = +3.0\\ \\text{m/s}$","$\\boldsymbol{v}(4.5\\ \\text{s}) = \\frac{9\\ \\text{m} - 9\\ \\text{m}}{6\\ \\text{s} - 3\\ \\text{s}} = 0$","$\\boldsymbol{v}(8.0\\ \\text{s}) = \\frac{1\\ \\text{m} - 9\\ \\text{m}}{10\\ \\text{s} - 6\\ \\text{s}} = -2.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{v}} = \\frac{1\\ \\text{m} - 0\\ \\text{m}}{10\\ \\text{s} - 0\\ \\text{s}} = +0.10\\ \\text{m/s}$"]'::jsonb, '[{"element":"السرعات اللحظية الثلاث","marks":3},{"element":"السرعة المتجهة المتوسطة","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع القيم صحيحة بإشاراتها والتعليل سليم"},{"level":"3–4 درجات","description":"خطأ في قيمة أو إشارة واحدة أو تعليل ناقص"},{"level":"1–2 درجة","description":"قيمة أو قيمتان صحيحتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الموقع عند اللحظة على الزمن بدل حساب ميل الجزء","إهمال إشارة السرعة في الجزء الثالث","حساب المتوسطة من المسافة الكلية 17 m بدل الإزاحة 1 m"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:34:59.278Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القول غير صحيح في عمومه؛ فهذه المعلومات تكفي لحساب السرعة المتجهة المتوسطة فقط $\boldsymbol{\bar{v}} = \frac{\Delta \boldsymbol{d}}{\Delta t}$، لأنها لا تخبرنا بما حدث بين النقطتين: فربما بقيت السرعة ثابتة أو زادت أو نقصت، أو توقفت السيارة أو غيرت اتجاهها. ويصح قول الطالب فقط إذا كانت السيارة تتحرك حركة منتظمة (سرعة متجهة ثابتة)، لأن السرعة المتجهة اللحظية عندئذ تساوي السرعة المتجهة المتوسطة في كل لحظة.', '["الحكم بأن القول غير صحيح في عمومه","ما يمكن تحديده: السرعة المتجهة المتوسطة","التعليل: لا نعرف ما حدث بين النقطتين","الحالة التي يصح فيها: الحركة المنتظمة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"تحديد السرعة المتجهة المتوسطة","marks":1},{"element":"التعليل","marks":1},{"element":"حالة الحركة المنتظمة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتعليل سليم وتحديد الحالة الخاصة"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ناقص أو إغفال الحالة الخاصة"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"تأييد القول مطلقًا أو لا إجابة"}]'::jsonb, '["الظن أن السرعة المتجهة المتوسطة تساوي اللحظية دائمًا","إغفال إمكانية توقف السيارة أو تغير اتجاهها","عدم ذكر الحالة التي يصح فيها القول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.278Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O10') and x.type = v.type and x.number = v.number
