select (select id from public.objectives where code = 'P1-C2-L4-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تكون حركة جسم ما منتظمة عندما:', null, null, '["يبقى مقدار سرعته ثابتًا ولو تغير اتجاه حركته","يتحرك في خط مستقيم ولو تغير مقدار سرعته","تبقى سرعته المتجهة ثابتة مقدارًا واتجاهًا","تكون إزاحته موجبة في جميع الفترات الزمنية"]'::jsonb, 'فهم', 'شرط', 'سهل', 'الكتاب ص 47 — الحركة المنتظمة (السرعة المتجهة الثابتة)'),
('mcq', 2, 'يبيّن المخطط التوضيحي الآتي نموذج الجسيم النقطي لحركة أربعة أجسام A وB وC وD، والتُقطت الصور على فترات زمنية متساوية. أي الأجسام حركته منتظمة خلال الفترة كلها؟', null, '[{"src":"qimg/phys1/c2l4-o11-dots.svg","alt":"مخطط توضيحي للحركة من أربعة صفوف أفقية من النقاط، لكل صف ست صور ملتقطة على فترات زمنية متساوية، والحركة نحو اليمين في اتجاه المحور d. الصف A: نقاط تفصل بينها مسافات متساوية. الصف B: المسافات بين النقاط تتزايد من اليسار إلى اليمين. الصف C: المسافات بين النقاط تتناقص من اليسار إلى اليمين. الصف D: ثلاث مسافات متساوية بين النقاط الأربع الأولى، ثم تقع النقطتان الأخيرتان فوق النقطة الرابعة تمامًا."}]'::jsonb, '["الجسم A","الجسم B","الجسم C","الجسم D"]'::jsonb, 'فهم', 'قراءة مخطط', 'متوسط', 'الكتاب ص 47 — الحركة المنتظمة (السرعة المتجهة الثابتة)'),
('mcq', 3, 'يبيّن الشكل الآتي أربعة منحنيات (الموقع – الزمن) مرقمة. أيّها يمثل حركة منتظمة؟', null, '[{"src":"qimg/phys1/c2l4-o11-panels.svg","alt":"أربعة منحنيات صغيرة (الموقع d – الزمن t) مرقمة. المنحنى (1): خط مستقيم واحد هابط من أعلى اليسار إلى أسفل اليمين. المنحنى (2): منحنى صاعد يزداد انحداره مع الزمن. المنحنى (3): خط صاعد، ثم جزء أفقي، ثم خط صاعد مرة أخرى. المنحنى (4): خط صاعد حتى منتصف الزمن، ثم خط هابط."}]'::jsonb, '["المنحنى (2)","المنحنى (1)","المنحنى (3)","المنحنى (4)"]'::jsonb, 'فهم', 'قراءة رسم بياني', 'صعب', 'الكتاب ص 47 — الحركة المنتظمة (السرعة المتجهة الثابتة)'),
('mcq', 4, 'إذا كانت السرعة المتجهة اللحظية لجسم ثابتة خلال فترة زمنية، فإن سرعته المتجهة المتوسطة خلال الفترة نفسها:', null, null, '["تساوي نصف سرعته المتجهة اللحظية","تساوي صفرًا لأن السرعة لم تتغير","تكون أكبر من سرعته المتجهة اللحظية","تساوي سرعته المتجهة اللحظية"]'::jsonb, 'فهم', 'علاقة', 'سهل', 'الكتاب ص 47 — الحركة المنتظمة (السرعة المتجهة الثابتة)'),
('mcq', 5, 'يبيّن الجدول الآتي مواقع أربعة أجسام A وB وC وD عند أزمنة متساوية التباعد. أي الأجسام حركته منتظمة خلال الفترة من 0 s إلى 4 s؟', '{"headers":["الزمن (s)","موقع A (m)","موقع B (m)","موقع C (m)","موقع D (m)"],"rows":[["0","0","0","0","20"],["1","4","2","5","15"],["2","8","8","10","10"],["3","12","18","10","5"],["4","16","32","10","0"]]}'::jsonb, null, '["A وD","A فقط","A وC","A وB وD"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 47 — الحركة المنتظمة (السرعة المتجهة الثابتة)'),
('mcq', 6, 'تسير سيارة على مسار دائري بمقدار سرعة ثابت 20 m/s. هل حركتها منتظمة؟', null, null, '["نعم؛ لأن مقدار سرعتها ثابت طوال الحركة","نعم؛ لأنها تقطع مسافات متساوية في أزمنة متساوية","لا؛ لأن مقدار سرعتها يتغير باستمرار","لا؛ لأن اتجاه سرعتها المتجهة يتغير باستمرار"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 31 — السرعة المنتظمة (ثابتة مقدارًا واتجاهًا)'),
('mcq', 7, 'غادر شخصان المنزل في الوقت نفسه، أحدهما يعدو والآخر يمشي، وتحركا في الاتجاه نفسه بسرعتين متجهتين منتظمتين. كيف يبدو منحنى (الموقع – الزمن) لكل منهما؟', null, null, '["خطان مستقيمان متوازيان لأن حركتيهما منتظمتان","خطان مستقيمان، وميل خط العدّاء أكبر من ميل خط الماشي","منحنيان يزداد ميل كل منهما مع مرور الزمن","خط مستقيم مائل للعدّاء وخط أفقي للماشي"]'::jsonb, 'فهم', 'وصف رسم بياني', 'متوسط', 'الكتاب ص 54 — التقويم السؤال 40 (المشي والركض)'),
('essay', 1, 'وضّح متى تكون حركة جسم ما منتظمة، ثم بيّن: (أ) كيف تتعرف الحركة المنتظمة من المخطط التوضيحي للحركة. (ب) كيف تتعرفها من منحنى (الموقع – الزمن). (ج) العلاقة بين السرعة المتجهة اللحظية والسرعة المتجهة المتوسطة في هذه الحركة.', null, null, null, 'فهم', 'توضيح', 'سهل', 'الكتاب ص 47 — الحركة المنتظمة (السرعة المتجهة الثابتة)'),
('essay', 2, 'وقف طلاب في صف واحد على طريق مستقيم، والمسافة بين كل طالبين 25 m، وسجّلوا الزمن الذي تمر فيه كل من سيارتين X وY أمام كل منهم كما في الجدول الآتي. (أ) احسب السرعة المتجهة المتوسطة لكل سيارة في كل فترة من الفترات الأربع. (ب) أي السيارتين حركتها منتظمة؟ علّل. (ج) صف حركة السيارة الأخرى.', '{"headers":["الموقع (m)","زمن مرور X (s)","زمن مرور Y (s)"],"rows":[["0","0.00","0.0"],["25","1.25","1.0"],["50","2.50","2.2"],["75","3.75","3.6"],["100","5.00","5.2"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 56 — التقويم السؤال 57 والجدول 2-3'),
('essay', 3, 'تحركت كرة على أرض مستوية نحو الشرق بسرعة 3.0 m/s، فاصطدمت بجدار وارتدت لتتحرك نحو الغرب بسرعة 3.0 m/s. قال طالب: «حركة الكرة منتظمة طوال الوقت؛ لأن مقدار سرعتها لم يتغير». قوّم قول الطالب، ثم صف شكل منحنى (الموقع – الزمن) لحركة الكرة إذا كان الاتجاه الموجب نحو الشرق.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 31 — السرعة المنتظمة (ثابتة مقدارًا واتجاهًا)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
