select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'إذا تحرك الجسم بسرعة متجهة ثابتة (ثابتة مقدارًا واتجاهًا) نقول إن سرعته منتظمة، لذا تكون حركته منتظمة.', '["تغير الاتجاه يعني تغير السرعة المتجهة، فلا تكون الحركة منتظمة.","تغير مقدار السرعة يعني أن السرعة المتجهة غير ثابتة.","","إشارة الإزاحة تدل على الاتجاه فقط؛ فقد تكون الحركة منتظمة في الاتجاه السالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.278Z"}'::jsonb),
('mcq', 2, 0, 'في الحركة المنتظمة يقطع الجسم إزاحات متساوية في فترات زمنية متساوية، فتكون المسافات بين النقاط المتتالية متساوية طوال الحركة، وهذا متحقق في الجسم A وحده.', '["","المسافات بين نقاطه تتزايد، أي إن سرعته تزداد فليست ثابتة.","المسافات بين نقاطه تتناقص، أي إن سرعته تقل فليست ثابتة.","تحرك بانتظام في البداية ثم توقف (تراكبت نقاطه الأخيرة)، فتغيرت سرعته خلال الفترة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-18T12:34:59.278Z"}'::jsonb),
('mcq', 3, 1, 'الحركة المنتظمة يمثلها خط مستقيم واحد ميله ثابت، والمنحنى (1) خط مستقيم هابط ميله ثابت؛ فالجسم يتحرك في الاتجاه السالب بسرعة متجهة ثابتة، والحركة في الاتجاه السالب قد تكون منتظمة أيضًا.', '["ميله يزداد مع الزمن، أي إن سرعة الجسم تزداد فليست ثابتة.","","فيه جزء أفقي يكون الجسم عنده ساكنًا، فالسرعة المتجهة تتغير بين الأجزاء.","إشارة ميله تتغير، أي إن الجسم يعكس اتجاه حركته فتتغير سرعته المتجهة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.278Z"}'::jsonb),
('mcq', 4, 3, 'إذا كانت السرعة المتجهة اللحظية ثابتة فإنها تكون مساوية للسرعة المتجهة المتوسطة، وعندئذ تكون الحركة منتظمة.', '["لا يوجد ما يجعلها نصفها؛ فالإزاحة على الزمن تساوي السرعة الثابتة نفسها.","ثبات السرعة لا يعني انعدامها؛ فالجسم يتحرك ويقطع إزاحة.","مع ثبات السرعة لا يمكن أن يكون المتوسط أكبر من القيمة الثابتة نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.279Z"}'::jsonb),
('mcq', 5, 0, 'إزاحات A في كل ثانية: $+4\ \text{m}$ دائمًا، وإزاحات D: $-5\ \text{m}$ دائمًا؛ فسرعة كل منهما المتجهة ثابتة ($+4$ و$-5$ بوحدة m/s). أما B فإزاحاته تتزايد، وC يتوقف بعد 2 s.', '["","استبعد D لأنه يتحرك في الاتجاه السالب، لكن إزاحاته متساوية ($-5\\ \\text{m}$ كل ثانية) فسرعته المتجهة ثابتة.","C يقطع 5 m في كل ثانية من الثانيتين الأوليين ثم يتوقف، فسرعته تتغير.","B إزاحاته 2 و6 و10 و14 m في الثواني المتتالية، أي إن سرعته تزداد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-18T12:34:59.279Z"}'::jsonb),
('mcq', 6, 3, 'الحركة المنتظمة تتطلب سرعة متجهة ثابتة مقدارًا واتجاهًا. على المسار الدائري يبقى المقدار ثابتًا لكن الاتجاه يتغير باستمرار، فالسرعة المتجهة غير ثابتة والحركة غير منتظمة.', '["ثبات المقدار لا يكفي؛ فالحركة المنتظمة تتطلب ثبات الاتجاه أيضًا.","تساوي المسافات يدل على ثبات المقدار فقط، أما الاتجاه فيتغير على المسار الدائري.","مقدار السرعة ثابت 20 m/s كما في نص السؤال؛ الذي يتغير هو الاتجاه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.279Z"}'::jsonb),
('mcq', 7, 1, 'كل حركة منتظمة يمثلها خط مستقيم ميله ثابت يساوي السرعة المتجهة؛ ولأن العدّاء أسرع يكون خطه أشد انحدارًا، ويبدأ الخطان من النقطة نفسها لأنهما غادرا المنزل معًا.', '["انتظام الحركة يجعل كل خط مستقيمًا، لكن اختلاف السرعتين يجعل الميلين مختلفين.","","ازدياد الميل يعني ازدياد السرعة، والسرعتان منتظمتان.","الخط الأفقي يمثل جسمًا ساكنًا، والماشي يتحرك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.279Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تكون حركة الجسم منتظمة إذا تحرك بسرعة متجهة ثابتة، أي ثابتة مقدارًا واتجاهًا. (أ) في المخطط التوضيحي للحركة تكون المسافات بين النقاط المتتالية متساوية وفي الاتجاه نفسه. (ب) يكون منحنى (الموقع – الزمن) خطًا مستقيمًا واحدًا ميله ثابت. (ج) تكون السرعة المتجهة اللحظية ثابتة ومساوية للسرعة المتجهة المتوسطة.', '["الشرط: سرعة متجهة ثابتة مقدارًا واتجاهًا","المخطط التوضيحي: مسافات متساوية بين النقاط","المنحنى: خط مستقيم ميله ثابت","السرعة اللحظية = السرعة المتجهة المتوسطة"]'::jsonb, '[]'::jsonb, '[{"element":"الشرط","marks":1},{"element":"المخطط التوضيحي","marks":1},{"element":"منحنى (الموقع – الزمن)","marks":1},{"element":"العلاقة بين السرعتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"إغفال الاتجاه في الشرط أو عنصر آخر"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بثبات مقدار السرعة دون الاتجاه","وصف المنحنى بأنه خط أفقي","الظن أن الحركة المنتظمة لا تكون في الاتجاه السالب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.279Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) X: $\frac{25}{1.25} = 20\ \text{m/s}$ في الفترات الأربع جميعها. Y: $\frac{25}{1.0} = 25$، $\frac{25}{1.2} \approx 21$، $\frac{25}{1.4} \approx 18$، $\frac{25}{1.6} \approx 16$ (بوحدة m/s). (ب) حركة X منتظمة؛ لأنها تقطع إزاحات متساوية (25 m) في فترات زمنية متساوية (1.25 s)، فسرعتها المتجهة ثابتة. (ج) Y تقطع الإزاحة نفسها في فترات تزداد، فسرعتها تتناقص، أي إنها تتباطأ وحركتها غير منتظمة.', '["سرعة X في كل فترة 20 m/s","سرعات Y: 25، 21، 18، 16 m/s","X حركتها منتظمة مع التعليل","Y تتباطأ وحركتها غير منتظمة"]'::jsonb, '["فترات X: $1.25 - 0.00 = 2.50 - 1.25 = \\dots = 1.25\\ \\text{s}$","$\\boldsymbol{\\bar{v}}_X = \\frac{25\\ \\text{m}}{1.25\\ \\text{s}} = 20\\ \\text{m/s}$","فترات Y: 1.0، 1.2، 1.4، 1.6 s","$\\boldsymbol{\\bar{v}}_Y$: $\\frac{25\\ \\text{m}}{1.0\\ \\text{s}} = 25$، $\\frac{25\\ \\text{m}}{1.2\\ \\text{s}} \\approx 21$، $\\frac{25\\ \\text{m}}{1.4\\ \\text{s}} \\approx 18$، $\\frac{25\\ \\text{m}}{1.6\\ \\text{s}} \\approx 16\\ \\text{m/s}$"]'::jsonb, '[{"element":"حساب سرعات X","marks":1},{"element":"حساب سرعات Y","marks":2},{"element":"تحديد الحركة المنتظمة وتعليلها","marks":1},{"element":"وصف حركة Y","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة وحكم معلل ووصف صحيح"},{"level":"3–4 درجات","description":"خطأ حسابي واحد أو تعليل ناقص"},{"level":"1–2 درجة","description":"حساب جزئي دون حكم صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الموقع على الزمن الكلي بدل الإزاحة على الفترة","الحكم بانتظام Y لأن المسافات بين الطلاب متساوية","وصف Y بأنها تتسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.279Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح؛ فالحركة المنتظمة تتطلب ثبات السرعة المتجهة مقدارًا واتجاهًا، والكرة غيّرت اتجاه حركتها فتغيرت سرعتها المتجهة من $+3.0\ \text{m/s}$ إلى $-3.0\ \text{m/s}$. لكن حركتها منتظمة في كل جزء على حدة (قبل الاصطدام وبعده). منحنى (الموقع – الزمن): خط مستقيم صاعد ميله $+3.0\ \text{m/s}$ حتى لحظة الاصطدام، ثم خط مستقيم هابط ميله $-3.0\ \text{m/s}$؛ أي إن المنحنى كله ليس خطًا مستقيمًا واحدًا.', '["الحكم بخطأ القول","التعليل بتغير الاتجاه وتغير السرعة المتجهة","كل جزء على حدة حركة منتظمة","وصف المنحنى: خط صاعد ميله موجب ثم خط هابط ميله سالب"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم والتعليل","marks":2},{"element":"انتظام كل جزء","marks":1},{"element":"وصف المنحنى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح معلل ووصف صحيح للمنحنى"},{"level":"2–3 درجات","description":"حكم صحيح مع وصف ناقص للمنحنى أو تعليل ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"تأييد القول أو لا إجابة"}]'::jsonb, '["الاكتفاء بثبات المقدار للحكم بالانتظام","رسم المنحنى خطًا مستقيمًا واحدًا","إعطاء الجزأين الميل نفسه بالإشارة نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.280Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O11') and x.type = v.type and x.number = v.number
