from (values
('mcq', 1, 'ما معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة؟', null, null, '["$\\boldsymbol{d} = \\boldsymbol{d}_i t + \\boldsymbol{\\bar{v}}$","$\\boldsymbol{d} = \\frac{\\boldsymbol{\\bar{v}}}{t} + \\boldsymbol{d}_i$","$\\boldsymbol{d} = \\boldsymbol{\\bar{v}}t - \\boldsymbol{d}_i$","$\\boldsymbol{d} = \\boldsymbol{\\bar{v}}t + \\boldsymbol{d}_i$"]'::jsonb, 'تذكر', 'معادلة', 'سهل', 'الكتاب ص 48 — معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة'),
('mcq', 2, 'عند مقارنة معادلة الخط المستقيم $y = mx + b$ بمنحنى (الموقع – الزمن) لجسم يتحرك حركة منتظمة، أيّ الكميات يقابل الميل $m$؟', null, null, '["الموقع الابتدائي للجسم $\\boldsymbol{d}_i$","السرعة المتجهة المتوسطة $\\boldsymbol{\\bar{v}}$","الزمن المنقضي منذ بدء التوقيت $t$","موقع الجسم $\\boldsymbol{d}$ عند أي لحظة"]'::jsonb, 'فهم', 'ربط', 'سهل', 'الكتاب ص 47–48 — استخدام المعادلات والجدول 2-2'),
('mcq', 3, 'يمثل المنحنى الآتي حركة منتظمة لجسم على خط مستقيم. أيّ المعادلات الآتية تصف هذه الحركة؟', null, '[{"src":"qimg/phys1/c2l4-o12-line1.svg","alt":"منحنى (الموقع – الزمن) لجسم: خط مستقيم واحد. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 18 m كل 2 m. يمر الخط بالنقطتين (0 s، 6 m) و(5 s، 16 m)."}]'::jsonb, '["$\\boldsymbol{d} = (6.0\\ \\text{m/s})t + 2.0\\ \\text{m}$","$\\boldsymbol{d} = (3.2\\ \\text{m/s})t + 6.0\\ \\text{m}$","$\\boldsymbol{d} = (2.0\\ \\text{m/s})t + 6.0\\ \\text{m}$","$\\boldsymbol{d} = (2.0\\ \\text{m/s})t + 16\\ \\text{m}$"]'::jsonb, 'تطبيق', 'كتابة معادلة من رسم بياني', 'متوسط', 'الكتاب ص 48 — معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة'),
('mcq', 4, 'يمثل المنحنى الآتي حركة قارب يتحرك بسرعة منتظمة نحو نقطة الأصل ثم يتجاوزها. أيّ المعادلات الآتية تعبّر عن موقع القارب بدلالة الزمن؟', null, '[{"src":"qimg/phys1/c2l4-o12-line2.svg","alt":"منحنى (الموقع – الزمن) لجسم: خط مستقيم واحد هابط. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من −6 إلى 16 m كل 2 m، ومحور الزمن عند الموقع 0. يمر الخط بالنقطتين (0 s، 15 m) و(5 s، −5 m)، ويقطع محور الزمن بين 3 s و4 s."}]'::jsonb, '["$\\boldsymbol{d} = (-4.0\\ \\text{m/s})t + 15\\ \\text{m}$","$\\boldsymbol{d} = (4.0\\ \\text{m/s})t + 15\\ \\text{m}$","$\\boldsymbol{d} = (-4.0\\ \\text{m/s})t - 5.0\\ \\text{m}$","$\\boldsymbol{d} = (-1.0\\ \\text{m/s})t + 15\\ \\text{m}$"]'::jsonb, 'تطبيق', 'كتابة معادلة من رسم بياني', 'صعب', 'الكتاب ص 48 — معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة'),
('mcq', 5, 'في معادلة الحركة المنتظمة $\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i$، ما وحدة الحد $\boldsymbol{\bar{v}}t$؟', null, null, '["m/s، وهي وحدة السرعة","s، وهي وحدة الزمن","m، وهي وحدة الموقع","m/s²، وهي وحدة التسارع"]'::jsonb, 'فهم', 'تحليل وحدات', 'متوسط', 'الكتاب ص 48 — معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة'),
('mcq', 6, 'يتحرك عدّاء بسرعة متجهة منتظمة مقدارها 4.0 m/s في الاتجاه السالب، وعند بدء التوقيت كان عند الموقع 50.0 m. أيّ المعادلات الآتية تصف حركته؟', null, null, '["$\\boldsymbol{d} = (4.0\\ \\text{m/s})t + 50.0\\ \\text{m}$","$\\boldsymbol{d} = (-4.0\\ \\text{m/s})t + 50.0\\ \\text{m}$","$\\boldsymbol{d} = (50.0\\ \\text{m/s})t - 4.0\\ \\text{m}$","$\\boldsymbol{d} = (-4.0\\ \\text{m/s})t - 50.0\\ \\text{m}$"]'::jsonb, 'تطبيق', 'كتابة معادلة', 'متوسط', 'الكتاب ص 48 — معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة'),
('mcq', 7, 'يبيّن الشكل الآتي نموذج الجسيم النقطي لجسم يتحرك نحو اليمين (الاتجاه الموجب) حركة منتظمة، والفترة الزمنية بين كل نقطتين متتاليتين 1.0 s، والتُقطت الصورة الأولى (أقصى اليسار) عند اللحظة 0 s. أيّ المعادلات الآتية تصف حركته؟', null, '[{"src":"qimg/phys1/c2l4-o12-dots.svg","alt":"نموذج الجسيم النقطي: خمس نقاط فوق محور الموقع d بالمتر، وهو مدرج من 0 إلى 16 m كل 1 m، ومكتوب أعلاه Δt = 1.0 s. تقع النقاط عند المواقع 2 و5 و8 و11 و14 m."}]'::jsonb, '["$\\boldsymbol{d} = (3.0\\ \\text{m/s})t + 2.0\\ \\text{m}$","$\\boldsymbol{d} = (3.0\\ \\text{m/s})t$","$\\boldsymbol{d} = (2.0\\ \\text{m/s})t + 3.0\\ \\text{m}$","$\\boldsymbol{d} = (2.8\\ \\text{m/s})t + 2.0\\ \\text{m}$"]'::jsonb, 'تطبيق', 'كتابة معادلة من نموذج', 'صعب', 'الكتاب ص 55 — التقويم السؤال 50 (كتابة معادلة الحركة من نموذج الجسيم النقطي)'),
('essay', 1, 'أجب عما يأتي: (أ) اكتب معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة، وبيّن دلالة كل رمز فيها. (ب) وضّح كيف تنتج هذه المعادلة من مقارنة منحنى (الموقع – الزمن) بمعادلة الخط المستقيم $y = mx + b$. (ج) تحقق من تطابق الوحدات في طرفيها.', null, null, null, 'فهم', 'توضيح معادلة', 'سهل', 'الكتاب ص 47–48 — استخدام المعادلات والجدول 2-2'),
('essay', 2, 'يمثل المنحنى الآتي حركة منتظمة لجسم على خط مستقيم. (أ) حدد الموقع الابتدائي للجسم واحسب سرعته المتجهة المتوسطة. (ب) اكتب معادلة الحركة المنتظمة التي تصف حركته. (ج) اختبر معادلتك بحساب موقع الجسم عند 4.0 s ومقارنته بالمنحنى. (د) ماذا تعني الإشارة السالبة في الموقع الابتدائي؟', null, '[{"src":"qimg/phys1/c2l4-o12-essay2.svg","alt":"منحنى (الموقع – الزمن) لجسم: خط مستقيم واحد صاعد. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من −8 إلى 14 m كل 2 m، ومحور الزمن عند الموقع 0. يمر الخط بالنقطتين (0 s، −6 m) و(6 s، 12 m)، ويقطع محور الزمن عند 2 s."}]'::jsonb, null, 'تطبيق', 'كتابة معادلة من رسم بياني', 'متوسط', 'الكتاب ص 48 — معادلة الحركة المنتظمة بدلالة السرعة المتجهة المتوسطة'),
('essay', 3, 'يبيّن الشكل الآتي نموذج الجسيم النقطي لدرّاج يتحرك حركة منتظمة على طريق مستقيم، والفترة الزمنية بين كل نقطتين متتاليتين 0.50 s. بدأ التوقيت والدرّاج عند الموقع 24 m، وتحرك نحو نقطة الأصل (في الاتجاه السالب). (أ) كوّن جدول بيانات (الزمن – الموقع) للحركة. (ب) صف منحنى (الموقع – الزمن) المكافئ. (ج) اكتب المعادلة التي تصف حركة الدرّاج، ثم استخدمها لتتحقق من موقعه عند آخر نقطة.', null, '[{"src":"qimg/phys1/c2l4-o12-essay3.svg","alt":"نموذج الجسيم النقطي: ست نقاط فوق محور الموقع d بالمتر، وهو مدرج من 0 إلى 28 m كل 2 m، ومكتوب أعلاه Δt = 0.50 s. تقع النقاط عند المواقع 4 و8 و12 و16 و20 و24 m."}]'::jsonb, null, 'تحليل', 'تحويل بين التمثيلات', 'صعب', 'الكتاب ص 55 — التقويم السؤال 50 (كتابة معادلة الحركة من نموذج الجسيم النقطي)')
