from (values
('mcq', 1, 3, 'موقع الجسم المتحرك بسرعة منتظمة يساوي حاصل ضرب السرعة المتجهة المتوسطة في الزمن مضافًا إليه الموقع الابتدائي: $\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i$.', '["بدّل موضعي السرعة والموقع الابتدائي؛ فالموقع الابتدائي هو الحد الثابت، والسرعة تُضرب في الزمن.","قسم السرعة على الزمن، فيكون الناتج بوحدة m/s² لا m؛ والصحيح ضربها في الزمن.","الموقع الابتدائي يُضاف إلى حاصل ضرب السرعة في الزمن ولا يُطرح منه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.280Z"}'::jsonb),
('mcq', 2, 1, 'في منحنى (الموقع – الزمن): $y$ يقابل $\boldsymbol{d}$، و$x$ يقابل $t$، و$b$ يقابل $\boldsymbol{d}_i$، والميل $m$ يقابل السرعة المتجهة المتوسطة $\boldsymbol{\bar{v}}$، فتصبح المعادلة $\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i$.', '["الموقع الابتدائي يقابل نقطة التقاطع مع المحور الرأسي $b$.","","الزمن هو المتغير على المحور الأفقي ويقابل $x$.","الموقع هو المتغير على المحور الرأسي ويقابل $y$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.280Z"}'::jsonb),
('mcq', 3, 2, 'الميل $\boldsymbol{\bar{v}} = \frac{16 - 6.0}{5.0 - 0} = 2.0\ \text{m/s}$، ونقطة التقاطع مع محور الموقع $\boldsymbol{d}_i = 6.0\ \text{m}$، فالمعادلة $\boldsymbol{d} = (2.0\ \text{m/s})t + 6.0\ \text{m}$.', '["بدّل بين الميل ونقطة التقاطع مع محور الموقع.","حسب السرعة بقسمة الموقع النهائي على الزمن ($\\frac{16}{5}$) بدل قسمة الإزاحة ($16 - 6$) على الزمن.","","استعمل الموقع النهائي حدًا ثابتًا بدل الموقع الابتدائي عند $t = 0$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.280Z"}'::jsonb),
