('mcq', 5, 'يستغرق الضوء 1.28 s ليصل من القمر إلى الأرض. إذا كانت سرعة الضوء $3.00 \times 10^8\ \text{m/s}$، فما بُعد القمر عن الأرض؟', null, null, '["$3.84 \\times 10^8\\ \\text{m}$","$2.34 \\times 10^8\\ \\text{m}$","$4.27 \\times 10^{-9}\\ \\text{m}$","$2.30 \\times 10^{10}\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حساب مسافة', 'متوسط', 'الكتاب ص 55 — التقويم السؤال 47 (بُعد الأرض عن الشمس)'),
('mcq', 6, 'يمثل المنحنى الآتي جزءًا من حركة منتظمة لجسم على خط مستقيم خلال 4 s الأولى. إذا استمر الجسم في الحركة بالسرعة المتجهة نفسها، فما موقعه عند اللحظة 10 s؟', null, '[{"src":"qimg/phys1/c2l4-o13-line.svg","alt":"منحنى (الموقع – الزمن) لجسم: خط مستقيم واحد صاعد. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 4 s كل 1 s، وتدريج الموقع من 0 إلى 18 m كل 2 m. يمر الخط بالنقطتين (0 s، 4 m) و(4 s، 16 m)."}]'::jsonb, '["30 m","44 m","26 m","34 m"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'صعب', 'الكتاب ص 48 — استخدام معادلة الحركة المنتظمة لحساب الموقع'),
('mcq', 7, 'قادت سلمى سيارتها بسرعة منتظمة 80.0 km/h، وقادت صديقتها سيارتها بسرعة منتظمة 100.0 km/h، وانطلقتا معًا من المكان نفسه على طريق مستقيم طوله 60.0 km. ما الزمن الذي ستنتظره الصديقة سلمى في نهاية الطريق؟', null, null, '["15 min","3.0 h","9.0 min","1.35 h"]'::jsonb, 'تطبيق', 'حساب زمن', 'صعب', 'الكتاب ص 55 — التقويم السؤال 49 (قيادة السيارة)'),
('essay', 1, 'بدأ التوقيت وكرة تتدحرج على أرض مستوية عند الموقع 40 m، وتتحرك نحو نقطة الأصل بسرعة متجهة منتظمة $-2.5\ \text{m/s}$. (أ) اكتب معادلة حركة الكرة. (ب) احسب موقع الكرة بعد 6.0 s. (ج) احسب الزمن الذي تستغرقه الكرة لتصل إلى نقطة الأصل. (د) ما المسافة التي قطعتها خلال 6.0 s الأولى؟', null, null, null, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 48 — استخدام معادلة الحركة المنتظمة لحساب الموقع'),
('essay', 2, 'في سباق طوله 400 m على مضمار مستقيم، انطلق عدّاءان A وB معًا من خط البداية؛ فركض A بسرعة منتظمة 5.0 m/s، وركض B بسرعة منتظمة 4.0 m/s. (أ) احسب الزمن الذي يستغرقه كل منهما لقطع السباق. (ب) بعد كم ثانية من وصول A يصل B إلى خط النهاية؟ (ج) على أي بُعد من خط النهاية يكون B لحظة وصول A؟', null, null, null, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 55 — إتقان حل المسائل الأسئلة 46–49'),
('essay', 3, 'يمثل المنحنى الآتي الثواني الخمس الأولى من حركة منتظمة لجسم على خط مستقيم، واستمر الجسم بعدها بالسرعة المتجهة نفسها. (أ) اكتب معادلة حركة الجسم. (ب) استخدم المعادلة لحساب موقعه عند 12 s. (ج) متى يصل الجسم إلى الموقع 50 m؟', null, '[{"src":"qimg/phys1/c2l4-o13-essay3.svg","alt":"منحنى (الموقع – الزمن) لجسم: خط مستقيم واحد صاعد. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من −12 إلى 12 m كل 2 m، ومحور الزمن عند الموقع 0. يمر الخط بالنقطتين (0 s، −10 m) و(5 s، 10 m)، ويقطع محور الزمن عند 2.5 s."}]'::jsonb, null, 'تطبيق', 'حساب من رسم بياني', 'متوسط', 'الكتاب ص 48 — استخدام معادلة الحركة المنتظمة لحساب الموقع')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
