from (values
('mcq', 1, 1, 'من $\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i$ مع $\boldsymbol{d}_i = 0$: المسافة $= 3.5\ \text{m/s} \times 8.0\ \text{s} = 28\ \text{m}$.', '["قسم الزمن على السرعة ($\\frac{8.0}{3.5}$)، والصحيح ضرب السرعة في الزمن.","","قسم السرعة على الزمن ($\\frac{3.5}{8.0}$)، والصحيح ضربهما.","جمع السرعة والزمن ($3.5 + 8.0$)، وهذا لا معنى فيزيائيًا له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.282Z"}'::jsonb),
('mcq', 2, 0, '$\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i = (-3.0\ \text{m/s})(5.0\ \text{s}) + 12\ \text{m} = -3.0\ \text{m}$، أي إن العربة تجاوزت نقطة الأصل بـ 3.0 m في الاتجاه السالب.', '["","أهمل إشارة السرعة المتجهة فأضاف الإزاحة بدل أن يطرحها.","حسب الإزاحة $\\boldsymbol{\\bar{v}}t$ فقط ونسي إضافة الموقع الابتدائي.","أخطأ في إشارة الناتج؛ فـ $12 - 15 = -3.0$ لا $+3.0$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.282Z"}'::jsonb),
('mcq', 3, 3, 'من $\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i$: $t = \frac{\boldsymbol{d} - \boldsymbol{d}_i}{\boldsymbol{\bar{v}}} = \frac{30.0\ \text{m} - 5.0\ \text{m}}{2.5\ \text{m/s}} = 10\ \text{s}$.', '["قسم الموقع النهائي على السرعة ($\\frac{30.0}{2.5}$) ونسي طرح الموقع الابتدائي.","أضاف الموقع الابتدائي بدل أن يطرحه ($\\frac{30.0 + 5.0}{2.5}$).","قسم السرعة على الإزاحة ($\\frac{2.5}{25}$) بدل قسمة الإزاحة على السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.283Z"}'::jsonb),
('mcq', 4, 2, '$72\ \text{km/h} = \frac{72}{3.6} = 20\ \text{m/s}$، والمسافة $= 20\ \text{m/s} \times 0.60\ \text{s} = 12\ \text{m}$.', '["ضرب 72 في 0.60 دون تحويل السرعة من km/h إلى m/s.","حوّل السرعة إلى 20 m/s ثم قسمها على الزمن ($\\frac{20}{0.60}$) بدل ضربها فيه.","","ضرب السرعة في 3.6 بدل قسمتها عليه عند التحويل إلى m/s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.283Z"}'::jsonb),
('mcq', 5, 0, 'المسافة $= \bar{v}t = (3.00 \times 10^8\ \text{m/s})(1.28\ \text{s}) = 3.84 \times 10^8\ \text{m}$.', '["","قسم سرعة الضوء على الزمن بدل ضربها فيه.","قسم الزمن على سرعة الضوء.","ضرب في 60 ظنًا أن الزمن بالدقائق، مع أنه بالثواني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.283Z"}'::jsonb),
('mcq', 6, 3, 'من المنحنى: $\boldsymbol{d}_i = 4\ \text{m}$، و$\boldsymbol{\bar{v}} = \frac{16 - 4}{4 - 0} = 3.0\ \text{m/s}$. إذن $\boldsymbol{d} = (3.0\ \text{m/s})(10\ \text{s}) + 4\ \text{m} = 34\ \text{m}$.', '["حسب $\\boldsymbol{\\bar{v}}t$ فقط ونسي إضافة الموقع الابتدائي 4 m.","حسب السرعة بقسمة الموقع النهائي على الزمن ($\\frac{16}{4} = 4$) بدل قسمة الإزاحة على الزمن.","طرح الموقع الابتدائي بدل أن يضيفه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-18T12:34:59.283Z"}'::jsonb),
('mcq', 7, 2, 'زمن سلمى $= \frac{60.0}{80.0} = 0.750\ \text{h}$، وزمن صديقتها $= \frac{60.0}{100.0} = 0.600\ \text{h}$، والفرق $0.150\ \text{h} = 0.150 \times 60 = 9.0\ \text{min}$.', '["حسب الفرق 0.150 h ثم قرأه 15 min، والصحيح $0.150 \\times 60 = 9.0\\ \\text{min}$.","قسم طول الطريق على فرق السرعتين ($\\frac{60.0}{20.0}$)، وهذا لا يعطي فرق الزمنين.","","جمع زمني الرحلتين بدل طرحهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.283Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $\boldsymbol{d} = (-2.5\ \text{m/s})t + 40\ \text{m}$. (ب) $\boldsymbol{d} = (-2.5)(6.0) + 40 = 25\ \text{m}$. (ج) عند نقطة الأصل $\boldsymbol{d} = 0$: $t = \frac{0 - 40\ \text{m}}{-2.5\ \text{m/s}} = 16\ \text{s}$. (د) المسافة $= |25 - 40| = 15\ \text{m}$.', '["المعادلة $\\boldsymbol{d} = (-2.5\\ \\text{m/s})t + 40\\ \\text{m}$","الموقع بعد 6.0 s يساوي 25 m","زمن الوصول إلى نقطة الأصل 16 s","المسافة المقطوعة 15 m"]'::jsonb, '["$\\boldsymbol{d} = (-2.5\\ \\text{m/s})(6.0\\ \\text{s}) + 40\\ \\text{m} = 25\\ \\text{m}$","$0 = (-2.5\\ \\text{m/s})t + 40\\ \\text{m} \\Rightarrow t = 16\\ \\text{s}$","المسافة $= |25\\ \\text{m} - 40\\ \\text{m}| = 15\\ \\text{m}$"]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"الموقع","marks":1},{"element":"الزمن","marks":1},{"element":"المسافة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحسابات صحيحة بوحداتها"},{"level":"2–3 درجات","description":"خطأ في الإشارة أو في مطلب واحد"},{"level":"1 درجة","description":"مطلب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال إشارة السرعة فيصبح الموقع 55 m","نسيان الموقع الابتدائي عند حساب الموقع","كتابة المسافة سالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.284Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $t_A = \frac{400\ \text{m}}{5.0\ \text{m/s}} = 80\ \text{s}$، $t_B = \frac{400\ \text{m}}{4.0\ \text{m/s}} = 100\ \text{s}$. (ب) $100 - 80 = 20\ \text{s}$. (ج) موقع B عند 80 s: $\boldsymbol{d} = (4.0)(80) = 320\ \text{m}$، فيكون على بُعد $400 - 320 = 80\ \text{m}$ من خط النهاية.', '["زمن A يساوي 80 s","زمن B يساوي 100 s","فرق الزمنين 20 s","B على بُعد 80 m لحظة وصول A"]'::jsonb, '["$t_A = \\frac{400\\ \\text{m}}{5.0\\ \\text{m/s}} = 80\\ \\text{s}$","$t_B = \\frac{400\\ \\text{m}}{4.0\\ \\text{m/s}} = 100\\ \\text{s}$","$\\Delta t = 100\\ \\text{s} - 80\\ \\text{s} = 20\\ \\text{s}$","$\\boldsymbol{d}_B = (4.0\\ \\text{m/s})(80\\ \\text{s}) = 320\\ \\text{m}$؛ $400 - 320 = 80\\ \\text{m}$"]'::jsonb, '[{"element":"الزمنان","marks":2},{"element":"فرق الزمنين","marks":1},{"element":"بُعد B عن النهاية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحسابات صحيحة"},{"level":"2–3 درجات","description":"خطأ في مطلب واحد"},{"level":"1 درجة","description":"حساب زمن واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة طول السباق على فرق السرعتين ($\\frac{400}{1.0} = 400\\ \\text{s}$)","حساب موقع B عند 100 s بدل 80 s","ضرب السرعة في طول السباق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.284Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $\boldsymbol{d}_i = -10\ \text{m}$، و$\boldsymbol{\bar{v}} = \frac{10 - (-10)}{5 - 0} = 4.0\ \text{m/s}$، فالمعادلة $\boldsymbol{d} = (4.0\ \text{m/s})t - 10\ \text{m}$. (ب) $\boldsymbol{d} = (4.0)(12) - 10 = 38\ \text{m}$. (ج) $t = \frac{50 - (-10)}{4.0} = 15\ \text{s}$.', '["السرعة $4.0\\ \\text{m/s}$ والموقع الابتدائي $-10\\ \\text{m}$","المعادلة $\\boldsymbol{d} = (4.0\\ \\text{m/s})t - 10\\ \\text{m}$","الموقع عند 12 s يساوي 38 m","الزمن اللازم للوصول إلى 50 m يساوي 15 s"]'::jsonb, '["$\\boldsymbol{\\bar{v}} = \\frac{10\\ \\text{m} - (-10\\ \\text{m})}{5\\ \\text{s} - 0\\ \\text{s}} = 4.0\\ \\text{m/s}$","$\\boldsymbol{d} = (4.0\\ \\text{m/s})(12\\ \\text{s}) - 10\\ \\text{m} = 38\\ \\text{m}$","$t = \\frac{50\\ \\text{m} - (-10\\ \\text{m})}{4.0\\ \\text{m/s}} = 15\\ \\text{s}$"]'::jsonb, '[{"element":"المعادلة","marks":2},{"element":"الموقع عند 12 s","marks":1},{"element":"زمن الوصول إلى 50 m","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"خطأ في إشارة الموقع الابتدائي أو في مطلب واحد"},{"level":"1 درجة","description":"حساب السرعة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الموقع الابتدائي موجبًا 10 m","حساب السرعة $\\frac{10}{5} = 2.0\\ \\text{m/s}$ بإهمال الموقع الابتدائي","حساب الزمن $\\frac{50}{4.0}$ دون طرح الموقع الابتدائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-18T12:34:59.284Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O13') and x.type = v.type and x.number = v.number
