select (select id from public.objectives where code = 'P1-C2-L4-O14'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يتحرك جسم نحو اليمين بسرعة متجهة ثابتة، ويبيّن الشكل الآتي أربعة مخططات توضيحية مرقمة لحركته، رُسمت عليها متجهات السرعة باللون الأحمر. أيّ المخططات تمثل فيه متجهات السرعة حركة الجسم تمثيلًا صحيحًا؟', null, '[{"src":"qimg/phys1/c2l4-o14-choices.svg","alt":"أربعة صفوف مرقمة من (1) إلى (4)، في كل صف ست نقاط سوداء تفصل بينها مسافات متساوية، وفوق النقاط أسهم حمراء. الصف (1): خمسة أسهم متساوية الطول تشير نحو اليمين. الصف (2): خمسة أسهم تشير نحو اليمين يزداد طولها من اليسار إلى اليمين. الصف (3): خمسة أسهم متساوية الطول تشير نحو اليسار. الصف (4): خمسة أسهم تشير نحو اليمين يتناقص طولها من اليسار إلى اليمين."}]'::jsonb, '["المخطط (2)","المخطط (3)","المخطط (1)","المخطط (4)"]'::jsonb, 'تطبيق', 'اختيار تمثيل', 'متوسط', 'الكتاب ص 47 — تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة'),
('mcq', 2, 'يبيّن المخطط التوضيحي الآتي حركة سيارتين A وB نحو اليمين، والتُقطت الصور على فترات زمنية متساوية. إذا رُسم متجه السرعة للسيارة A بطول 1.0 cm، فما طول متجه السرعة الذي يُرسم للسيارة B بمقياس الرسم نفسه؟', null, '[{"src":"qimg/phys1/c2l4-o14-twocars.svg","alt":"مخطط توضيحي للحركة من صفين من النقاط. الصف العلوي للسيارة A: ست نقاط زرقاء تفصل بين كل نقطتين متتاليتين مسافة ثابتة صغيرة. الصف السفلي للسيارة B: ست نقاط حمراء تفصل بين كل نقطتين متتاليتين مسافة ثابتة تساوي ضعف المسافة في صف A. تبدأ النقطتان الأوليان من الموقع الأفقي نفسه."}]'::jsonb, '["1.0 cm","0.50 cm","4.0 cm","2.0 cm"]'::jsonb, 'تطبيق', 'تناسب', 'متوسط', 'الكتاب ص 47 — تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة'),
('mcq', 3, 'ما اللون المعتمد لرسم متجهات السرعة على المخطط التوضيحي للحركة؟', null, null, '["الأحمر","الأخضر","الأزرق","البنفسجي"]'::jsonb, 'تذكر', 'دلالة اللون', 'سهل', 'الكتاب ص 44 — دلالة اللون (متجهات السرعة باللون الأحمر)'),
('mcq', 4, 'تسير سيارتان على طريق بسرعتين مختلفتين، وفي مؤخرة كل منهما فرشاة دهان تهبط كل ثانية لترسم خطًا على الأرض مدة نصف ثانية. ماذا ترسم فرشاة السيارة الأسرع مقارنة بالأخرى؟', null, null, '["خطًا أقصر لأنها تمر بسرعة","خطًا أطول في اتجاه حركتها","خطًا بالطول نفسه لأن مدة الرسم واحدة","خطوطًا أكثر عددًا في كل ثانية"]'::jsonb, 'فهم', 'تفسير نموذج', 'سهل', 'الكتاب ص 47 — تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة'),
('mcq', 5, 'يبيّن الشكل الآتي مخططًا توضيحيًا رسمه طالب لجسم يتحرك نحو اليمين، والتُقطت الصور على فترات زمنية متساوية، ثم رسم عليه متجهات السرعة باللون الأحمر. ما الخطأ في رسمه؟', null, '[{"src":"qimg/phys1/c2l4-o14-wrong.svg","alt":"مخطط توضيحي للحركة: صف من ست نقاط سوداء تتزايد المسافات بينها من اليسار إلى اليمين، وفوق كل نقطة من النقاط الخمس الأولى سهم أحمر قصير يشير نحو اليمين، والأسهم الخمسة متساوية الطول تمامًا."}]'::jsonb, '["رسم المتجهات باللون الأحمر بدل اللون الأخضر","جعل المتجهات تشير في اتجاه حركة الجسم","رسم متجهًا واحدًا بين كل نقطتين متتاليتين","رسم المتجهات متساوية الطول مع أن المسافات بين النقاط تتزايد"]'::jsonb, 'تحليل', 'اكتشاف خطأ', 'صعب', 'الكتاب ص 47 — تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة'),
('mcq', 6, 'اختار طالب مقياس رسم يمثل فيه كل 1 cm سرعة مقدارها 2.0 m/s. ما طول المتجه الذي يرسمه على المخطط التوضيحي لتمثيل سرعة متجهة مقدارها 7.0 m/s؟', null, null, '["14 cm","3.5 cm","7.0 cm","0.29 cm"]'::jsonb, 'تطبيق', 'مقياس رسم', 'متوسط', 'الكتاب ص 47 — تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة'),
('mcq', 7, 'يتحرك جسم بسرعة متجهة ثابتة $-3.0\ \text{m/s}$، والاتجاه الموجب نحو اليمين. كيف تُرسم متجهات السرعة على المخطط التوضيحي لحركته؟', null, null, '["متجهات متساوية الطول تشير نحو اليسار","متجهات متساوية الطول تشير نحو اليمين","متجهات يتناقص طولها وتشير نحو اليسار","متجهات يزداد طولها وتشير نحو اليسار"]'::jsonb, 'تطبيق', 'رسم متجهات', 'متوسط', 'الكتاب ص 47 — تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة'),
('essay', 1, 'يبيّن الشكل الآتي نموذج الجسيم النقطي لعربة تتحرك نحو اليمين (الاتجاه الموجب)، والفترة الزمنية بين كل نقطتين متتاليتين 0.50 s. (أ) احسب السرعة المتجهة المتوسطة للعربة في كل فترة. (ب) إذا اخترت مقياس رسم يمثل فيه كل 1 cm سرعة 3.0 m/s، فما طول كل متجه سرعة ستضيفه إلى المخطط؟ (ج) صف المتجهات التي ستضيفها.', null, '[{"src":"qimg/phys1/c2l4-o14-essay1.svg","alt":"نموذج الجسيم النقطي: خمس نقاط فوق محور الموقع d بالمتر، وهو مدرج من 0 إلى 14 m كل 1 m، ومكتوب أعلاه Δt = 0.50 s. تقع النقاط عند المواقع 0 و3 و6 و9 و12 m."}]'::jsonb, null, 'تطبيق', 'رسم متجهات', 'سهل', 'الكتاب ص 47 — تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة'),
('essay', 2, 'على طريق مستقيم يمتد شرقًا وغربًا، تتحرك السيارة A نحو الشرق بسرعة ثابتة 10 m/s، وتتحرك السيارة B نحو الغرب بسرعة ثابتة 25 m/s، والاتجاه الموجب نحو الشرق. صمّم مخططًا توضيحيًا لحركة كل سيارة بصورة كل 1.0 s، مبيّنًا: (أ) الإزاحة بين كل صورتين متتاليتين لكل سيارة. (ب) مقياس رسم مناسب لمتجهات السرعة وطول متجه كل سيارة. (ج) كيف يختلف المخططان في تباعد النقاط واتجاه المتجهات وأطوالها.', null, null, null, 'تطبيق', 'تصميم تمثيل', 'صعب', 'الكتاب ص 47 — تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة'),
('essay', 3, 'يبيّن الشكل الآتي نموذج الجسيم النقطي لدرّاجة تتحرك نحو اليمين (الاتجاه الموجب)، والفترة الزمنية بين كل نقطتين متتاليتين 1.0 s، وآخر نقطتين متطابقتان عند 20 m. (أ) احسب السرعة المتجهة المتوسطة في كل فترة من الفترات الخمس. (ب) باستعمال مقياس يمثل فيه كل 1 cm سرعة 2.0 m/s، حدد طول كل متجه سرعة. (ج) صف حركة الدرّاجة، وفسّر ما تدل عليه أطوال المتجهات.', null, '[{"src":"qimg/phys1/c2l4-o14-essay3.svg","alt":"نموذج الجسيم النقطي: ست نقاط فوق محور الموقع d بالمتر، وهو مدرج من 0 إلى 22 m كل 2 m، ومكتوب أعلاه Δt = 1.0 s. تقع النقاط عند المواقع 0 و8 و14 و18 و20 m، والنقطة السادسة منطبقة على النقطة الخامسة عند 20 m."}]'::jsonb, null, 'تحليل', 'تمثيل وتحليل', 'صعب', 'الكتاب ص 47 — تمثيل السرعة المتجهة المتوسطة على المخططات التوضيحية للحركة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O14') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'السرعة المتجهة ثابتة مقدارًا واتجاهًا، فتُرسم متجهات متساوية الطول تشير جميعها في اتجاه الحركة (نحو اليمين)، وهذا ما في المخطط (1).', '["أطوال المتجهات فيه تتزايد، وهذا يعني أن السرعة تزداد، والسرعة هنا ثابتة.","المتجهات فيه تشير نحو اليسار، أي عكس اتجاه حركة الجسم.","","أطوال المتجهات فيه تتناقص، وهذا يعني أن السرعة تقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.285Z"}'::jsonb),
('mcq', 2, 3, 'المسافة بين صورتين متتاليتين للسيارة B ضعف المسافة للسيارة A في الفترة الزمنية نفسها، فسرعتها ضعف سرعة A، وطول المتجه يتناسب مع مقدار السرعة: $2 \times 1.0 = 2.0\ \text{cm}$.', '["جعل المتجهين متساويين، مع أن B تقطع في الفترة الزمنية نفسها ضعف ما تقطعه A.","عكس التناسب؛ فالسيارة الأسرع يُرسم لها متجه أطول لا أقصر.","ربّع النسبة بين السرعتين، وطول المتجه يتناسب طرديًا مع مقدار السرعة لا مع مربعها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.285Z"}'::jsonb),
('mcq', 3, 0, 'تُرسم متجهات السرعة باللون الأحمر، ومتجهات الإزاحة باللون الأخضر، تمييزًا بين الكميتين.', '["","اللون الأخضر لمتجهات الإزاحة.","اللون الأزرق لمتجهات القوة.","اللون البنفسجي لمتجه التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.285Z"}'::jsonb),
('mcq', 4, 1, 'خلال نصف الثانية تقطع السيارة الأسرع مسافة أكبر فترسم خطًا أطول في اتجاه حركتها؛ وهذه الخطوط تشبه متجهات السرعة على المخطط التوضيحي للحركة، إذ يتناسب طولها مع مقدار السرعة.', '["السيارة الأسرع تقطع مسافة أكبر خلال نصف الثانية، فخطها أطول.","","تساوي المدة لا يعني تساوي الطول؛ فالطول يعتمد على السرعة.","الفرشاتان تهبطان مرة واحدة كل ثانية، فعدد الخطوط متساوٍ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:59.285Z"}'::jsonb),
('mcq', 5, 3, 'تتزايد المسافات بين النقاط المتتالية، أي إن الجسم يقطع إزاحات أكبر في الفترات الزمنية المتساوية فسرعته تزداد؛ لذا يجب أن تتزايد أطوال المتجهات بالنسبة نفسها، لا أن تكون متساوية.', '["متجهات السرعة تُرسم فعلًا باللون الأحمر، فلا خطأ في اللون.","متجه السرعة يشير في اتجاه الحركة، وهذا صحيح.","هذا هو الصحيح؛ فكل متجه يمثل السرعة المتجهة المتوسطة في فترة واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.285Z"}'::jsonb),
('mcq', 6, 1, 'كل 1 cm يمثل 2.0 m/s، فطول المتجه $= \frac{7.0\ \text{m/s}}{2.0\ \text{m/s}} \times 1\ \text{cm} = 3.5\ \text{cm}$.', '["ضرب السرعة في 2.0 بدل قسمتها عليه.","","أهمل مقياس الرسم وجعل كل 1 cm يمثل 1 m/s.","قسم 2.0 على 7.0 بدل قسمة 7.0 على 2.0."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.285Z"}'::jsonb),
('mcq', 7, 0, 'الإشارة السالبة تعني أن الحركة في الاتجاه السالب (نحو اليسار)، وثبات السرعة يعني تساوي أطوال المتجهات؛ فتُرسم متجهات متساوية الطول تشير نحو اليسار.', '["","أهمل الإشارة السالبة التي تدل على أن الحركة نحو اليسار.","السرعة ثابتة المقدار، فلا تتغير أطوال المتجهات؛ والإشارة السالبة تدل على الاتجاه لا على التناقص.","تزايد الطول يعني ازدياد مقدار السرعة، والسرعة هنا ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.286Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الإزاحة في كل فترة 3 m، فالسرعة $\boldsymbol{\bar{v}} = \frac{3\ \text{m}}{0.50\ \text{s}} = +6.0\ \text{m/s}$ في الفترات الأربع. (ب) طول كل متجه $= \frac{6.0}{3.0} = 2.0\ \text{cm}$. (ج) أربعة متجهات حمراء متساوية الطول (2.0 cm) تشير جميعها نحو اليمين، يبدأ كل منها عند نقطة ويمتد نحو النقطة التالية.', '["السرعة في كل فترة $+6.0\\ \\text{m/s}$","طول كل متجه 2.0 cm","المتجهات حمراء متساوية الطول نحو اليمين"]'::jsonb, '["$\\Delta \\boldsymbol{d} = 3\\ \\text{m}$ لكل فترة","$\\boldsymbol{\\bar{v}} = \\frac{3\\ \\text{m}}{0.50\\ \\text{s}} = 6.0\\ \\text{m/s}$","الطول $= \\frac{6.0\\ \\text{m/s}}{3.0\\ \\text{m/s}} \\times 1\\ \\text{cm} = 2.0\\ \\text{cm}$"]'::jsonb, '[{"element":"حساب السرعة","marks":1},{"element":"طول المتجه","marks":1},{"element":"وصف المتجهات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع العناصر صحيحة"},{"level":"2 درجتان","description":"خطأ في عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال 1.0 s فترة زمنية بدل 0.50 s","رسم المتجهات بأطوال مختلفة","ضرب السرعة في المقياس بدل القسمة عليه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-18T12:34:59.286Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) A: $\Delta \boldsymbol{d} = (+10\ \text{m/s})(1.0\ \text{s}) = +10\ \text{m}$؛ B: $\Delta \boldsymbol{d} = (-25\ \text{m/s})(1.0\ \text{s}) = -25\ \text{m}$. (ب) مثلًا كل 1 cm يمثل 5 m/s، فطول متجه A يساوي $\frac{10}{5} = 2.0\ \text{cm}$ نحو الشرق، وطول متجه B يساوي $\frac{25}{5} = 5.0\ \text{cm}$ نحو الغرب. (ج) نقاط B متباعدة أكثر (25 m مقابل 10 m) والمسافات في كل مخطط متساوية لأن الحركة منتظمة؛ ومتجهات A متساوية الطول نحو الشرق، ومتجهات B متساوية الطول نحو الغرب وطولها 2.5 مرة طول متجهات A.', '["إزاحة A لكل صورة $+10\\ \\text{m}$ وإزاحة B لكل صورة $-25\\ \\text{m}$","مقياس رسم مناسب","أطوال المتجهات وفق المقياس بالنسبة 2.5","المقارنة: التباعد والاتجاه والأطوال"]'::jsonb, '["$\\Delta \\boldsymbol{d}_A = (10\\ \\text{m/s})(1.0\\ \\text{s}) = +10\\ \\text{m}$","$\\Delta \\boldsymbol{d}_B = (-25\\ \\text{m/s})(1.0\\ \\text{s}) = -25\\ \\text{m}$","بمقياس 1 cm لكل 5 m/s: A طوله 2.0 cm، وB طوله 5.0 cm"]'::jsonb, '[{"element":"الإزاحتان","marks":1},{"element":"المقياس وأطوال المتجهات","marks":2},{"element":"المقارنة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تصميم متكامل بمقياس صحيح ومقارنة شاملة"},{"level":"3–4 درجات","description":"خطأ في الاتجاه أو في نسبة الأطوال"},{"level":"1–2 درجة","description":"حساب الإزاحتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم متجهي السيارتين في الاتجاه نفسه","رسم المتجهين بالطول نفسه","جعل طول المتجه يتناسب عكسيًا مع السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.286Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الإزاحات: 8، 6، 4، 2، 0 m، فالسرعات: $+8.0$، $+6.0$، $+4.0$، $+2.0$، 0 (بوحدة m/s). (ب) أطوال المتجهات: 4.0، 3.0، 2.0، 1.0 cm، ولا يُرسم متجه في الفترة الأخيرة (طوله صفر). (ج) الدرّاجة تتحرك نحو اليمين ويتناقص مقدار سرعتها تدريجيًا حتى تتوقف عند 20 m؛ وتناقص أطوال المتجهات يدل على تناقص مقدار السرعة، وانعدام المتجه الأخير يدل على السكون.', '["السرعات الخمس: 8.0، 6.0، 4.0، 2.0، 0 m/s","الأطوال: 4.0، 3.0، 2.0، 1.0، 0 cm","الوصف: تتباطأ ثم تتوقف","تفسير دلالة أطوال المتجهات"]'::jsonb, '["$\\boldsymbol{\\bar{v}}_1 = \\frac{8\\ \\text{m} - 0\\ \\text{m}}{1.0\\ \\text{s}} = 8.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{v}}_2 = \\frac{14 - 8}{1.0} = 6.0$، $\\boldsymbol{\\bar{v}}_3 = \\frac{18 - 14}{1.0} = 4.0$، $\\boldsymbol{\\bar{v}}_4 = \\frac{20 - 18}{1.0} = 2.0$، $\\boldsymbol{\\bar{v}}_5 = 0$","الطول $= \\frac{\\bar{v}}{2.0\\ \\text{m/s}} \\times 1\\ \\text{cm}$: 4.0، 3.0، 2.0، 1.0، 0 cm"]'::jsonb, '[{"element":"حساب السرعات","marks":2},{"element":"أطوال المتجهات","marks":1},{"element":"الوصف والتفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حسابات وأطوال صحيحة ووصف وتفسير سليمان"},{"level":"3–4 درجات","description":"خطأ في قيمة أو إغفال الفترة الأخيرة"},{"level":"1–2 درجة","description":"حساب بعض السرعات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة موقع كل نقطة على زمنها بدل الإزاحة في كل فترة","رسم متجه في الفترة الأخيرة","وصف الحركة بأنها متسارعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-18T12:34:59.286Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O14') and x.type = v.type and x.number = v.number
