insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L4-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل المنحنى الآتي حركة متزلج على مسار مستقيم. أين كان المتزلج عند بدء التوقيت؟', null, '[{"src":"qimg/phys1/c2l4-o15-line1.svg","alt":"منحنى (الموقع – الزمن) لجسم: خط مستقيم واحد صاعد. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. يمر الخط بالنقطتين (0 s، 8 m) و(5 s، 18 m)."}]'::jsonb, '["8 m","18 m","2 m","0 m"]'::jsonb, 'تطبيق', 'قراءة رسم بياني', 'سهل', 'الكتاب ص 48 — الموقع الابتدائي (نقطة التقاطع مع المحور الرأسي)'),
('mcq', 2, 'بالاستعانة بالمنحنى الآتي لحركة عربة على مسار مستقيم، حدد الموقع الابتدائي للعربة.', null, '[{"src":"qimg/phys1/c2l4-o15-line2.svg","alt":"منحنى (الموقع – الزمن) لجسم: خط مستقيم واحد صاعد. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 4 s كل 1 s، وتدريج الموقع من −8 إلى 12 m كل 2 m، ومحور الزمن عند الموقع 0. يمر الخط بالنقطتين (0 s، −6 m) و(4 s، 10 m)، ويقطع محور الزمن عند 1.5 s."}]'::jsonb, '["$+6\\ \\text{m}$","$+10\\ \\text{m}$","$0\\ \\text{m}$","$-6\\ \\text{m}$"]'::jsonb, 'تطبيق', 'قراءة رسم بياني', 'متوسط', 'الكتاب ص 48 — الموقع الابتدائي (نقطة التقاطع مع المحور الرأسي)'),
('mcq', 3, 'يمثل المنحنى الآتي حركة أربعة أجسام A وB وC وD. ما ترتيبها بحسب الموقع الابتدائي، بدءًا بأكبر قيمة موجبة وانتهاء بأكبر قيمة سالبة؟', null, '[{"src":"qimg/phys1/c2l4-o15-rank.svg","alt":"منحنى (الموقع – الزمن) لأربعة أجسام A وB وC وD. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من −12 إلى 18 m كل 2 m، ومحور الزمن عند الموقع 0. الخط A (أزرق) هابط من (0 s، 12 m) إلى (5 s، 2 m). الخط B (أحمر) صاعد من (0 s، −4 m) إلى (5 s، 16 m). الخط C (أخضر) صاعد من (0 s، 6 m) إلى (5 s، 11 m). الخط D (برتقالي) صاعد من (0 s، −10 m) إلى (5 s، 0 m)."}]'::jsonb, '["A، ثم D، ثم C، ثم B","A، ثم C، ثم B، ثم D","B، ثم C، ثم A، ثم D","D، ثم B، ثم C، ثم A"]'::jsonb, 'تحليل', 'ترتيب', 'صعب', 'الكتاب ص 49 — مراجعة 2-4 السؤال 31 (الموقع الابتدائي)'),
('mcq', 4, 'يقطع الخط البياني في منحنى (الموقع – الزمن) لجسم محورَ الموقع عند $-15\ \text{m}$. ماذا يعني ذلك؟', null, null, '["تحرك الجسم إزاحة مقدارها 15 m في الاتجاه السالب خلال حركته","السرعة المتجهة المتوسطة للجسم تساوي $-15\\ \\text{m/s}$","كان الجسم عند بدء التوقيت على بُعد 15 m من نقطة الأصل في الاتجاه السالب","وصل الجسم إلى نقطة الأصل بعد مرور 15 s من بدء التوقيت"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 48 — الموقع الابتدائي (نقطة التقاطع مع المحور الرأسي)'),
('mcq', 5, 'تصف المعادلة $\boldsymbol{d} = (3.0\ \text{m/s})t - 7.0\ \text{m}$ حركة جسم. عند أي قيمة يقطع خطه البياني في منحنى (الموقع – الزمن) محور الموقع؟', null, null, '["$+7.0\\ \\text{m}$","$-7.0\\ \\text{m}$","$+3.0\\ \\text{m}$","$-4.0\\ \\text{m}$"]'::jsonb, 'تطبيق', 'ربط المعادلة بالرسم', 'سهل', 'الكتاب ص 48 — الموقع الابتدائي (نقطة التقاطع مع المحور الرأسي)'),
('mcq', 6, 'يمثل المنحنى الآتي حركة عدّاءين A (الخط المتقطع) وB (الخط المتصل) على مضمار مستقيم. ماذا تبيّن نقطتا تقاطع الخطين مع محور الموقع عن موقعي العدّاءين عند بدء التوقيت؟', null, '[{"src":"qimg/phys1/c2l4-o15-runners.svg","alt":"منحنى (الموقع – الزمن) لعدّاءين. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من 0 إلى 20 m كل 2 m. الخط A (أزرق متقطع) من (0 s، 6 m) إلى (6 s، 12 m). الخط B (أحمر متصل) من (0 s، 0 m) إلى (6 s، 18 m). يتقاطع الخطان عند (3 s، 9 m)."}]'::jsonb, '["كان A متقدمًا على B بمسافة 6 m","كان العدّاءان عند الموقع نفسه","كان B متقدمًا على A بمسافة 6 m","كان A متقدمًا على B بمسافة 9 m"]'::jsonb, 'تطبيق', 'قراءة رسم بياني', 'متوسط', 'الكتاب ص 54 — التقويم السؤال 43a'),
('mcq', 7, 'يمثل المنحنى الآتي جزءًا من حركة منتظمة لجسم بين اللحظتين 2 s و6 s. إذا كان الجسم يتحرك بالسرعة المتجهة نفسها منذ بدء التوقيت، فما موقعه الابتدائي؟', null, '[{"src":"qimg/phys1/c2l4-o15-segment.svg","alt":"منحنى (الموقع – الزمن) لجسم. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج الموقع من 0 إلى 24 m كل 2 m. الخط المرسوم قطعة مستقيمة صاعدة تبدأ من النقطة (2 s، 10 m) وتنتهي عند النقطة (6 s، 22 m)، ولا يظهر أي خط بين 0 s و2 s."}]'::jsonb, '["10 m","22 m","4 m","0 m"]'::jsonb, 'تطبيق', 'استقراء من رسم بياني', 'صعب', 'الكتاب ص 48 — الموقع الابتدائي (نقطة التقاطع مع المحور الرأسي)'),
('essay', 1, 'يمثل المنحنى الآتي حركة ثلاثة أجسام P وQ وR. (أ) حدد الموقع الابتدائي لكل جسم. (ب) رتّب الأجسام بحسب الموقع الابتدائي بدءًا بأكبر قيمة موجبة وانتهاء بأكبر قيمة سالبة. (ج) هل يختلف الترتيب إذا رتّبتها بحسب المسافة الابتدائية لكل جسم عن نقطة الأصل؟ وضّح.', null, '[{"src":"qimg/phys1/c2l4-o15-essay1.svg","alt":"منحنى (الموقع – الزمن) لثلاثة أجسام P وQ وR. المحور الأفقي: الزمن بالثانية (s)، والمحور الرأسي: الموقع بالمتر (m). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج الموقع من −14 إلى 20 m كل 2 m، ومحور الزمن عند الموقع 0. الخط P (أزرق) من (0 s، 10 m) إلى (5 s، 20 m). الخط Q (أحمر) من (0 s، −14 m) إلى (5 s، 6 m). الخط R (أخضر) هابط من (0 s، −2 m) إلى (5 s، −12 m)."}]'::jsonb, null, 'تحليل', 'ترتيب ومقارنة', 'صعب', 'الكتاب ص 49 — مراجعة 2-4 السؤال 31 (الموقع الابتدائي)'),
('essay', 2, 'سُجّلت مواقع لعبة آلية تتحرك حركة منتظمة على مسار مستقيم ابتداءً من اللحظة 2.0 s كما في الجدول الآتي، ولم يُسجَّل موقعها عند بدء التوقيت. (أ) مثّل البيانات بمنحنى (الموقع – الزمن)، ثم مُدّ الخط البياني لتحدد الموقع الابتدائي للعبة. (ب) تحقق من إجابتك حسابيًا. (ج) ماذا تعني إشارة الموقع الابتدائي؟ (د) ما الذي تدل عليه نقطة تقاطع الخط مع محور الزمن؟ وبماذا تختلف عن نقطة تقاطعه مع محور الموقع؟', '{"headers":["الزمن (s)","الموقع (m)"],"rows":[["2.0","1.0"],["4.0","7.0"],["6.0","13.0"],["8.0","19.0"]]}'::jsonb, null, null, 'تطبيق', 'قراءة رسم بياني', 'متوسط', 'الكتاب ص 48 — الموقع الابتدائي (نقطة التقاطع مع المحور الرأسي)'),
('essay', 3, 'وضّح كيف تحدد الموقع الابتدائي لجسم يتحرك حركة منتظمة: (أ) من منحنى (الموقع – الزمن). (ب) من معادلة حركته. ثم طبّق ذلك على جسم معادلة حركته $\boldsymbol{d} = (-2.0\ \text{m/s})t + 9.0\ \text{m}$: ما موقعه الابتدائي؟ وأين يقطع خطه البياني محور الموقع؟ وماذا يعني ذلك؟', null, null, null, 'تطبيق', 'توضيح وتطبيق', 'سهل', 'الكتاب ص 48 — الموقع الابتدائي (نقطة التقاطع مع المحور الرأسي)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O15') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الموقع الابتدائي $\boldsymbol{d}_i$ هو موقع الجسم عند $t = 0$، أي نقطة تقاطع الخط البياني مع محور الموقع، وهي هنا 8 m.', '["","هذا موقع المتزلج عند 5 s (الموقع النهائي) لا عند بدء التوقيت.","هذا ميل الخط (2 m/s)، أي سرعته المتجهة المتوسطة لا موقعه الابتدائي.","افترض أن كل متحرك يبدأ من نقطة الأصل، لكن الخط يقطع محور الموقع عند 8 m."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.287Z"}'::jsonb),
('mcq', 2, 3, 'نقطة تقاطع الخط مع محور الموقع (عند $t = 0$) هي $-6\ \text{m}$، فالجسم بدأ على بُعد 6 m من نقطة الأصل في الاتجاه السالب.', '["أهمل الإشارة؛ فنقطة التقاطع تقع أسفل محور الزمن، أي في الاتجاه السالب.","هذا موقع الجسم عند 4 s لا عند بدء التوقيت.","هذه قيمة الموقع عند تقاطع الخط مع محور الزمن (عند 1.5 s)، لا عند $t = 0$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.287Z"}'::jsonb),
('mcq', 3, 1, 'نقاط التقاطع مع محور الموقع: A $= +12$، C $= +6$، B $= -4$، D $= -10$ (بوحدة m)، وبما أن $+12 > +6 > -4 > -10$ فالترتيب A ثم C ثم B ثم D.', '["رتّب بحسب بُعد الجسم الابتدائي عن نقطة الأصل (القيمة المطلقة) وأهمل الإشارة.","","رتّب بحسب الموقع النهائي عند 5 s لا بحسب التقاطع مع محور الموقع.","هذا الترتيب معكوس؛ بدأ بأكبر قيمة سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.287Z"}'::jsonb),
('mcq', 4, 2, 'نقطة تقاطع الخط مع محور الموقع هي الموقع الابتدائي $\boldsymbol{d}_i$ عند $t = 0$، والإشارة السالبة تعني أن الجسم كان عند بدء التوقيت على بُعد 15 m من نقطة الأصل في الاتجاه السالب.', '["نقطة التقاطع تعطي موقعًا عند لحظة واحدة ($t = 0$) لا إزاحة خلال فترة.","السرعة المتجهة المتوسطة يعطيها ميل الخط لا نقطة تقاطعه مع محور الموقع.","","زمن الوصول إلى نقطة الأصل يُقرأ من تقاطع الخط مع محور الزمن لا مع محور الموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.287Z"}'::jsonb),
('mcq', 5, 1, 'نقطة التقاطع مع محور الموقع هي قيمة $\boldsymbol{d}$ عند $t = 0$، أي الحد الثابت $\boldsymbol{d}_i = -7.0\ \text{m}$.', '["أهمل الإشارة السالبة للحد الثابت في المعادلة.","","العدد 3.0 هو الميل (السرعة المتجهة المتوسطة) لا نقطة التقاطع.","عوّض $t = 1\\ \\text{s}$ فحسب الموقع بعد ثانية، لا عند $t = 0$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.288Z"}'::jsonb),
('mcq', 6, 0, 'يقطع خط A محور الموقع عند 6 m وخط B عند 0 m، أي إن A بدأ متقدمًا على B بمسافة 6 m.', '["","الخطان يبدآن من نقطتين مختلفتين على محور الموقع؛ أما تقاطعهما معًا فيحدث لاحقًا عند 3 s.","عكس الموقعين؛ فخط A يبدأ عند 6 m وخط B عند 0 m.","قرأ موقع نقطة تقاطع الخطين (9 m عند 3 s) بدل نقطتي تقاطعهما مع محور الموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.288Z"}'::jsonb),
('mcq', 7, 2, 'ميل الخط $= \frac{22 - 10}{6 - 2} = 3\ \text{m/s}$، وبمدّ الخط إلى $t = 0$: $\boldsymbol{d}_i = 10 - 3 \times 2 = 4\ \text{m}$، وهي نقطة تقاطعه مع محور الموقع.', '["أخذ موقع الجسم عند أول نقطة مرسومة (2 s) بدل مدّ الخط حتى $t = 0$.","هذا موقع الجسم عند 6 s.","","افترض أن الجسم بدأ من نقطة الأصل دون مدّ الخط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.288Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) من نقاط التقاطع مع محور الموقع: P $= +10\ \text{m}$، Q $= -14\ \text{m}$، R $= -2\ \text{m}$. (ب) P ثم R ثم Q، لأن $+10 > -2 > -14$. (ج) نعم؛ المسافة الابتدائية عن نقطة الأصل كمية عددية لا إشارة لها: Q = 14 m، P = 10 m، R = 2 m، فيكون الترتيب من الأبعد Q ثم P ثم R.', '["المواقع الابتدائية بإشاراتها","الترتيب P ثم R ثم Q","الترتيب بالمسافة Q ثم P ثم R","التعليل: المسافة لا إشارة لها"]'::jsonb, '["$\\boldsymbol{d}_{i,P} = +10\\ \\text{m}$، $\\boldsymbol{d}_{i,Q} = -14\\ \\text{m}$، $\\boldsymbol{d}_{i,R} = -2\\ \\text{m}$","$+10 > -2 > -14$","المسافات: 14 m، 10 m، 2 m"]'::jsonb, '[{"element":"المواقع الابتدائية","marks":1},{"element":"الترتيب بالموقع","marks":1},{"element":"الترتيب بالمسافة والتعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة مع التعليل"},{"level":"2–3 درجات","description":"خطأ في إشارة أو في أحد الترتيبين"},{"level":"1 درجة","description":"تحديد المواقع الابتدائية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قراءة الموقع النهائي بدل الابتدائي","ترتيب القيم السالبة بمقدارها فيصبح Q قبل R","القول بعدم اختلاف الترتيبين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.288Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تقع النقاط على خط مستقيم صاعد، وبمدّه إلى الخلف حتى $t = 0$ يقطع محور الموقع عند $-5.0\ \text{m}$، فالموقع الابتدائي $\boldsymbol{d}_i = -5.0\ \text{m}$. (ب) الميل $\boldsymbol{\bar{v}} = \frac{19.0 - 1.0}{8.0 - 2.0} = +3.0\ \text{m/s}$، ومن $\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i$ عند 2.0 s: $\boldsymbol{d}_i = 1.0 - (3.0)(2.0) = -5.0\ \text{m}$. (ج) أن اللعبة كانت عند بدء التوقيت على بُعد 5.0 m من نقطة الأصل في الاتجاه السالب. (د) نقطة التقاطع مع محور الزمن تعطي اللحظة التي يكون فيها الموقع صفرًا، أي لحظة مرور اللعبة بنقطة الأصل: $t = \frac{5.0}{3.0} \approx 1.7\ \text{s}$؛ أما نقطة التقاطع مع محور الموقع فتعطي موقع اللعبة عند $t = 0$ (الموقع الابتدائي).', '["مدّ الخط البياني حتى محور الموقع: $\\boldsymbol{d}_i = -5.0\\ \\text{m}$","التحقق الحسابي بالميل $+3.0\\ \\text{m/s}$ ومعادلة الحركة المنتظمة","معنى الإشارة السالبة للموقع الابتدائي","التمييز بين التقاطع مع محور الزمن (المرور بنقطة الأصل عند 1.7 s تقريبًا) والتقاطع مع محور الموقع (الموقع الابتدائي)"]'::jsonb, '["$\\boldsymbol{\\bar{v}} = \\frac{19.0\\ \\text{m} - 1.0\\ \\text{m}}{8.0\\ \\text{s} - 2.0\\ \\text{s}} = 3.0\\ \\text{m/s}$","$\\boldsymbol{d}_i = \\boldsymbol{d} - \\boldsymbol{\\bar{v}}t = 1.0\\ \\text{m} - (3.0\\ \\text{m/s})(2.0\\ \\text{s}) = -5.0\\ \\text{m}$","$0 = (3.0\\ \\text{m/s})t - 5.0\\ \\text{m} \\Rightarrow t \\approx 1.7\\ \\text{s}$"]'::jsonb, '[{"element":"تحديد الموقع الابتدائي بمدّ الخط","marks":1},{"element":"التحقق الحسابي","marks":2},{"element":"معنى الإشارة","marks":1},{"element":"دلالة التقاطع مع محور الزمن والتمييز","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح للموقع الابتدائي وتحقق حسابي سليم وتفسير صحيح للإشارة وللتقاطعين"},{"level":"3–4 درجات","description":"خطأ في الإشارة أو في الحساب أو خلط بين التقاطعين"},{"level":"1–2 درجة","description":"تحديد الموقع الابتدائي فقط أو حساب الميل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ أول موقع مسجّل (1.0 m) موقعًا ابتدائيًا","كتابة الموقع الابتدائي موجبًا 5.0 m","عدّ تقاطع الخط مع محور الزمن موقعًا ابتدائيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.289Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الموقع الابتدائي هو موقع الجسم عند $t = 0$، ويُقرأ من نقطة تقاطع الخط البياني مع محور الموقع (المحور الرأسي). (ب) في المعادلة $\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i$ هو الحد الثابت $\boldsymbol{d}_i$ (يقابل $b$ في $y = mx + b$). للجسم المعطى: $\boldsymbol{d}_i = 9.0\ \text{m}$، فيقطع خطه محور الموقع عند 9.0 m؛ أي إن الجسم كان عند بدء التوقيت على بُعد 9.0 m من نقطة الأصل في الاتجاه الموجب.', '["من المنحنى: التقاطع مع محور الموقع","من المعادلة: الحد الثابت $\\boldsymbol{d}_i$","التطبيق: $\\boldsymbol{d}_i = 9.0\\ \\text{m}$","المعنى: 9.0 m من نقطة الأصل في الاتجاه الموجب عند $t = 0$"]'::jsonb, '[]'::jsonb, '[{"element":"الطريقة من المنحنى","marks":1},{"element":"الطريقة من المعادلة","marks":1},{"element":"التطبيق والمعنى","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الطريقتان والتطبيق صحيحة"},{"level":"2 درجتان","description":"خطأ في عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار $-2.0$ هو الموقع الابتدائي","الخلط بين محور الموقع ومحور الزمن","الظن أن الموقع الابتدائي صفر دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-18T12:34:59.289Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
