from (values
('mcq', 1, 'ما أهمية رسم نموذج مصور ونموذج فيزيائي لمسألة حركة قبل البدء بحل المعادلات؟', null, null, '["يغنيان عن استخدام المعادلات في حل المسألة","يجعلان الإجابة صحيحة أيًّا كانت المعادلة المختارة","يُستخدمان فقط عندما تكون السرعة المتجهة سالبة","يساعدان على فهم المسألة وتحديد النظام الإحداثي وإشارات المعطيات"]'::jsonb, 'فهم', 'أهمية', 'سهل', 'الكتاب ص 49 — مراجعة 2-4 السؤال 33 (أهمية النماذج المصورة والفيزيائية)'),
('mcq', 2, 'يبدأ درّاج الحركة من موقع يبعد 30 m شرق إشارة مرور، ويتحرك نحو الغرب بسرعة ثابتة 5.0 m/s. رسم طالب نموذجًا مصورًا جعل فيه نقطة الأصل عند الإشارة والاتجاه الموجب نحو الشرق. ما القيمتان اللتان يعوّضهما في معادلة الحركة؟', null, null, '["$\\boldsymbol{d}_i = -30\\ \\text{m}$ و$\\boldsymbol{\\bar{v}} = +5.0\\ \\text{m/s}$","$\\boldsymbol{d}_i = +30\\ \\text{m}$ و$\\boldsymbol{\\bar{v}} = +5.0\\ \\text{m/s}$","$\\boldsymbol{d}_i = +30\\ \\text{m}$ و$\\boldsymbol{\\bar{v}} = -5.0\\ \\text{m/s}$","$\\boldsymbol{d}_i = -30\\ \\text{m}$ و$\\boldsymbol{\\bar{v}} = -5.0\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'تحديد الإشارات', 'متوسط', 'الكتاب ص 46 — مثال 3 (تحليل المسألة ورسمها، إيجاد الكمية المجهولة، تقويم الجواب)'),
('mcq', 3, 'يبيّن النموذج المصور الآتي طالبًا على طريق مستقيم بين منزله والمدرسة، ونقطة الأصل عند المنزل والاتجاه الموجب نحو المدرسة. بدأ التوقيت والطالب في الموقع المبيّن، ومشى نحو المدرسة بسرعة ثابتة 1.5 m/s. أيّ التمثيلات الرياضية الآتية يصف حركته؟', null, '[{"src":"qimg/phys1/c2l4-o16-sketch1.svg","alt":"نموذج مصور: خط أفقي يمثل طريقًا مستقيمًا، على طرفه الأيسر منزل وعلى طرفه الأيمن مدرسة، وتحت الطريق محور x مدرج بالمتر من 0 عند المنزل إلى 600 عند المدرسة كل 100 m، وسهم الاتجاه الموجب +x نحو اليمين (نحو المدرسة). الطالب نقطة زرقاء على الطريق فوق التدريج 200 m."}]'::jsonb, '["$\\boldsymbol{d} = (1.5\\ \\text{m/s})t + 200\\ \\text{m}$","$\\boldsymbol{d} = (1.5\\ \\text{m/s})t$","$\\boldsymbol{d} = (1.5\\ \\text{m/s})t + 600\\ \\text{m}$","$\\boldsymbol{d} = (-1.5\\ \\text{m/s})t + 200\\ \\text{m}$"]'::jsonb, 'تطبيق', 'تحويل نموذج إلى معادلة', 'متوسط', 'الكتاب ص 48 — تمثيل الحركة بالكلمات والمخططات والصور والجداول والمنحنيات ومعادلة الحركة المنتظمة'),
('mcq', 4, 'ما الترتيب المناسب لخطوات حل مسألة حركة؟', null, null, '["تمثيل رياضي وحل، ثم نموذج مصور، ثم نموذج فيزيائي، ثم تقويم الجواب","نموذج مصور، ثم نموذج فيزيائي، ثم تمثيل رياضي وحل، ثم تقويم الجواب","نموذج فيزيائي، ثم تقويم الجواب، ثم نموذج مصور، ثم تمثيل رياضي وحل","نموذج مصور، ثم تمثيل رياضي وحل، ثم تقويم الجواب، ثم نموذج فيزيائي"]'::jsonb, 'فهم', 'ترتيب خطوات', 'سهل', 'الكتاب ص 46 — مثال 3 (تحليل المسألة ورسمها، إيجاد الكمية المجهولة، تقويم الجواب)'),
('mcq', 5, 'أيّ مما يأتي يُعد تمثيلًا رياضيًا لحركة جسم؟', null, null, '["رسم الجسم وما حوله مع تحديد نقطة الأصل والاتجاه الموجب","سلسلة نقاط تبين مواقع الجسم في فترات زمنية متساوية","وصف حركة الجسم بالكلمات كما وردت في نص المسألة","معادلة الحركة المنتظمة بعد تعويض قيم الكميات المعلومة فيها"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 48 — تمثيل الحركة بالكلمات والمخططات والصور والجداول والمنحنيات ومعادلة الحركة المنتظمة'),
('mcq', 6, 'رسم طالب نموذجًا مصورًا لسيارة تتحرك نحو الغرب بسرعة ثابتة 4.0 m/s، واختار الاتجاه الموجب نحو الشرق، ثم كتب في التمثيل الرياضي $\boldsymbol{\bar{v}} = +4.0\ \text{m/s}$. ما الذي يجب تصحيحه؟', null, null, '["تغيير مقدار السرعة إلى 8.0 m/s مع إبقاء الإشارة موجبة","لا شيء؛ لأن السرعة المتجهة تُكتب موجبة دائمًا في المعادلة","جعل $\\boldsymbol{\\bar{v}} = -4.0\\ \\text{m/s}$ ليتفق مع النظام الإحداثي المختار","حذف النموذج المصور لأنه لا يتفق مع التمثيل الرياضي"]'::jsonb, 'تطبيق', 'اكتشاف خطأ', 'متوسط', 'الكتاب ص 46 — مثال 3 (تحليل المسألة ورسمها، إيجاد الكمية المجهولة، تقويم الجواب)'),
('mcq', 7, 'يبيّن النموذج المصور الآتي طالبًا على طريق مستقيم بين منزله والمدرسة، ونقطة الأصل عند المنزل والاتجاه الموجب نحو المدرسة. بدأ التوقيت والطالب في الموقع المبيّن، ومشى عائدًا إلى المنزل بسرعة ثابتة 1.5 m/s. بعد كم ثانية يصل إلى المنزل؟', null, '[{"src":"qimg/phys1/c2l4-o16-sketch2.svg","alt":"نموذج مصور: خط أفقي يمثل طريقًا مستقيمًا، على طرفه الأيسر منزل وعلى طرفه الأيمن مدرسة، وتحت الطريق محور x مدرج بالمتر من 0 عند المنزل إلى 600 عند المدرسة كل 100 m، وسهم الاتجاه الموجب +x نحو اليمين (نحو المدرسة). الطالب نقطة زرقاء على الطريق فوق التدريج 450 m."}]'::jsonb, '["$100\\ \\text{s}$","$300\\ \\text{s}$","$675\\ \\text{s}$","$400\\ \\text{s}$"]'::jsonb, 'تطبيق', 'حل باستخدام النماذج', 'صعب', 'الكتاب ص 48 — تمثيل الحركة بالكلمات والمخططات والصور والجداول والمنحنيات ومعادلة الحركة المنتظمة'),
('essay', 1, 'تتدحرج كرة على أرض مستوية بسرعة ثابتة نحو جدار. (أ) ما أهمية عمل نموذج مصور ونموذج فيزيائي للحركة قبل البدء بحل معادلة ما؟ (ب) صف ما يتضمنه كل من النموذج المصور والنموذج الفيزيائي والتمثيل الرياضي لحركة هذه الكرة.', null, null, null, 'تطبيق', 'تصميم تمثيلات', 'متوسط', 'الكتاب ص 49 — مراجعة 2-4 السؤال 33 (أهمية النماذج المصورة والفيزيائية)'),
('essay', 2, 'لحظة بدء التوقيت كانت سيارة على بُعد 50 m غرب إشارة مرور، وكانت تتحرك نحو الشرق بسرعة متجهة ثابتة 10 m/s. (أ) صمّم نموذجًا مصورًا للمسألة، محددًا نقطة الأصل والاتجاه الموجب. (ب) صمّم النموذج الفيزيائي للحركة بنقطة كل 1.0 s خلال أول 4.0 s. (ج) اكتب التمثيل الرياضي، ثم أوجد متى تصل السيارة إلى الإشارة، وموقعها بعد 8.0 s. (د) قوّم جوابك.', null, null, null, 'تطبيق', 'تصميم تمثيلات وحل', 'صعب', 'الكتاب ص 48 — تمثيل الحركة بالكلمات والمخططات والصور والجداول والمنحنيات ومعادلة الحركة المنتظمة'),
('essay', 3, 'يبدأ خالد الجري من نقطة الأصل نحو الشرق بسرعة ثابتة 4.0 m/s، وفي اللحظة نفسها يبدأ سعد الجري من موقع يبعد 300 m شرق نقطة الأصل نحو الغرب بسرعة ثابتة 2.0 m/s، على الطريق المستقيم نفسه. صمّم نموذجًا مصورًا ونموذجًا فيزيائيًا وتمثيلًا رياضيًا لحركتي العدّاءين، ثم استخدمها لإيجاد متى وأين يلتقيان.', null, null, null, 'تطبيق', 'تصميم تمثيلات وحل', 'صعب', 'الكتاب ص 48 — تمثيل الحركة بالكلمات والمخططات والصور والجداول والمنحنيات ومعادلة الحركة المنتظمة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L4-O16') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'النموذجان يساعدان على فهم المسألة وتحديد النظام الإحداثي وإشارات المعطيات: فرسم النموذج المصور (الموقف ونقطة الأصل والاتجاه الموجب) والنموذج الفيزيائي (المخطط التوضيحي للحركة بمتجهاته) يوضح ما يحدث، ويحدد المعلوم والمجهول وإشارات الكميات، فيُختار التمثيل الرياضي الصحيح وتُعوَّض القيم بإشاراتها الصحيحة.', '["النماذج تمهد للحل الرياضي ولا تلغيه؛ فالمعادلة ما زالت ضرورية لإيجاد المجهول.","اختيار المعادلة الصحيحة وتعويض القيم بإشاراتها ما زالا ضروريين.","النماذج مفيدة في كل مسائل الحركة لا في حالة الإشارة السالبة فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.289Z"}'::jsonb),
('mcq', 2, 2, 'وفق النظام الإحداثي المختار: الدرّاج يبدأ شرق نقطة الأصل فـ $\boldsymbol{d}_i = +30\ \text{m}$، ويتحرك نحو الغرب فـ $\boldsymbol{\bar{v}} = -5.0\ \text{m/s}$؛ فتكون المعادلة $\boldsymbol{d} = (-5.0\ \text{m/s})t + 30\ \text{m}$.', '["عكس الإشارتين؛ فالدرّاج يبدأ شرق نقطة الأصل (موجب) ويتحرك نحو الغرب (سالب).","أهمل أن الحركة نحو الغرب، أي في الاتجاه السالب.","","جعل الموقع الابتدائي سالبًا مع أن الدرّاج يبدأ شرق الإشارة (في الاتجاه الموجب)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.290Z"}'::jsonb),
('mcq', 3, 0, 'من النموذج المصور: $\boldsymbol{d}_i = +200\ \text{m}$، والحركة نحو المدرسة (الاتجاه الموجب) فـ $\boldsymbol{\bar{v}} = +1.5\ \text{m/s}$؛ إذن $\boldsymbol{d} = (1.5\ \text{m/s})t + 200\ \text{m}$.', '["","أهمل الموقع الابتدائي، فافترض أن الطالب بدأ من المنزل (نقطة الأصل).","استعمل موقع المدرسة موقعًا ابتدائيًا، والطالب بدأ عند 200 m.","جعل السرعة سالبة، مع أن الطالب يتحرك نحو المدرسة، أي في الاتجاه الموجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (72%)"}],"at":"2026-11-18T12:34:59.290Z"}'::jsonb),
('mcq', 4, 1, 'يُبدأ بتحليل المسألة ورسمها: نموذج مصور للموقف ونظامه الإحداثي، ثم نموذج فيزيائي (المخطط التوضيحي للحركة)، ثم التمثيل الرياضي وإيجاد الكمية المجهولة، وأخيرًا تقويم الجواب (الوحدات والإشارات).', '["بدأ بالحل الرياضي قبل فهم المسألة ورسمها، والنماذج تُرسم أولًا لتوجيه الحل.","","لا يمكن تقويم الجواب قبل الحصول عليه.","النموذج الفيزيائي يُرسم قبل الحل ليساعد على تحديد الإشارات، لا بعده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:59.290Z"}'::jsonb),
('mcq', 5, 3, 'التمثيل الرياضي يعبر عن الحركة بعلاقة رياضية، مثل معادلة الحركة المنتظمة $\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i$ بعد تعويض قيم السرعة المتجهة المتوسطة والموقع الابتدائي.', '["هذا نموذج مصور للموقف لا تمثيل رياضي.","هذا نموذج الجسيم النقطي، وهو نموذج فيزيائي.","هذا تمثيل لفظي للحركة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-18T12:34:59.290Z"}'::jsonb),
('mcq', 6, 2, 'الحركة نحو الغرب تعاكس الاتجاه الموجب المختار (الشرق)، فإشارة السرعة المتجهة سالبة: $\boldsymbol{\bar{v}} = -4.0\ \text{m/s}$؛ ويجب أن تتفق التمثيلات كلها مع النظام الإحداثي نفسه.', '["المقدار صحيح (4.0 m/s)؛ الخطأ في الإشارة فقط.","السرعة المتجهة تحمل إشارة الاتجاه؛ أما السرعة المتوسطة فهي التي لا تكون سالبة.","","النموذج المصور صحيح، والمعادلة هي التي يجب أن تتفق معه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.290Z"}'::jsonb),
('mcq', 7, 1, 'من النموذج: $\boldsymbol{d}_i = +450\ \text{m}$ و$\boldsymbol{\bar{v}} = -1.5\ \text{m/s}$، فالتمثيل الرياضي $\boldsymbol{d} = (-1.5\ \text{m/s})t + 450\ \text{m}$. عند المنزل $\boldsymbol{d} = 0$: $t = \frac{450}{1.5} = 300\ \text{s}$.', '["حسب زمن الوصول إلى المدرسة ($\\frac{600 - 450}{1.5}$) لا إلى المنزل.","","ضرب الموقع الابتدائي في السرعة بدل القسمة عليها.","قسم المسافة الكلية بين المنزل والمدرسة ($\\frac{600}{1.5}$) ولم يبدأ من موقع الطالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (72%)"}],"at":"2026-11-18T12:34:59.291Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) تساعد النماذج على تصور الموقف وفهمه، واختيار نقطة الأصل والاتجاه الموجب، وتحديد المعلوم والمجهول وإشاراتها، فيسهل اختيار المعادلة المناسبة وتجنب أخطاء الإشارة. (ب) النموذج المصور: رسم للكرة والجدار والأرض، مع محور تحدد عليه نقطة الأصل (مثلًا عند موقع الكرة الابتدائي) والاتجاه الموجب نحو الجدار. النموذج الفيزيائي: نموذج الجسيم النقطي بنقاط متساوية التباعد (لأن السرعة ثابتة) ومتجهات سرعة حمراء متساوية الطول تشير نحو الجدار. التمثيل الرياضي: $\boldsymbol{d} = \boldsymbol{\bar{v}}t + \boldsymbol{d}_i$ بعد تعويض القيم، أو منحنى (الموقع – الزمن) خطًا مستقيمًا.', '["أهمية النماذج: الفهم وتحديد النظام الإحداثي والإشارات","النموذج المصور مع نقطة الأصل والاتجاه الموجب","النموذج الفيزيائي: نقاط متساوية التباعد ومتجهات متساوية","التمثيل الرياضي: معادلة الحركة المنتظمة أو منحنى خطي"]'::jsonb, '[]'::jsonb, '[{"element":"الأهمية","marks":1},{"element":"النموذج المصور","marks":1},{"element":"النموذج الفيزيائي","marks":1},{"element":"التمثيل الرياضي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أهمية واضحة ووصف صحيح للتمثيلات الثلاثة"},{"level":"2–3 درجات","description":"إغفال النظام الإحداثي أو خطأ في وصف تمثيل"},{"level":"1 درجة","description":"ذكر الأهمية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين النموذج المصور والنموذج الفيزيائي","رسم متجهات متزايدة الطول لسرعة ثابتة","إغفال تحديد نقطة الأصل والاتجاه الموجب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.291Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) طريق أفقي عليه الإشارة عند نقطة الأصل، والاتجاه الموجب نحو الشرق، والسيارة عند $-50\ \text{m}$. (ب) نقاط عند $-50$، $-40$، $-30$، $-20$، $-10\ \text{m}$ متساوية التباعد (10 m)، فوقها متجهات سرعة حمراء متساوية الطول نحو الشرق. (ج) $\boldsymbol{d} = (10\ \text{m/s})t - 50\ \text{m}$؛ عند الإشارة $\boldsymbol{d} = 0$: $t = 5.0\ \text{s}$؛ وعند $t = 8.0\ \text{s}$: $\boldsymbol{d} = 80 - 50 = +30\ \text{m}$، أي 30 m شرق الإشارة. (د) الوحدات صحيحة (m وs)، والإشارة الموجبة للموقع بعد 8.0 s منطقية لأن السيارة تجاوزت الإشارة نحو الشرق بعد 5.0 s.', '["نموذج مصور بنقطة أصل واتجاه موجب واضحين","نموذج فيزيائي بنقاط متساوية التباعد ومتجهات نحو الشرق","التمثيل الرياضي $\\boldsymbol{d} = (10\\ \\text{m/s})t - 50\\ \\text{m}$","زمن الوصول 5.0 s والموقع بعد 8.0 s يساوي +30 m","تقويم الوحدات والإشارات"]'::jsonb, '["$\\boldsymbol{d}_i = -50\\ \\text{m}$، $\\boldsymbol{\\bar{v}} = +10\\ \\text{m/s}$","$0 = (10\\ \\text{m/s})t - 50\\ \\text{m} \\Rightarrow t = 5.0\\ \\text{s}$","$\\boldsymbol{d} = (10\\ \\text{m/s})(8.0\\ \\text{s}) - 50\\ \\text{m} = +30\\ \\text{m}$"]'::jsonb, '[{"element":"النموذج المصور","marks":1},{"element":"النموذج الفيزيائي","marks":1},{"element":"التمثيل الرياضي","marks":1},{"element":"الحلول","marks":2},{"element":"التقويم","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تمثيلات متسقة وحلول صحيحة وتقويم سليم"},{"level":"4–5 درجات","description":"خطأ في إشارة أو نقص في أحد النماذج"},{"level":"1–3 درجات","description":"نموذج أو حل واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الموقع الابتدائي +50 m","رسم نقاط النموذج الفيزيائي متزايدة التباعد","حساب الموقع بعد 8.0 s بإهمال الموقع الابتدائي (80 m)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.291Z"}'::jsonb),
('essay', 3, null::int, null, null, 'النموذج المصور: طريق أفقي، نقطة الأصل عند موقع خالد الابتدائي، والاتجاه الموجب نحو الشرق، وسعد عند $+300\ \text{m}$. النموذج الفيزيائي: لخالد نقاط متساوية التباعد ومتجهات حمراء نحو الشرق، ولسعد نقاط متساوية التباعد بنصف تباعد نقاط خالد ومتجهات نحو الغرب طولها نصف طول متجهات خالد. التمثيل الرياضي: $\boldsymbol{d}_K = (4.0\ \text{m/s})t$، $\boldsymbol{d}_S = (-2.0\ \text{m/s})t + 300\ \text{m}$. عند الالتقاء $\boldsymbol{d}_K = \boldsymbol{d}_S$: $4.0t = -2.0t + 300$ فـ $t = 50\ \text{s}$، والموقع $\boldsymbol{d} = 4.0 \times 50 = 200\ \text{m}$ شرق نقطة الأصل. (ويمكن تمثيلهما بمنحنى (الموقع – الزمن) يتقاطع فيه الخطان عند (50 s، 200 m)).', '["نموذج مصور بنقطة أصل واتجاه موجب","نموذج فيزيائي: تباعد النقاط وأطوال المتجهات واتجاهاتها لكل عدّاء","معادلتا الحركة بإشاراتهما الصحيحة","زمن الالتقاء 50 s","موقع الالتقاء 200 m"]'::jsonb, '["$\\boldsymbol{d}_K = (4.0\\ \\text{m/s})t$","$\\boldsymbol{d}_S = (-2.0\\ \\text{m/s})t + 300\\ \\text{m}$","$(4.0\\ \\text{m/s})t = (-2.0\\ \\text{m/s})t + 300\\ \\text{m} \\Rightarrow t = \\frac{300\\ \\text{m}}{6.0\\ \\text{m/s}} = 50\\ \\text{s}$","$\\boldsymbol{d} = (4.0\\ \\text{m/s})(50\\ \\text{s}) = 200\\ \\text{m}$"]'::jsonb, '[{"element":"النموذج المصور","marks":1},{"element":"النموذج الفيزيائي","marks":1},{"element":"التمثيل الرياضي","marks":2},{"element":"زمن الالتقاء وموقعه","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تمثيلات متسقة ومعادلتان صحيحتان وزمن وموقع صحيحان"},{"level":"4–5 درجات","description":"خطأ في إشارة سرعة سعد أو نقص في نموذج"},{"level":"1–3 درجات","description":"كتابة معادلة واحدة صحيحة أو نموذج واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل سرعة سعد موجبة فلا يلتقيان","قسمة 300 على 2.0 أو 4.0 وحدها بدل مجموع السرعتين","حساب موقع الالتقاء من معادلة سعد دون إضافة الموقع الابتدائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.291Z"}'::jsonb)
